INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198080746', 'Barraca Menina Rosa Tenda Princesa Anti-Mosquito - Poliéster Premium - 130cm Inmetro', 'A Barraca Infantil Encantada Rosa Dupla é uma tenda estilo castelo, ideal para criar um espaço mágico e seguro para crianças. Com design fofo, cores suaves e funcionalidades práticas, é fácil de montar, dobrável e inclui cortina anti-mosquito e saco de armazenamento. Perfeita para estimular a imaginação e a diversão. Tópicos Técnicos: Material: Tecido Oxford e hastes de fibra de vidro. Tamanho: 130 x 100 x 130 cm. Cores: Rosa e azul. Idade: Todas as idades. Design: Dobrável, leve e compacta. Cortina: Anti-mosquito inclusa. Acessórios: Saco de armazenamento e hastes de apoio. Uso: Quarto, sala, áreas externas. Conclusão: A Barraca Infantil Encantada Rosa Dupla é uma opção encantadora e prática para proporcionar momentos de diversão e criatividade, criando um espaço mágico para as crianças.', 149.0, 116.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5emlx2q03np9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F22198080746', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793491726', 'Motoca Triciclo Velotrol + Game Aplicativo 3D 🚴‍♂️ - Infantil C/ Pedal Empurrador Protetor - QUEEN SHOP', 'NESSE PEDIDO VOCÊ GANHARÁ O GAME CORRIDA KENDY 6 MODOS DE JOGO, CENÁRIO 3D E SUPER DIVERTIDO. EXCLUSIVO NA QUEEN SHOP 🚴‍♂️ 🚴‍♂️ 🎉👦 A Motoca Infantil é um triciclo superdivertido para crianças de 12 meses a 3 anos! Certificado pelo Inmetro, é seguro e estimula o desenvolvimento saudável. 🌟 Características 1. Tamanho: 88 cm x 42,5 cm x 88 cm 📏 2. Suporte: Até 16 kg ⚖️ 3. Certificação: Inmetro 📝 4. Idade: 12 meses a 3 anos 👶 Recursos Divertidos! 1. Painel interativo com som 🎵 2. Modelo reforçado 💪 3. Protetor de corpo 🛡️ 4. Haste para empurrar 🔄 5. Suporte para os pés 👣 Benefícios Mágicos! 1. Desenvolve coordenação motora 🤸 2. Estimula imaginação e criatividade 🎨 3. Autoconfiança 💪 4. Entretenimento educativo 📚 5. Segurança garantida 🔒', 139.9, 120.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbmdi1n1mm48e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F22793491726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793656010', 'Kit Limpeza Para Carabinas Pressão Cal 5,5 E 6,0mm - Fxr', 'O Kit Limpeza Para Carabinas de Pressão Fxr é essencial para a manutenção de carabinas calibres 5,5 e 6,0 mm, garantindo um desempenho eficiente e prolongando a vida útil do equipamento. Composto por 10 peças, o kit inclui escovas e varetas que facilitam a remoção de resíduos de chumbo, evitando a deterioração do cano e assegurando um funcionamento ideal da carabina. Além disso, o estojo proporciona um armazenamento prático e seguro das ferramentas. A limpeza periódica com este kit é indicada não apenas para carabinas, mas também para armas de fogo de calibre .22, oferecendo versatilidade para os usuários. As escovas em aço e nylon, juntamente com as varetas em metal, garantem uma limpeza eficaz e cuidadosa, preservando a integridade das superfícies internas. O recipiente para óleo e os panos de limpeza complementam o conjunto, assegurando uma manutenção completa. Ficha Técnica - Conteúdo: 01 escova de aço calibre .22/5.5 e 6mm - Conteúdo: 01 Escova de câmara calibre .22/5.5 e 6mm - Conteúdo: 01 escova dupla de Nylon - Conteúdo: 01 recipiente para óleo - Conteúdo: 04 Varetas em metal - Conteúdo: 01 Ponta vazada - Conteúdo: 01 pacote com 25 uni. panos de limpeza - Conteúdo: 01 estojo', 90.12, 65.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-m14ah1czs36h1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F22793656010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202090523', 'Esfera munição BBs Rossi 0,12G Airsoft 6,0MM 150und', 'As Esferas Plásticas Rossi 0,12g para Airsoft são projetadas para proporcionar alta precisão e desempenho superior. Com 150 unidades por embalagem, essas esferas contam com um acabamento de alto padrão, garantindo um funcionamento suave nos equipamentos de Airsoft. A ausência de rebarbas melhora a aerodinâmica, contribuindo para tiros mais precisos e consistentes. Fabricadas em PVC, essas esferas são compatíveis com todos os equipamentos de Airsoft, tornando-as uma escolha versátil para praticantes do esporte. Seu calibre de 6 mm e peso de 0,12 g proporcionam a balance ideal entre velocidade e controle durante as partidas. Ficha Técnica - Material: PVC - Calibre: 6 mm - Peso da Esfera: 0,12 g - Embalagem: 150 unidades - Peso da Embalagem: 20 g', 29.39, 29.39, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-81zw3-mid3mchzqh388a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F58202090523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199266748', 'Perfume Feminino Rebelle HINODE 75ml', 'O Rebelle Deo Colônia Hinode é um perfume feminino marcante que traduz os contrastes da mulher jovem, moderna e cheia de personalidade. Irreverente sem perder a elegância, Rebelle foge do óbvio e revela uma fragrância envolvente, sofisticada e surpreendente. Sua composição abre com notas frescas e luminosas de bergamota, combinadas à delicadeza da orquídea e do lírio do vale, criando uma primeira impressão feminina e elegante. No coração, um bouquet floral refinado de rosa, aliado ao toque aveludado do musk e à sofisticação do vetiver, traz equilíbrio e charme. Já no fundo, a fragrância se torna mais intensa e acolhedora, com amêndoa, baunilha e o caráter marcante do patchouli, garantindo sensualidade e fixação prolongada. Ideal para mulheres que gostam de perfumes florais confortáveis, adocicados na medida certa e perfeitos tanto para o dia a dia quanto para ocasiões especiais. Família Olfativa: Floral Confortável Categoria: Perfume Feminino / Deo Colônia Sensação: Feminino, sofisticado, envolvente e moderno Notas Olfativas: Saída: Bergamota, Orquídea, Lírio do Vale Corpo: Rosa, Musk, Vetiver Fundo: Amêndoa, Baunilha, Patchouli Produto 100% original Hinode.', 169.9, 169.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820lr-mqf0wz8g9b0h13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F18199266748', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203371403', 'Kit 2 Pulverizadores Borrifadores Manuais Cinza 450ML', 'PRODUTO NOVO Quer praticidade para irrigar plantas e hortaliças no dia a dia? Características do Produto – Marca: Tramontina – Referência: 78604046 – Capacidade: 450 ml – Material: Plástico de alta resistência – Cor: Transparente – Bico pulverizador regulável – Leve, versátil e ergonômico – Dimensões: 17 x 12 x 10 cm – Peso: 350 g – Itens inclusos: 1 pulverizador manual 450 ml Por que escolher este produto – Ideal para horta, jardim e plantas em vasos – Corpo transparente facilita o controle do nível de líquido – Regulagem do jato conforme a necessidade – Resistente e de fácil manuseio – Compacto e leve para uso diário Dicas de Uso – Utilize para pulverizar água ou soluções de cuidado para plantas – Ajuste o jato para regar de forma delicada ou mais intensa – Mantenha limpo após o uso para maior durabilidade – Guarde em local protegido do sol direto Perguntas Frequentes – Qual a capacidade do pulverizador? Possui capacidade de 450 ml. – O jato pode ser regulado? Sim, o bico é ajustável para diferentes tipos de pulverização. – O corpo é transparente? Sim, isso facilita visualizar o nível do líquido. Tenha mais praticidade no cuidado diário das suas plantas com o pulverizador Tramontina 450 ml.', 44.59, 38.55, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mjiw2sbgkkcne9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552175911%2F58203371403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17586004985', 'Fraqueira Grande Vega 2T Azul', 'Combina com qualquer destino. As frasqueiras da linha Vega surpreender com o design, padronagem de ondas moldadas em ABS texturizado de alta resistência. Se por um lado ela é linda e delicada, por outro, é super-resistente. Além disso, é cheia de astral e combina bem com qualquer destino que peça um colorido extra. Possui a Altura: 27 Cm - Largura: 34 Cm - Profundidade: 16 Cm - Peso: 1,29 KG - Capacidade Total: 15 L', 169.9, 169.9, NULL, 'Travel & Luggage > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rcdb-lqw0ptuvil4bec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867958784%2F17586004985', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193342046', 'Booster Facial Efeito Tensor Routine Dermo', 'Sobre o produto: O Booster Facial Efeito Tensor atua como um bioestimulador de colágeno, reduzindo rugas, flacidez e linhas de expressão para deixar a pele mais macia e hidratada. Sua fórmula de textura leve e secagem rápida conta com uma combinação de silício e ativos hidratantes, que auxiliam na firmeza, na elasticidade e no contorno do rosto. Principais ativos: Silício Orgânico com Ácido Algínico: Combinação de componente extraído de algas marrons com silício orgânico que atua na estrutura da pele, auxiliando no aumento de sua firmeza, densidade e elasticidade. Trehalose: Componente que auxilia na reidratação da pele, ajudando a reter a umidade e a manter a hidratação por mais tempo. Betaína: Ativo 100% natural e de origem sustentável, obtido através do reaproveitamento de matéria-prima. Possui propriedades hidratantes que ajudam a manter o equilíbrio de água nas células. Principais benefícios: - Melhora a luminosidade da pele; - Reduz a flacidez; - Auxilia na firmeza da pele (efeito lifting); - Hidrata e revitaliza a pele; - Atua no rejuvenescimento da pele; - Melhora a firmeza e a textura; - Possui rápida absorção; - Auxilia na melhora do contorno do rosto; - Ajuda no estímulo à produção de colágeno e ácido hialurônico. Resultados dos testes e estudos: Resultados visíveis e comprovados a partir de 26 dias *: 100% dos participantes perceberam redução das rugas e linhas de expressão; 100% dos participantes perceberam melhora da firmeza da pele; 100% dos participantes perceberam efeito lifting, melhora da hidratação e pele revitalizada; 94% dos participantes perceberam redução da flacidez da pele; 94% dos participantes perceberam o rejuvenescimento da pele e mais luminosa. *Resultado obtido através de teste clínico em instituto independente', 156.9, 156.9, NULL, 'Beauty > Skincare > Acne Treatment', 'https://cf.shopee.com.br/file/br-11134207-820ld-mqwc6h7ksn4540', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F23193342046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45352625759', 'Uma Zebra Fora Do Padrão | Paula Browne', 'Livro Uma Zebra Fora Do Padrão | Paula Browne Paula BrowneConheça uma zebra muito especial, que não se encaixa em nenhum padrão. Ela é bagunceira, mas adora se arrumar; leitora voraz e também escritora; animada e, ao mesmo tempo, dorminhoca. Com sua cabeça de vento e imaginação sem fim, ela vive cercada por cadernos de listas que enumeram desde coisas amarelas até rimas que não combinam. Esta história é um convite à brincadeira e à descoberta, mostrando que ser diferente é o que nos torna verdadeiramente únicos. Através das listas criativas da zebra, os pequenos leitores são incentivados a observar, classificar e criar, celebrando suas próprias particularidades com leveza e humor. O que você vai encontrar neste livro: Uma protagonista única e carismática que celebra a diferençaCadernos de listas criativas que estimulam a observação e a imaginaçãoNarrativa divertida que incentiva as crianças a aceitarem sua própria singularidadeIdeal para: Crianças que se sentem diferentes ou fora do padrãoPequenos leitores curiosos e cheios de imaginaçãoPresentes que celebram a individualidade e a criatividadeAdquira já "Uma Zebra Fora do Padrão" e descubra como ser diferente pode ser a maior aventura – e a mais divertida lista a se fazer!', 48.91, 48.91, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-82276-mhuslcbph6gzdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F45352625759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
