INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49751009561', 'Tênis Infantil Feminino Sem Cadarço Calçados Sapatenis Calce facil Unisse Tenis Menino', 'Tênis Infantil sem Cadarço Jogging Infantil Aventuras cheias de conforto e estilo. O Tênis Jogging foi criado para os meninos super descolados e que adoram se divertir. Ideal para passeios em família, e para a prática de esportes ou para ir à escola. O tênis possui características esportivas. Seu solado possui pontos de flexão, que tornam o caminhar do seu filho mais saudável. Cabedal em Mash Respirável, o tênis Jogging permite maior respiração aos pezinhos dos pequenos. Por ser um tênis esportivo, ele cai perfeitamente em um look esportivo-casual. Composição do Calçado: Material: Têxtil Forro: Têxtil Palmilha: EVA Sola: Micro Expandido Tabela de Medidas: Nº 20 – 13,2 CM Nº 21 – 13,8 CM Nº 22 – 14,9 CM Nº 23 – 15,3 CM Nº 24 – 16,2 CM Nº 25 – 16,6 CM Nº 26 – 17,7 CM Nº 27 – 18,0 CM Nº 28 – 18,9 CM Nº 29 – 19,1 CM Nº 30 – 20,0 CM Nº 31 – 20,3 CM Nº 32 – 21,6 CM Nº 33 – 21,9 CM Nº 34 – 22,9 CM Nº 35 – 23,0 CM', 98.9, 52.98, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgs17dj7jhtwa7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F49751009561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40415545856', 'Sandalia Ortopedica Modare Ultraconforto Chinelo Plataforma Massageadora Feminina', 'Descubra o conforto e elegância na Sandália Modare feita em material sintético de alta qualidade, caracterizada por sua sola reta e alta, que oferece elevação uniforme ao longo de todo o pé. Além de ser fácil de limpar, a sandália é leve e possui uma palmilha acolchoada, que garante uma pisada macia e confortável enquanto o solado proporciona leveza e flexibilidade. Ela conta com duas tiras largas na parte superior com detalhes dourados, que proporcionam um caminhar mais seguro. Essas características fazem da Sandália Flatforme Modare, uma ótima escolha para quem busca estilo e conforto no dia a dia. Composição do Calçado: Marca: Modare Material: Sintético PU Solado: Borracha Fecho: De Contato Altura do Salto: 3,0 cm Guia Tamanhos: Nº 34 – 22,5 CM Nº 35 – 23,3 CM Nº 36 – 24,0 CM Nº 37 – 24,5 CM Nº 38 – 25,3 CM Nº 39 – 26,0 CM', 175.9, 112.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Health Slippers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdyvmo2w29duba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F40415545856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
