INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199610571', 'Mangueira Respiro Óleo FIAT PUNTO 1.4 8v FIRE EVO 2013/2017 - 89605 - 4204', 'Mangueira Respiro Óleo FIAT PUNTO 1.4 8v FIRE EVO 2013/2017 1.4 8v FIRE EVO (Medida: 17cm x 39cm)Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 50.88, 50.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mq1y1ozw0zkdd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21199610571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
