INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993493164', '2x Soquete Farol Lâmpada H7 C/fio 1,5mm Super Branca E Xenon', 'Mundo Peças, Empresa com mais de 25 anos no mercado de peças para reposição automotiva, com garantia de preço justo, atendimento sempre dando preferência a Qualidade. Descrição 2x Soquete para Lâmpada H7 em Porcelana com Fio de 1,5mm Suporta Lâmpadas de 100W ( Super Branca Ou Comum ), XENON e Lâmpadas de 55W Compatível com todos os Carros, Motos e Caminhões que utilizam Lâmpada H7 Por ser fabricado em Porcelana e conexões de Latão de alta resistência ele não derrete como os soquetes Plásticos encontrados no mercado. Foi dimensionado para Lâmpadas de alta potência, por isso pode ser usado em sistema que utilizam lâmpadas de 55W. COMPRE DIRETO DO DISTRIBUIDOR COM TOTAL GARANTIA NA ENTREGA E NO PÓS VENDA, TIRE SUAS DUVIDAS DIRETO COM PESSOAS ESPECIALIZADAS NO RAMO AUTOMOTIVO!!', 26.5, 26.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7repb-m1u2lz2lidme66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397020362%2F22993493164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598364900', 'Estator Honda Cg Fan Titan 125 2000 2001 2002 XRL 125 Original Magnetron', 'ESTATOR ORIGINAL MAGNETRON (90271660) - PREÇO REFERENTE A 01 PEÇA APLICAÇÃO HONDA CG FAN TITAN 125 KS/ES 99 2000 2001 2002 XRL 125 2000 O ESTATOR TEM A FUNÇÃO DE GERAR ENERGIA PARA O SISTEMA DE CARGA DE BATERIA E ILUMINAÇÃO (PAINEL, FAROL, LANTERNA TRASEIRA, PISCAS DIANTEIROS E TRASEIROS). ** GARANTIA DE 03 MESES DO FABRICANTE, COM NOTA FISCAL ** ***RECOMENDAMOS QUE A INSTALAÇÃO SEJA REALIZADA POR PROFISSIONAIS ESPECIALIZADOS!*** NÓS DA EQUIPE GOLDSPEED, ESTAMOS AGUARDANDO A SUA COMPRA! A instalação deste estator é simples, permitindo que você retome a estrada rapidamente. Com um design que respeita as especificações do fabricante, ele se integra perfeitamente ao sistema elétrico de sua moto. Não comprometa a qualidade do seu transporte; escolha um estator que atenda às suas necessidades e garanta uma experiência de pilotagem superior.', 199.9, 102.86, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd3o-m7wc04ue2hex1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F975729867%2F22598364900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599303593', 'Válvula Solenóide Fiat Uno 2007 a 2013 - 1339234 - T140002', 'Válvula Solenóide Fiat Uno 2007 a 2013 1339234 T140002 (Furgoneta) - Motor 1.3 8v Flex - (2 Vias) Problemas mais comuns no sistema de partida a frio Estão relacionados ao combustível ruim. A utilização de um combustível de baixa qualidade faz com que as vias de passagem da solenoide venham a entupir e não permitir a passagem do combustível. Outro problema no sistema pode ser a falta do uso. O combustível resseca os locais de passagem, fazendo com que a falta de lubrificação venha a tornar o material mais frágil, pois algumas partes do sistema são feitas de plástico.', 73.3, 73.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-822xk-mo9u7ttji6fj55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20599303593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
