INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8327021987', 'Empate de Aço 40Lbs 18kg 10m Marine Sports', 'Empate ou cabo de aço trançado em aço inox de alta resistência, revestido com nylon. Utilizado para fazer encastoados, chicotes, pernadas e empates para pesca, acompanha 70 luvas ideais para o cabo. ESPECIFICAÕES Marca: Marine Sports Modelo: Cabo de aço inox Capacidade: 40lbs - 18,14kgs Cor: Chumbo Cartela Com 10 metros de cabo Acompanha 70 luvas', 19.44, 19.44, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/sg-11134201-7rbn1-lp5l0aj245ne62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F8327021987', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897418200', 'Tonalizante Banho De Brilho Keraton Louro Bege Trigo', 'Banho de Brilho Keraton, Realça e ilumina a cor dos cabelos opacos, desbotados e sem vida. Trata e recupera os cabelos, de forma suave e sem agredir as fibras pois é enriquecido com aminoácido da Cistina. Por não conter amônia nem oxidantes pode ser aplicado imediatamente após qualquer processo químico. Keraton Banho de Brilho trata enquanto colore. Resiste até 8 lavagens. Não contém: Amônia, Etanolaminas, Oxidantes, Emulsões. Modo de uso: Lave os cabelos com shampoo e não utilize condicionador. Retire o excesso de água com uma toalha, coloque as luvas e aplique o produto por toda a cabeça de forma uniforme massageando suavemente. Aguarde até 30 minutos e enxágue bem até eliminar todo o excesso do produto. Para melhores resultados faça teste de mecha para determinar o tempo de pausa. #html-body [data-pb-style="646BA64672D7F"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64672D94"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 57.07, 57.07, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbmn-lmgg8ycyw1mzb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18897418200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
