INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897623421', 'Creme de Hidratação Monange Firmador Q10 Vitamina C 400ml', '#html-body [data-pb-style=T8AXITC]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}Hidratante Monange Firmador Q10 Vitamina C + E – Pele Normal a Seca com Ação Desodorante 400ml aumenta o colágeno da pele, possui ação antissinais e previne a flacidez. Dermatologicamente testado, o produto já começa a dar resultados em até 2 semanas de uso constante, recomenda-se que ele seja aplicado 2 vezes ao dia. Além disso, com ativos provenientes da laranja, o hidratante nutre até a segunda camada da derme, possui uma textura cremosa e pode ser utilizado em todos os tipos de pele. Modo de Uso: A melhor hora para aplicar o hidratante é depois do banho - neste momento a pele absorve melhor o produto e todos os seus nutrientes! Sendo assim, logo depois da higiene, com o corpo ainda ligeiramente úmido, passe a loção ou creme de hidratação em toda a pele, dando atenção, principalmente, às regiões mais ressecadas.', 37.69, 37.69, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rccw-lr5zemzhjouabd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18897623421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10942340734', 'Espátula Multiuso de Plástico 20cm Lisa - Castor', 'A Espátula plástica multiuso 20 cm da Castor é ideal para criação de efeitos decorativos com texturas lisas ou granuladas. Indispensável no manuseio de gesso, rejunte comum, rejunte à base de epóxi, massa corrida, resinas acrílicas, vinílicas e produtos similares. Apresenta grande flexibilidade na hora da aplicação. CARACTERÍSTICAS Material da chapa: Plástico resistente Material do Cabo: Plástico Uso Indicado: Pequenos reparos com massa corrida, aplicação de rejunte epóxi, gesso, argamassa, colas, resinas, etc. Auxiliam na aplicação de papel de parede e podem ser utilizadas na criação de efeitos decorativos. Também utilizada para aplicação de insulfilm. Vantagens: Pode ser usada com produtos à base de água e solventes. Não empena, não racha e é fácil de limpar e fácil de armazenar. Código do fábricante: 290 Limpeza e conservação: Logo após o uso, retirar os resíduos do produto utilizado. Produtos à base de água, lavar com água e sabão. Produtos sintéticos, lavar com solvente adequado e depois com água e sabão. Secar bem e guardar em local arejado. FERRAMENTAS QUE GARANTEM RESULTADOS PRECISOS Perfeição e versatilidade, tudo o que você precisa em uma só ferramenta. A Castor selecionou as melhores e mais resistentes espátulas para você. Tudo para facilitar a sua vida! SEGURANÇA Compre com segurança! Nossa equipe de suporte estará à disposição caso tenha algum problema ou dúvida. Aguardamos seu pedido!', 23.82, 23.82, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvg2-leq4rfev2lvh85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F10942340734', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
