INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41769213906', 'Bebedouro Refrigerador de Água Gelada Preto 127V ou 220V - Importway', 'O bebedouro de água refrigerado é ideal para fornecer água potável a uma temperatura agradável, geralmente mais fria do que a temperatura ambiente. É especialmente útil em climas quentes ou para pessoas que preferem beber água gelada. Além disso, pode ser uma ótima adição para escritórios, escolas, academias e residências, onde o acesso rápido a água fresca é desejável. CARACTERÍSTICAS: - Marca: Importway - Cor: Preto - Potência de refrigeração: 65w - Frequência: 60hz - Temperatura da água fria: 7-15°C - Tipo de proteção ante elétrica: classe I -Grau de proteção: ambiente interno IPX0 - Temperaturas máxima e mínima da água de entrada no aparelho: 10-32°C - A vazão nominal de água: 5 L/h - Vazão mínima recomendada: 0,7l/h - Capacidade de refrigeração da água: 0,25 L/h - Capacidade de fornecimento de água gelada: 0,25 L/h -Classificação de instalação: ponto de uso (pou) por gravidade - IWBAR110PT: produto 110V / IWBAR220PT: produto 220V INMETRO: 1408‑21‑01', 370.0, 370.0, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc8agl7x93orc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F41769213906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
