INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14100468948', 'Isca Artificial Rei do Rio 9,5cm Cor 24 - Marine Sports', 'Para os amantes da pesca esportiva a ISCA REI DO RIO da consagrada marca Marine Sports é excelente para captura de bons exemplares, seu efeito sonoro e nado errático em meia-água faz com que ela seja mais provocante e eficiente, atraindo os predadores facilmente. Possuem esferas de aço que ao serem arremessadas se desprendem da trava magnética e se desloca para as extremidades, aumentando a precisão do arremesso e a distância. Sua preparação foi feita levando em consideração a força dos peixes das bacias brasileiras, vem com garatéias VMC de alta durabilidade. Ideal para a pesca de Robalo, Black Bass, Tucunaré, Dourado, Traíra entre outros peixes Predadores. ESPECIFICAÇÕES Fabricante: Marine Sports Tamanho:95mm(9,5cm) Peso: 11g Cor: 24 OUTRAS CARACTERÍSTICAS Garatéias VMC HOOKS e argolas em Aço Inox Imagens Ilustrativas', 60.9, 60.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/2f966f8dedf7cdb701df92e33888fe25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F14100468948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
