INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891479678', 'Jogo de 12 Colheres para Sobremesa 16,5Cm Oxford Fortaleza', 'Uma linha de talheres profissionais feitas com o aço inox conhecido como 18/0, o mais resistente e indicado para o uso extremo das cozinhas profissionais ou domésticas. Facas temperadas, que garantem maior durabilidade no fio de corte, resistentes à corrosão e que não danificam as porcelanas. Todos são monólitos, peças únicas, o que garante mais resistência e levam um polimento extra brilho, além de ter uma robustez na pega. Podem ser lavados diariamente na máquina de lavar louças. O conjunto de colheres para sobremesa Fortaleza é composto por 12 peças. Conteúdo da embalagem: 12 colheres de sobremesa com 16,5 cm - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Uso: Não utilizar em micro-ondas - Tipo da embalagem: Papelão pardo - Material: Aço inoxidável - Cor: Prata - Decoração: Monocromático - Formato: Outros - Formato de vendas: Kit - Unidades por kit: 12 - Comprimento: 16,5cm - É produto personalizado: Não - Material do cabo: Aço inoxidável ATENÇÃO: Para compras de pessoa jurídica, cadastre os dados exatamente como consta em seu cartão do CNPJ', 107.89, 107.89, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/sg-11134201-7qvep-lhxt7sjwa4wi67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548911108%2F22891479678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
