INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293672473', 'Tênis Olympikus Versa Casual Masculino Original', 'Estilo versátil com tecnologias exclusivas para garantir seu conforto. O tênis masculino Olympikus Versa tem design leve com tecnologia Evasense, que proporciona alto nível de maciez e solado Gripper, que favorece a aderência e a durabilidade. Um design feito para elevar seu bem-estar no dia a dia, com visual clean que possibilita diversas combinações. Os recortes e o mix de cores fazem toda a diferença e adicionam ainda mais atitude ao modelo. ÓTima pedida para combinar com calça jeans, sarja ou de moletom, bermuda masculina e camiseta masculina Olympikus. Compre agora!', 309.9, 259.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820ly-mo3vla5csn4251', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F23293672473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
