INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56051910066', 'Rasteira Cia do Porto Amarração Detalhes Feminina - Verde Claro', 'Delicadeza, conforto e elegância estão garantidos com o nobre modelo na linha Amarração Detalhes. A Rasteira Cia do Porto Amarração Detalhes Feminina vem com a leveza e qualidade que você precisa. Combinação perfeita entre autenticidade, estilo e sofisticação pelo detalhe do cabedal com o aplique douradoe o desing moderno que transmite na amarração da tira, para te acompanhar em diversas ocasiões! Não fique de fora dessa nova tendência com a ilustre marca Cia do Porto onde a elegância encontra a sofisticação, criando momentos únicos de estilo sem deixar o conforto de lado! Garanta já a sua!', 99.9, 59.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mix3fej40zk123', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F56051910066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
