INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200570107', 'Carregador Turbo USB-C 33W Amarelo | Lufa-Lufa Harry Potter', 'O Carregador GaN 33W do Harry Potter é a escolha perfeita para quem busca velocidade e desempenho em um só produto. Inspirado na Lufa-Lufa, ele combina o melhor da tecnologia com o desejo e a paixão pelo trabalho árduo que definem os bruxos dessa casa. Seu design exclusivo, na cor amarela, remete a essência de lealdade e dedicação dos verdadeiros Lufanos. Sua tecnologia GaN (nitreto de gálio) permite que o carregamento seja ultrarrápido e eficiente, entregando uma potência de 33W para dispositivos móveis sem sobrecarregar a energia e evitando superaquecimentos, tudo com máxima segurança durante o uso. As voltagens de 110V e 220V asseguram que você possa levá-lo para qualquer lugar. Com entrada USB Tipo-C, o GaN é ideal para smartphones, tablets, laptops e outros gadgets. Especificações: -Porta: USB Tipo C -Potência de saída total: 33W (máx) -Voltagem de entrada: 100-240V (50/60 Hz) - 0.8A -Saída: 5V/3A | 9V/3A | 11V/3A | 12V/2.5A | 15V/2A | 20V/1.5A -Tecnologia GaN (Nitreto de Gálio) para maior potência e eficiência -Proteção quádrupla: OCP (sobrecarga), OVP (sobretensão), OTP (superaquecimento), SCP (curto-circuito) -Garantia: 2 anos -Certificação: ANATEL Garantia de 2 anos contra defeitos de fabricação. A garantia engloba os 3 meses de Garantia Legal. Imagens ilustrativas. As cores podem variar de acordo com o monitor ou lote de fabricação.', 169.0, 109.9, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgzemrvpk0ede8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013839557%2F58200570107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899179670', 'Carregador Turbo USB-C 33W Vermelho | Grifinória Harry Potter', 'O Carregador GaN 33W do Harry Potter é a escolha perfeita para quem busca velocidade e desempenho em um só produto. Inspirado na Corvinal, ele combina o melhor da tecnologia com a inteligência e a sede de aprendizado que definem os bruxos dessa casa. Seu design exclusivo, na cor azul, remete aos céus e à criatividade dos verdadeiros Corvinos. Sua tecnologia GaN (nitreto de gálio) permite que o carregamento seja ultrarrápido e eficiente, entregando uma potência de 33W para dispositivos móveis sem sobrecarregar a energia e evitando superaquecimentos, tudo com máxima segurança durante o uso. As voltagens de 110V e 220V asseguram que você possa levá-lo para qualquer lugar. Com entrada USB Tipo-C, o GaN é ideal para smartphones, tablets, laptops e outros gadgets. Especificações: Porta: USB Tipo C Potência de saída total: 33W (máx) Voltagem de entrada: 100-240V (50/60 Hz) - 0.8A Saída: 5V/3A | 9V/3A | 11V/3A | 12V/2.5A | 15V/2A | 20V/1.5A Tecnologia GaN (Nitreto de Gálio) para maior potência e eficiência Proteção quádrupla: OCP (sobrecarga), OVP (sobretensão), OTP (superaquecimento), SCP (curto-circuito) Garantia: 2 anos Certificação: ANATEL Garantia de 2 anos contra defeitos de fabricação. A garantia engloba os 3 meses de Garantia Legal. Imagens ilustrativas. As cores podem variar de acordo com o monitor ou lote de fabricação.', 169.0, 109.9, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgzc54g9kikge7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013839557%2F22899179670', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
