INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253362979', '2x Pulverizador Borrifador Manual 450ml Tramontina Original', 'PRODUTO NOVO Quer praticidade para irrigar plantas e hortaliças no dia a dia? Características do Produto – Marca: Tramontina – Referência: 78604046 – Capacidade: 450 ml – Material: Plástico de alta resistência – Cor: Transparente – Bico pulverizador regulável – Leve, versátil e ergonômico – Dimensões: 17 x 12 x 10 cm – Peso: 350 g – Itens inclusos: 1 pulverizador manual 450 ml Por que escolher este produto – Ideal para horta, jardim e plantas em vasos – Corpo transparente facilita o controle do nível de líquido – Regulagem do jato conforme a necessidade – Resistente e de fácil manuseio – Compacto e leve para uso diário Dicas de Uso – Utilize para pulverizar água ou soluções de cuidado para plantas – Ajuste o jato para regar de forma delicada ou mais intensa – Mantenha limpo após o uso para maior durabilidade – Guarde em local protegido do sol direto Perguntas Frequentes – Qual a capacidade do pulverizador? Possui capacidade de 450 ml. – O jato pode ser regulado? Sim, o bico é ajustável para diferentes tipos de pulverização. – O corpo é transparente? Sim, isso facilita visualizar o nível do líquido. Tenha mais praticidade no cuidado diário das suas plantas com o pulverizador Tramontina 450 ml.', 36.59, 32.94, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mjiw2sbgkkcne9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552162152%2F58253362979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
