INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799549622', 'Disco De Corte Diamantado Segmentado Metais 115 Mm Vonder', 'Disco de corte diamantado, segmentado, para metais, metal super, 115 mm, VONDER Produto de altíssima qualidade com alta performance. Comparado a um disco abrasivo convencional, pode obter um rendimento até 10 vezes superior, considerando as mesmas condições e aplicações (espessura e dureza do material, temperatura ambiente, potência do equipamento, etc). Reduz o risco de acidentes por ser um disco de metal. Indicado para cortar metais, como chapas metálicas, aço inoxidável, vergalhões, ferro fundido e metais não ferrosos. Utilizado em esmerilhadeiras. Proporciona qualidade e produtividade na operação. Especificações: Perfil do corte: Segmentado Tipo de corte do disco de corte diamantado: A seco Diâmetro externo do disco de corte diamantado: 115 mm Diâmetro do furo do disco de corte diamantado: 22,2 mm Altura do segmento diamantado: 2,5 mm Espessura do segmento diamantado: 1,4 mm Rotação máxima: 13.300/min Segue norma: ABNT NBR 15545 Massa aproximada (peso) (kg): 0,114 kg Conteúdo da Embalagem: 1 Disco de corte diamantado.', 61.82, 47.44, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd4v-lvyt5hffrm5u74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F20799549622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
