INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48162041812', 'Lenovo Thinkplus XT62 Fones De Ouvido Sem Fio Bluetooth ENC Com Cancelamento De Ruído Esportivos À Prova D''água Digitais', '• Tecnologia Bluetooth 5.3: Experimente conectividade sem fio com a tecnologia Bluetooth 5.3, garantindo transmissão estável e som de alta qualidade para uma experiência sonora imersiva. • Fone de Ouvido Esportivo Wireless HiFi: Desfrute da superior qualidade sonora deste fone de ouvido esportivo HiFi wireless, perfeito para malhar ou simplesmente relaxar. • Função de Redução de Ruído: Reduza sons externos com a função de redução de ruído integrada do fone de ouvido, permitindo que você se concentre em sua atividade ou conversa. • Controle por Toque no Microfone: Controle convenientemente o microfone com um simples toque, facilitando atender chamadas ou interagir com assistentes de voz. • Conjunto de Almofadas Substituíveis: O fone de ouvido vem com um conjunto de almofadas substituíveis, garantindo um ajuste confortável para uso durante todo o dia e permitindo fácil manutenção. • Suporte ao Google Assistente: Interaja com o Google Assistente sem usar as mãos, facilitando a realização de várias tarefas simultaneamente e aumentando sua produtividade.Modelo: Lenovo XT62 Versão Bluetooth: V5.3 Tipo de alto-falante: 8 MM, 32Ω Capacidade da bateria do compartimento: 400mAh Bateria dos fones: 40mAh Tempo de uso: Cerca de 4,5 horas (fones de ouvido) Tempo de carregamento: Cerca de 1,5 hora (fones de ouvido) Faixa de frequência: 2.402-2.480KHz Sensibilidade do receptor: -90dBm Distância de transmissão: Até 10 metros / 33 pés Lista de embalagem: 2 x fone de ouvido Bluetooth 1 x Estojo de Carregamento 1 x Cabo USB 1 x Manual do Usuário 3 x tampões de ouvido (tamanhos S, M, L)', 98.8, 44.69, NULL, 'Audio > Earphones, Headphones & Headsets', 'https:/