INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3492501949', 'Livro Literatura infantil O urso popozão', 'O urso era um amigo muito querido. O mais legal que os animais já haviam conhecido. Tinha patas pequenas e era muito divertido, mas o que se destacava era seu popozão!? Oh, não! O popô do urso está causando-lhe muitos problemas! Será que ele poderá compensar seus amigos?_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2013_x000D_ Autor: Steve Smallman_x000D_ Ilustrador: Emma Yarlett_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 26.00 x E 0.30_x000D_ ISBN: 9788538052883_x000D_ Coleção: Histórias emocionantes_x000D_ Linha Editorial: Ciranda na Escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Aceitação, Amizade, Literatura infantil, Urso, Ciências Naturais, Diversidade_x000D_ BISAC: Literatura Infantil / Temas Sociais / Amizade_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-m0yjjk72ftp451', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F3492501949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
