INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51809443938', 'Tênis Asics Gel-Excite 11 Roxo Claro - Feminino', 'Mais conforto e suavidade para seus treinos diários! Tênis Asics Gel Excite 11 Roxo Claro - Feminino Parte superior do formulário Ficha Técnica: Marca: Asics Cor: Roxo claro com detalhes em branco Gênero: Feminino Indicação de uso: Corrida e atividades fitness no dia a dia Nível de Corrida: Iniciantes a Intermediários – 5km a 10km Cabedal: Mesh - 71% Poliéster e 29% Poliuretano Palmilha: Tecnologia Ortholite para conforto e respirabilidade Sola: Borracha com alta tração Forro: Poliéster Fechamento: Cadarço Amortecimento: Médio com entressola em AMPLIFOAM PLUS Tecnologias: GEL, para absorção de impacto; AMPLIFOAM PLUS para maciez; ORTHOLITE para conforto interno Entressola: AMPLIFOAM PLUS de maior espessura para sensação de amortecimento suave Detalhes: Estrutura versátil que se adapta ao uso diário e treinos leves, design moderno e anatômico Com design pensado para quem não abre mão do conforto e funcionalidade, o Gel Excite 11 é a escolha certa para quem busca performance sem complicação. Porque investir: Ideal para mulheres que buscam versatilidade e conforto, o Gel Excite 11 oferece amortecimento reforçado com a nova camada AMPLIFOAM PLUS, proporcionando uma passada suave e estável. A tecnologia GEL ajuda na absorção de impacto, enquanto a palmilha Ortholite garante respirabilidade interna. O modelo perfeito para acompanhar desde caminhadas e corridas leves até o uso no dia a dia. Conteúdo da embalagem: 1 par de Tênis Asics Gel Excite 11 Roxo Claro - FemininoParte superior do formulário Parte superior do formulário', 499.99, 450.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-820nt-mng3n8ywxjba22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1