INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41121576570', 'Endoscópio com Tela 4.3" P210, Câmera 1080P, À Prova D''água IP67, Cabo 2M/5M/10M', 'Inspecione áreas de difícil acesso com facilidade! Este Endoscópio com Tela Integrada P210 possui uma tela LCD colorida de 4.3 polegadas, eliminando a necessidade de smartphone, Wi-Fi ou aplicativo. Com câmera Full HD 1080P, lente à prova d''água IP67 e cabo flexível de até 10 metros, é a ferramenta perfeita para inspeções industriais, mecânicas e domésticas. Pratique e eficiente! Parâmetros e Especificações Técnicas: Modelo: P210 Tela: LCD Colorida de 4.3 Polegadas Resolução da Câmera: 1920 x 1080P (Full HD) Diâmetro da Lente: 8mm / 5.5mm (modelos variados) Proteção da Lente: IP67 (À prova d''água) Distância Focal: 5cm - 500cm Bateria: Lítio 2600mAh recarregável Entrada: CC 5V (USB) Comprimento do Cabo: 2 metros, 5 metros ou 10 metros (opcional) Iluminação: 6 LEDs ajustáveis em 3 níveis de brilho Funções: Grava vídeo, tira fotos, armazenamento em cartão TF (não incluso) Tamanho do Host: Aprox. 160mm x 90mm Cenários de Uso Prático: Mecânica Automotiva: Inspecione internos de motores, tubulações e áreas de difícil acesso em veículos. Manutenção Predial: Verifique tubulações hidráulicas, fiações elétricas embutidas e dutos de ar condicionado. Indústria: Inspeção de máquinas, tubos e equipamentos sem necessidade de desmontagem. Uso Doméstico: Encontre objetos perdidos em vãos ou atrás de móveis. Acessórios Incluídos: 1x Endoscópio com Tela P210 1x Cabo de Dados (comprimento conforme opção escolhida) 1x Conjunto de Acessórios para Lente (Gancho, Ímã, Espelho Lateral, Fivela de Substituição) 1x Cabo USB para carregamento', 599.0, 239.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-824jf-mf3qxy2c2ivic0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F791248992%2F41121576570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
