INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599595420', 'Fantasia De Príncipe Infantil Com Capa Vermelha', 'A Fantasia Infantil de Príncipe é composta por uma túnica azul decorada com um brasão real, uma capa vermelha destacável e um cinto preto para ajustar ao corpo. Ideal para pequenos que adoram histórias mágicas e aventuras de reinos encantados. Transforme seu pequeno no herói de contos de fadas com esta fantasia de príncipe! Ideal para festas temáticas, Carnaval e brincadeiras encantadoras. Diferenciais Conjunto completo com túnica azul, capa vermelha e cinto. Detalhes dourados que realçam o charme real. Tecido confortável para longas horas de diversão. Dicas de Uso Combine com sapatos sociais ou botas infantis para um visual completo. Perfeito para festas de aniversário com tema de realeza ou apresentações escolares. Inclua acessórios como uma coroa ou espada (vendidos separadamente) para complementar o visual. Tamanho Disponível: Infantil (P 3 a 4 anos, M 6 a 8 anos , G 10 a 12 anos ).. Garantia: 30 Dias Genero: Menino IDADE: kids GENDER: male Codigo do Produto: 935409 Tamanhos: P 3/4 - M 6/8 - G 10/12 Anos Descrição: Fantasia Príncipe Infantil com Capa', 179.99, 179.99, NULL, 'Baby & Kids Fashion > Baby Clothes > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbky-m5u53z2hmm3v6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410794727%2F19599595420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
