INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097891951', 'Colchão Solteiro Howie Espuma D28 (17x88x188) Branco', 'Que tal o Colchão Howie?Dormir bem é essencial para a saúde física e mental, não é verdade? E nada como o Colchão Howie para acompanhar seu merecido descanso! Pensado para proporcionar o relaxamento ideal e te deixar aconchegado nas horas de sono, ele tem espuma D28 na composição, além de contar com EPS - o combo perfeito para você dormir bem. Já por fora, esse modelo traz revestimento em poliéster com costuras em linha de poliéster, assim tem toque macio quando em contato com o corpo. Daí é só adquirir uma boa base box ou cama tradicional e descansar :) Cor: Branco Garantia em Meses: 12 Cores do Produto: Branco Instruções/Cuidados: Seguir o manual de instruções Conteúdo da Embalagem: 1 Colchão - Entregue em: 1 Volume Modelo: Howie Número de Volumes: 1 Material: O Colchão Howie é composto por espuma D28 e EPS (poliestireno), revestimento 100% poliéster e acabamento com linhas poliéster e bordado em matelassê. Material para Filtro: Espuma Descrição do Tamanho: Altura: 17 cm | Largura: 88 cm | Profundidade: 188 cm Altura do Produto (cm): 17 Largura do Produto (cm): 88 Comprimento do Produto (cm): 188 Peso do Produto (Kg): 7.9 Produto precisa de Montagem?: Não Pillow Top: Não Turn Free (Não precisa virar): Não Tendências: Minimal Pop Densidade da espuma: D28 Material do Revestimento: Poliéster Tipo de Colchão: Espuma PROFUNDIDADE x LARGURA x ALTURA: 188 x 88 x 17 Fornecedor: Mobly Baterias são necessárias?: Não Certificação de teste externa: Não Componentes incluídos: Não Número da peça: Não Submarca: Não Produto: Colchão Classificação do Colchão: Solteiro Tipo do Colchão: Padrão Tamanho do colchão: Solteiro Marca: Mobly', 489.96, 440.28, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://c