INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40122469027', 'Conector DC Jack para Notebook Dell Inspiron 14-5458-3080', 'Conector DC Jack compatível com Dell Inspiron 14-5458-3080 Este é um DC Jack bringIT compatível com o notebook Dell Inspiron 14-5458-3080. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 4.5mm x 3.0mm Cabo: Com Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC112-DE-0123', 46.2, 43.89, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-825b0-mqu12gbf2vpn57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F40122469027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
