INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22595975969', 'CAPACETE ASW BIKE FUN', 'O capacete ASW FUN é a aposta ideal para um dia descontraído no pedal, seja com amigos ou sozinho, o que importa é se divertir! Com inúmeras cores e iluminação traseira, o capacete ASW FUN é preparado para sua proteção durante as pedaladas noturnas e aproveite também para pedalar durante o dia, afinal a pala do ASW FUN foi desenvolvida especialmente para te proteger nos dias ensolarados. QUER SABER MAIS? - Certificação CE - Entradas de ar e saídas de ar, assim você fica confortável! - Sistema de ajuste para que seu capacete fique sempre na posição correta - Forro removível e lavável, mais durabilidade para o seu capacete - Sistema de iluminação traseira (bateria LR41).', 164.44, 164.44, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rffx-m968mktp9tnd57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1003133428%2F22595975969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598441401', 'Kit de Natação Para Iniciantes Touca Slim Óculos e Protetor Ouvido Três em Um Speedo SLC - PRETO', 'O Kit de Natação Três em Um Speedo SLC é a escolha ideal para quem busca conforto, proteção e alto desempenho nas piscinas. Composto por óculos de natação, touca Slim e protetor de ouvido, este kit oferece tudo o que você precisa para um treino eficiente e sem preocupações. Diferenciais do kit: • Óculos com vedação confortável e ajuste perfeito, garantindo excelente visão debaixo d’água. • Área de vedação do óculos: M. • Narizeira regulável para adaptação personalizada. • Touca Slim em silicone, que proporciona leveza e encaixe sem pressão excessiva. • Protetor de ouvido em silicone, evitando a entrada de água e garantindo mais conforto durante a prática esportiva. Composição e qualidade: • Óculos: Lentes de policarbonato, ventosa e tiras de silicone para ajuste seguro. • Touca: 100% silicone, garantindo durabilidade e flexibilidade. Dicas de uso: • Para melhor conservação, mantenha as lentes livres de poeira e gordura. Lave suavemente com água limpa e fria após o uso, deixando secar à sombra. • Não esfregue ou passe pano nas lentes, para não danificá-las. • Atenção: Exceto quando em uso, evite deixar os óculos expostos ao sol ou temperaturas muito altas. • Tratamento antiembaçante: É Aconselhável a colocação dos óculos ainda secos e evitar molhar o interior das lentes, pois o acúmulo de cloro pode danificar esta propriedade, que sofre desgaste natural no uso. • Contato com protetores solares ou produtos abrasivos danificam suas lentes.', 109.9, 109.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/sg-11134201-7repn-m90n78nbl7zbf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242944993%2F22598441401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
