INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205919340', 'Ração Quatree Life Gatos Castrados Frango e Arroz 10kg', 'Descrição: Ração Quatree Life Gatos Castrados Frango e Arroz 10kg Especialmente desenvolvido para oferecer uma dieta saudável e nutritiva, Ração Seca Quatree Life Frango e Arroz Gatos Castrados é um alimento Premium Especial Natural formulado com antioxidantes naturais e complexo de vegetais para promover mais vitalidade e bem-estar para o seu gato. Não possui ingredientes transgênicos, corantes, aromatizantes e conservantes artificiais (BHT e BHA). - Indicada para gatos adultos castrados; - Não contém ingredientes transgênicos, corantes, aromatizantes ou conservantes artificiais; - Ajuda no controle do peso com L-carnitina, fibras especiais e calorias reduzidas; - Promove um trato urinário saudável, prevenindo cálculos urinários de estruvita e oxalato de cálcio; - Reduz a formação de bolas de pelo com fibras especiais; - Reforça o sistema imunológico com beta-glucano, vitaminas C e E, e selênio; - Contém um complexo de vegetais, ricos em fibras naturais e nutrientes; - Ajuda a reduzir o volume e odor das fezes com prebióticos, yucca e zeólita; Resumo: - CONTROLE DE PESO IDEAL: Contém L-carnitina, fibras especiais e níveis reduzidos de calorias para ajudar a manter o peso ideal; - TRATO URINÁRIO SAUDÁVEL: Controle do pH urinário e equilíbrio dos minerais auxiliam na prevenção dos principais cálculos urinários nos felinos - estruvita e oxalato de cálcio; - CONTROLE DE BOLA DE PELO: Fibras especiais que auxiliam na eliminação natural dos pelos, reduzindo a formação de bola de pelo; - REFORÇO IMUNOLÓGICO: Contém beta-glucano 1,3-1,6 e complexo de antioxidantes: vitaminas C e E e selênio para reforçar as defesas naturais do organismo; - COMPLEXO DE VEGETAIS: Brócolis, beterraba branca, batata-doce e cenoura, carboidratos saudáveis de baixo índice glicêmico, ricos em fibras naturais que garantem saciedade por mais tempo, além de serem fontes de vitaminas e minerais; - MENOR VOLUME E ODOR DE FEZES: Prebiótico, yucca e zeólita promovem a saúde intestinal e contribuem para fezes mais firmes com odor e volume reduzidos.', 286.65, 178.09, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-82601-ml6un8u4tkaqa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009890604%2F58205919340', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
