INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2957728621', 'Trena Aço 5mx19mm Curta Auto Trava Vonder Plus', 'Conteúdo da embalagem 1 Trena Aplicações e dicas de uso Indicada para medições em geral Destaques e diferenciais Possui estojo anatômico em ABS com borracha termoplástica que confere maior resistência e conforto no manuseio e fita em aço com pintura fosca antirreflexo e graduação em milímetros/polegadas, facilitando a leitura e proporcionando maior precisão. Conta também com sistema autotrava, que mantém a fita travada quando esticada e facilita a leitura, alça em nylon e presilha para cinto, auxiliando no transporte e segurança durante o uso. Conta ainda com gancho ajustável. DETALHES TÉCNICOS Comprimento da trena 5 m Largura da fita da trena: 19,0 mm Revestimento da fita da trena: Pintado Acabamento da fita da trena: Pintura fosca Graduação da trena: mm/pol Material da caixa da trena: ABS de alta resistência com borracha termoplástica Sistema de trava da trena: Autotrava Classe de precisão : Classe II', 36.9, 36.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-lzyy5vew58be0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F2957728621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
