INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892005249', 'Óculos de Natação Hammerhead Vortex 1.0 Original Proteção U.V Máxima Vedação', 'Óculos de Natação Vortex Series – Desempenho e Conforto para Todos os Nadadores Desenvolvido para atletas iniciantes ou experientes, o Óculos de Natação Vortex Series oferece alta tecnologia e proteção para aprimorar sua performance na água. Por que Escolher o Vortex Series? Lentes de Policarbonato: Alta qualidade, sem distorção de visão, com proteção U.V.A. e U.V.B. para máxima segurança. Tratamento Antiembaçante: Garante visibilidade clara e nítida durante toda a prática. Vedação Superior: Ventosas em PVC com excelente sucção, evitando vazamentos. Ajuste Personalizado: Narigueira substituível com dois tamanhos adicionais para moldar à sua face. Conforto Extra: Tiras de silicone macio para uso prolongado sem incômodos. Especificações Técnicas: Material: Lentes: Policarbonato. Ventosas: PVC. Tiras: Silicone. Narigueira: Poliuretano (2 opções de ajuste). Tamanho: Único. Garantia: Contra defeitos de fabricação. Benefícios Extras: Proteção Completa: Bloqueia raios solares prejudiciais e mantém a nitidez embaixo d''água. Durabilidade: Fabricado com materiais resistentes e de alta qualidade. Ajuste Versátil: Ideal para diferentes formatos de rosto. Compra Garantida com a Sloth: Produto Original: Autenticidade e qualidade certificadas com nota fiscal. Envio Ágil: Postagem em até 24 horas após aprovação do pedido. Troca e Devolução Sem Complicações: 30 dias para defeitos de fabricação, com custos de envio cobertos pela Sloth. 7 dias para desistência da compra, contados a partir do recebimento. Melhore sua experiência de natação com o Óculos Vortex Series! Perfeito para desempenho, conforto e segurança em cada braçada. Compre agora e eleve sua prática esportiva!', 39.9, 33.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m40jql51n0hte1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F22892005249', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
