INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250314691', 'Buffet 3 Portas Cantinho do Café Aparador Bela Moderno Versátil Sofisticado hall de entrada sala', '☕ Buffet 3 Portas Cantinho do Café – Aparador Bela | Moderno, Versátil e Sofisticado Renove seu espaço com o Buffet 3 Portas Bela, o móvel multifuncional que vai transformar sua casa com elegância e praticidade. Ideal como buffet para sala de jantar, aparador decorativo ou cantinho do café, ele se adapta perfeitamente à sua rotina e ao seu estilo. ✨ Destaques que encantam: ✔️ 3 em 1: Use como buffet, aparador ou cantinho do café ✔️ Design Moderno e Minimalista: combina com qualquer decoração ✔️ Pintura UV Texturizada: mais brilho, resistência e durabilidade ✔️ Sistema Batente Cava: sem puxadores, mais elegante e funcional ✔️ Portas com Dobradiças de Aço Inox: maior vida útil e resistência ✔️ Prateleiras Internas Amplas: guarde louças, mantimentos ou utensílios com organização total 📏 Medidas do Produto: Altura: 80 cm Largura: 121 cm Profundidade: 35 cm 🛠️ Montagem e Cuidados: Acompanha manual de montagem detalhado Produto entregue desmontado Recomendamos montagem profissional Itens decorativos não acompanham o produto Cores podem variar conforme o seu dispositivo', 499.0, 359.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgnr6dcs3don33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467752495%2F58250314691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293094443', 'Areia Sílica Para Gatos Cristal Grosso 1,5kg Maylon Pet Tira Odor', 'Areia Sanitária Cristais Sílica Em Gel Para Caixa De Gato Esse pacote de cristais de sílica atóxica é a evolução do sanitário para gatos. - Alto rendimento, Ultra absorção, Elimina odores (propriedades Antibacterianas). Atende a todas as raças e tamanho. - Os Micro grãos de cristais possuem inúmeros microporos que atuam como esponjas absorvendo a urina e líquidos, eliminando o odor e proporcionando um ambiente mais limpo e sem cheiro. Possui alto poder de absorção, agindo nas bactérias encontradas na urina e fezes do gato, retendo-os até a troca dos cristais. A sílica tem textura semelhante a grãos de areia. É biodegradável e contém partículas que inibem a proliferação de bactérias. Em pacotes de 1,5Kg, o produto tem durabilidade de até três semanas dentro da bandeja para gatos, variando conforme a quantidade de gatos. Não causa dano ao gato e possui tecnologia que indica qual área deve ser retirada devido à ultra absorção da sílica gel, proporcionando economia e durabilidade. Os Cristais de Sílica não deixam marcas de pegadas, pois não possuem resíduos como as areias comuns. INFORMAÇÕES: - Indicação: Somente Gatos - Idade: Filhotes, Adultos, Idosos - Raças: Pequenas, Médias e Grandes - Apresentação: 1,5 Kg - Marca: Maylon Pet', 39.9, 39.9, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rd3n-lwom2b1md44728', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318817543%2F23293094443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
