INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098164446', 'Roda Traseira Yamaha Factor 125 Ybr 125 Freio Á Lona 4mm Pneu Tork Montada Camara de Ar Cinta Aro', 'Roda Traseira (Montada, Alinhada e Balanceada) Especificações: Modelo Compatível: Ybr 125 / Factor 125-150 Cilindradas Compatíveis: 125, 150 Posição da Roda: Traseira Características Técnicas: Aro: Fabreck Raio:4mm Cromado Cubo: Fabreck/Unibreq ( Marca Instalada Conforme Disponibilidade no Estoque ) Sistema de Freio: Á Tambor Pneu: Pneu Pro Tork montado na roda com cinta de aro e câmara. Dimensões e Material: Medidas do Aro: 18inches Material do Aro: Aço Estrutura de roda: De Raios Sendo líder de mercado, os cubos de roda Fabreck são confeccionados em liga de alumínio especial e com pintura no padrão da original, além de serem produzidos em modernos equipamentos de usinagem, proporcionam grande durabilidade e resistência do produto. Conservação Os cuidados para conservação do cromo, tanto no seu aspecto quanto na prevenção contra a oxidação, devem considerar a limpeza frequente com água e sabão neutro aplicados com pano ou esponja macia. A montagem e desmontagem do pneu deve ser realizada por profissional experiente e com equipamento adequado. Nunca utilize materiais abrasivos ou produtos químicos para limpeza.', 519.9, 467.91, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6mobxtmrt4g3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012518791%2F23098164446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
