INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41201049159', 'Livro Fundamentos do Cristianismo | Alister McGrath e J. I. Packer', 'Livro Fundamentos do Cristianismo Alister McGrath e J. I. Packer Dois mil anos depois da crucificação de Jesus, o cristianismo conta com mais seguidores do que qualquer outra religião do mundo. - Quais são suas crenças essenciais? Como surgiram? Como as diversas igrejas entendem essas crenças? Como elas influenciam a maneira de os cristãos viverem? Em Fundamentos do Cristianismo o leitor encontrará: - informações acessíveis de especialistas em várias áreas do conhecimento teológico ; - mais de 600 pequenos artigos com informações detalhadas sobre diversos assuntos: desde a Natividade na arte cristã até a pós-modernidade ; das origens dos credos à relação do cristianismo com a justiça social; da sexualidade humana ao problema do sofrimento ; - uma antologia de excertos da obra dos principais pensadores cristãos da história. Especificações do livro: Título: Fundamentos do Cristianismo Subtítulo: Um Manuak da Fé Cristã Autor(es): Alister McGrath e J. I. Packer Ano de Edição: 2018 Capa: Brochura Acabamento: Laminação Brilhante Miolo: Papel Off-set 63 g/m² Páginas: 464 Dimensões: Altura: 22,5 cm Largura: 15,5 cm Profundidade: 2,6 cm Peso: 0,658 k.g ISBN: 9788527505758 Editora: Vida Nova n', 73.61, 73.61, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9krd95mihvm70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F41201049159', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
