INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252373527', 'Esmalte Dailus Coleção Dai Goods', 'Inspirada no gigante sucesso dos famosos livrinhos de colorir que invadiram a internet e na tendência #cozycoloring, chegou a hora de despertar sua imaginação para pintar e desenhar nas unhas com a coleção de esmaltes DAI GOODS! Se encante e estimule a criatividade com 9 vidrinhos cremosos superdivertidos, baseados em 3 irreverentes cenários para colorir – cada um com um personagem carismático diferente! Fique apaixonada pelo nosso simpático sapinho em uma relaxante tarde na praia, pela nossa hipopótama superfofa em uma animada aula de ballet e pela charmosa lhama em um delicioso piquenique no parque. Embarque nessa aventura com a gente! Modo de Uso: Agite o frasco antes da aplicação.Passe uma camada de base para proteger as unhas.Aplique 1 a 2 camadas do esmalte escolhido.Finalize com extra brilho para aumentar a durabilidade.', 15.39, 15.39, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-81zu1-milyumw53j0m50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58252373527', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18948623726', 'Bíblia Sagrada | Letra Extragigante | ARC | Capa Luxo Flor P', '&lt;h2&gt;B&amp;iacute;blia Sagrada&amp;nbsp;&lt;/h2&gt; &lt;div&gt; &lt;p&gt;B&amp;iacute;blia Sagrada com a linguagem na vers&amp;atilde;o ARC (Revista Corrigida) de Jo&amp;atilde;o Ferreira de Almeida. Sendo a vers&amp;atilde;o mais utilizada pelos evang&amp;eacute;licos do Brasil. Com sua fidelidade traduzida dos textos originais pelo mission&amp;aacute;rio portugu&amp;ecirc;s Jo&amp;atilde;o Ferreira de Almeida esta obra tem como destaque sua linguagem elegante e&amp;nbsp;culta.&lt;/p&gt; &lt;p&gt;Ela Possui:&amp;nbsp;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;Como encontrar ajuda na B&amp;iacute;blia&lt;/li&gt; &lt;li&gt;Leituras para dias especiais&lt;/li&gt; &lt;li&gt;Mapas coloridos&lt;/li&gt; &lt;li&gt;Notas e refer&amp;ecirc;ncia b&amp;iacute;blicas&lt;/li&gt; &lt;li&gt;O que a B&amp;iacute;blia diz sobre o perd&amp;atilde;o de Deus&lt;/li&gt; &lt;li&gt;Palavras de Jesus impressas em Vermelho&lt;/li&gt; &lt;li&gt;Tabela de pesos moedas e medidas&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;Com tamanho de letra extragigante e palavras de Jesus impressas em vermelho este modelo da B&amp;iacute;blia Sagrada oferece mais conforto na leitura especialmente ao grupo da terceira idade ou &amp;agrave;quelas pessoas com problemas leves de vis&amp;atilde;o.&lt;/p&gt; &lt;/div&gt; &lt;table width=&quot;600&quot;&gt; &lt;tbody&gt; &lt;tr&gt; &lt;td&gt;&lt;strong&gt;T&amp;iacute;tulo:&lt;/strong&gt;&lt;/td&gt; &lt;td&gt;B&amp;iacute;blia Sagrada&amp;nbsp;&lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt;&lt;strong&gt;Linguagem:&lt;/strong&gt;&lt;/td&gt; &lt;td&gt;Almeida Revista e Corrigida&lt;/td&gt; &lt;/tr&gt; &lt;tr&gt; &lt;td&gt;&lt;strong&gt;Capa:&lt;/strong&gt;&lt;/td&gt; &lt;td&gt;Flor Pink&lt;/td&gt; &lt;/tr&gt; &lt;tr&g