INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698543954', 'Halter Pintado 1kg Bola Peso de Academia Musculação Pesinho Treino Em Casa Funcional', 'HALTER BOLA PINTADO – DESEMPENHO, CONFORTO E RESISTÊNCIA PARA SEUS TREINOS. O Halter Bola Pintado MegaGym é a escolha certa para quem busca treinos de alta performance. Fabricado em ferro fundido de alta durabilidade e possui acabamento em Pintura protetora premium na cor preta, que auxilia a evitar corrosão e protege seus por longos períodos. Características do Produto • Material: Ferro Fundido; • Revestimento - Pintura Protetora Premium, que evita corrosão e desgaste por longos períodos; • Pegada: Anatômica, com conforto e segurança; • Numeração gravada - Facilita a identificação do peso. Benefícios: — Pegada Anatômica — Treinamento Versátil — Ganhos de Massa e Definição Muscular — Aprimoramento da Postura e Equilíbrio — Fortalecimento Muscular', 37.27, 18.52, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf16wjfhn7r9ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867949056%2F18698543954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397625429', 'Kit 3 Fraldas Geriátricas Bigfral Derma Plus Juvenil com 10un cada', 'O Kit contém: 3 pacotes de Fraldas Geriátricas Bigfral Derma Plus Juvenil com 10un cada. A Bigfral DermaPlus foi desenvolvida para adultos com incontinência urinária severa. Possui o exclusivo sistema de proteção total da pele, com extratos naturais hidratantes que ajudam a prevenir irritações, mantendo a pele protegida e saudável, além de sistema antiodor, trazendo até 10h de proteção e cuidado.', 151.09, 114.96, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rccu-lryfesrl35pre2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1131442264%2F20397625429', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292822516', 'Fio Dental Hillo 100 metros.', 'Fio Dental Hillo O uso do fio dental é essencial para manter uma boa higienização bucal! E é por isso que você precisa adquirir o Fio Dental Hillo! Para evitar a formação da placa bacteriana, o fio dental deve ser usado diariamente. Ele ainda vai prevenir o tártaro e as cáries. Modo de uso: Corte aproximadamente 50cm e enrole-o nos dedos médios. Passe o Fio na parte superior do dente e deslize suavemente em direção à gengiva. Limpe os dois lados do dente e abaixo da linha da gengiva, utilizando uma nova parte do Fio a cada dente. #html-body [data-pb-style="646BA64D0C20E"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64D0C223"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}#html-body [data-pb-style="646BA64D0C232"]{height: 141px;}#html-body [data-pb-style="646BA64D0C241"]{width: 1022px;}', 21.3, 21.3, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rcdj-lr61u6zczckkcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23292822516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
