INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206881752', 'Kit 12 Canetas Marcadores Soft Touch Dual Álcool Profissional Desenho', 'O kit de canetas marcadoras Touch Dual é ideal para quem busca qualidade, versatilidade e excelente acabamento em desenhos, ilustrações e projetos artísticos. Com tinta à base de álcool, proporciona cores intensas, ótima cobertura e secagem rápida, garantindo resultados profissionais em diferentes tipos de trabalhos. Cada marcador possui duas pontas funcionais: uma ponta fina para detalhes e contornos precisos, e uma ponta chanfrada para preenchimentos, traços largos e efeitos de sombreamento. Essa combinação permite maior controle e criatividade durante o uso. Muito utilizado por ilustradores, designers, estudantes de arte, arquitetos e amantes do desenho, o kit oferece cores variadas que possibilitam criar degradês, sombras e efeitos com facilidade. As canetas possuem corpo ergonômico que facilita o manuseio e tampas identificadas com a cor correspondente, permitindo encontrar rapidamente o tom desejado. VANTAGENS DO PRODUTO: - Marcadores com tinta à base de álcool de alta qualidade - Cores intensas e ótima pigmentação - Duas pontas para maior versatilidade no desenho - Ponta fina para detalhes e ponta chanfrada para preenchimento - Secagem rápida e excelente cobertura - Ideal para ilustração, design, sketch, mangá e colorização ESPECIFICAÇÕES TÉCNICAS: - Tipo: Marcador artístico - Modelo: Touch Dual - Tipo de tinta: À base de álcool - Quantidade: Kit com 12 canetas - Pontas: Dupla (fina e chanfrada) IDEAL PARA: - Ilustração artística - Desenho profissional ou hobby - Arquitetura e design - Mangá e anime - Colorização de projetos e sketches CONTEÚDO DA EMBALAGEM: - 12 Canetas marcadoras Touch Dual', 49.99, 18.99, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/br-11134207-820lp-mlrxxjd0wnpg6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1333507062%2F58206881752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
