INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20907532225', 'O Verdadeiro Evangelho | Paul Washer', 'O Verdadeiro Evangelho Deus tem dado a Paul Washer uma mensagem oportuna e profética para a igreja dos nossos tempos. Ao analisar esta geração, ele afirma que o problema principal não é a dureza do evangelho, mas a ignorância de seu conteúdo. Como resposta a isso, Washer tem pregado em diversas ocasiões as verdades fundamentais do evangelho (o pecado do homem, a justiça de Deus, o sacrifício, a ressurreição de Cristo, etc). Baseado em várias exposições de Romanos 3, o Verdadeiro Evangelho busca apresentar aquilo que Deus fez em Cristo, a fim de ele mesmo ser justo e o justificador daquele que tem fé em Jesus (Rm 3:26). Recomendações: ""Deus tem dado a Paul Washer uma mensagem oportuna e profética para a igreja dos nossos tempos. Ao analisar esta geração, ele afirma que o problema principal não é a dureza ao evangelho, mas a ignorância do seu conteúdo. Como resposta a isso, Washer tem pregado em diversas ocasiões as verdades fundamentais do evangelho (o pecado do homem, a justiça de Deus, o sacrifício e a ressurreição de Cristo, etc.). Baseado em várias exposições de Romanos 3, O Verdadeiro Evangelho busca apresentar aquilo que Deus fez em Cristo, a fim de ele mesmo ser justo e o justificador daquele que tem fé em Jesus (Rm 3:26)."" - Vinicius Musselman Pimentel, Diretor do Blog Voltemos ao Evangelho Título: O Verdadeiro Evangelho Autor: Paul Washer Páginas: 120 Formato: 16 x 12 x 0.5cm Peso: 0.212 kg ISBN: 9788581320359 Editora: Fiel', 33.08, 33.08, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/9c6f2742f419c158e1f514818d155e48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20907532225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399407703', 'Chocolate M&M''S Ao Leite Tubo 12 Unidades de 30g', 'Caixa com 12 unidades do Chocolate M&M''S Ao Leite Tubo 30g. O M&M''S Ao Leite 30g vem com deliciosos confeitos de chocolate ao leite, cobertos por uma fina e crocante casquinha colorida, em uma embalagem especial no formato de tubo, tamanho ideal para o consumo individual. Perfeito para levar para qualquer lugar na bolsa, na mochila ou no bolso. Experimente também os sabores Amendoim e Crispy. Entre as seis cores de tubo (amarelo, vermelho, verde, azul, laranja e marrom), a seleção é aleatória. Ingredientes Açúcar, massa de cacau, leite em pó, gordura vegetal, amido de milho (agrobacterium tumefaciens, bacillus thuringiensis, streptomyces viridochromogenes, sphingobium herbicidorovans e zea mays), xarope de glucose, manteiga de cacau, dextrina, sal, emulsificantes (lecitina de soja e poliglicerol polirricinoleato), espessante goma arábica, corante inorgânico dióxido de titânio, corantes artificiais (amarelo crepúsculo, tartrazina, vermelho 40, azul brilhante), corante natural cúrcuma, aromatizantes, glaceante cera de carnaúba. Alergênicos ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. PODE CONTER AMENDOIM, DERIVADOS DE TRIGO, CENTEIO, CEVADA E AVEIA. CONTÉM LACTOSE. CONTÉM GLÚTEN.', 86.48, 61.67, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-820ly-mq1w2oxghzwgdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F18399407703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10110401548', 'Munhequeira Noturna Kestal KSN063', 'Anvisa : Registro isento conforme resolução RDC 27 de 06 de agosto de 2010 - anexo 1. Munhequeira Noturna Kestal KSN063 A munhequeira noturna possibilita manter a mão em posição neitra ao dormir. Composição: Borracha de cloropreno revestida com tecido 100% Poliamida. Medidas aproximadas: 9cm altura x 25cm comprimento Cor: preta ITENS INCLUSOS: 01 unidade da Munhequeira Noturna Kestal KSN063 Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 109.0, 109.0, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Sports Wristbands', 'https://cf.shopee.com.br/file/e6f5c8128ca2f2f49309519d5c7d7a95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F10110401548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899204450', 'Bola De Futebol De Campo Estadios 24 Fortaleza N5', 'A Bola Futebol de Campo do Fortaleza é a pedida certa para o bate-bola da sua turma. Confeccionada em materiais de qualidade, a Bola de Futebol oferece maciez, essencial para as partidas de futebol da criançada. E para complementar, o escudo do seu time do coração em destaque para o orgulho do torcedor. Desperte o craque que existe em você. Informações Técnicas : Composição: Policloreto de Vinila (PVC) Câmara interna: 100% borracha butílica Circunferência aproximada: 68 - 70 cm Peso aproximado: 410 - 440 g Clube: Fortaleza Indicado para: Campo Origem: Importada Miolo: Removível Gênero: Unissex Costura: Sim Gomos: 32 Tamanho : 5 Conteúdo da Embalagem: 01 un. Bola de Futebol de Campo Estadios 24 Fortaleza N5 Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 119.0, 119.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7rceh-ls1uy7ekesdk75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F21899204450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8265306471', 'Munhequeira com Tala e Tiras Bilateral KSN031 Kestal Preta P', 'Anvisa : Registro isento conforme resolução RDC 27 de 06 de agosto de 2010 - anexo 1. Munhequeira com Tala e Tiras Bilateral KSN031 Kestal A Munhequeira com Tala e Tiras Bilateral Kestal auxilia na prevenção e reabilitação de entorses e lesões de mãos e punhos. Pode ser utilizada com e/ou sem a tala, em ambas as mãos. A compressão é ajustavel conforme a necessidade e as tiras proporcionam maior compressão e segurança articular. Possui suporte interno em lycra que facilita o encaixe e a utilização do produto. Confeccionada em neoprene, mantém a temperatura da região, aliviando dores. Dimensões aproximadas: P - 22cm (circunferência) x 16cm (altura) M - 23cm (circunferência) x 17cm (altura) G - 24cm (circunferência) x 17cm (altura) Composição: Borracha de cloropreno revestida com tecido 100% Poliamida. ITENS INCLUSOS: 01 unidade da Munhequeira com Tala e Tiras Bilateral Kestal Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 54.0, 54.0, NULL, 'Health > Medical Supplies > Injury & Disability Support', 'https://cf.shopee.com.br/file/4f46f716faddc44b3be9ca2f4b1faebd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F8265306471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699015914', 'Perfume Mawwal Fada Masculino 100ml Eau de Parfum Toque Exótico e Misterioso Transmite Liberdade', 'Seja bem vindo (a) a Mawwal. Você procura um perfume masculino que transmita confiança, elegância e personalidade, mas está cansado de fragrâncias comuns que não deixam sua marca por onde passa? Fada de Mawwal Arabia é um perfume masculino, que foi pensado para transmitir uma sensação de fuga e liberdade, com um toque exótico e misterioso. O perfume "Fada" da Mawwal Arabia foi criado para ser uma experiência olfativa que evoca a liberdade e a aventura, com notas que remetem a terras exóticas e um céu vasto. A fragrância possui uma combinação intrigante de especiarias e notas amadeiradas, criando um aroma sofisticado e envolvente. Analisando mais detalhadamente as notas do perfume: Notas de Topo A canela, a noz-moscada, a toranja e o cardamomo trazem uma abertura quente e picante, com um toque cítrico e vibrante. Notas de Coração A lavanda, o alcaçuz, a noz-moscada e o olíbano adicionam um coração aromático e suave, equilibrando a intensidade das notas de topo. Notas de Fundo O sândalo, o patchouli, o vetiver e o âmbar conferem profundidade e mistério à fragrância, criando uma base amadeirada e envolvente. O perfume "Fada" é descrito como uma fragrância que pode ser usada tanto no dia a dia quanto em ocasiões especiais, transmitindo uma sensação de confiança e elegância. Item incluso: 1 - Perfume 100ml. Ficou com alguma dúvida? Nossa equipe especializada está pronta para ajudar você! Entre em contato pelo chat e receba um atendimento rápido e personalizado.', 453.75, 199.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-825ak-mfsn1ovbdcln48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1642951702%2F22699015914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209453710', 'Coca-Cola Sem Açúcar Refrigerante', 'Desfrute do sabor autêntico e refrescante da Coca-Cola sem adição de açúcar. Perfeita para acompanhar suas refeições, churrascos ou momentos de lazer, sem abrir mão de um estilo de vida equilibrado. A Coca-Cola Sem Açúcar é ideal para compartilhar com amigos e familiares em qualquer ocasião. Refresque-se com o sabor clássico e zero açúcar!', 7.99, 7.99, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-82581-mr0bybldxyx8b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209453710', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697290942', 'Spot LED 7W para trilho, preto ou branco, luz 6500K, 4200K ou 3000K, Super LED ideal para ambientes internos.', '💡 Iluminação Focada e Eficiente! 💡 🌟 POTÊNCIA: 7W: Oferece um equilíbrio entre brilho e eficiência energética. 🔌 TENSÃO: AC85-265V: Compatível com uma ampla faixa de tensão para fácil instalação. 💡 LUMENS: 455LM: Proporciona uma iluminação brilhante e eficaz. 🌆 ÂNGULO DE ABERTURA: 24°: Concentra a luz em áreas específicas, ideal para destaque. 🔋 FATOR DE POTÊNCIA: 0,5: Contribui para a eficiência energética. 🎨 COR: Branco Quente (Amarelo 3000K) | Branco Frio (Branco 6500K) | Branco Neutro: Escolha a temperatura de cor que melhor se adapta ao seu ambiente. 🕐 VIDA ÚTIL: (Não Especificado): Oferece uma iluminação duradoura. 🌈 IRC (ÍNDICE DE REPRODUÇÃO DE COR): (Não Especificado): Reprodução fiel de cores para uma iluminação de qualidade. 🔒 IP: IP20: Adequada para uso em ambientes internos. 🔒 GARANTIA: (Não Especificado): Oferece tranquilidade para sua compra. 📏 TAMANHO: 4990115mm: Design compacto e versátil para diversas aplicações. 🎨 COR DO MATERIAL: Branco | Preto: Escolha a cor que melhor combina com seu estilo e ambiente. Esta lâmpada é ideal para iluminação direcionada e realce. Escolha a temperatura de cor que se adapta às suas preferências e crie uma atmosfera acolhedora e atraente em seus espaços. 💫🎨🏡', 30.0, 17.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgz2uarq5yivbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F22697290942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47202974148', 'Receptor Bluetooth USB Para Carro PC Altomex A230 Áudio Sem Fio', 'Receptor USB Bluetooth para Som de Carro Adaptador Altomex REC-AL-A230 Receptor desenvolvido para quem deseja modernizar o som do carro sem trocar o rádio. Basta conectar na entrada USB do aparelho, parear com o celular e transmitir músicas, podcasts, chamadas ou navegação por voz de forma prática e estável. Compacto e discreto, é ideal para uso automotivo e também compatível com outros dispositivos que possuam porta USB para alimentação, seguindo o padrão comum do mercado. ⭐ BENEFÍCIOS NO USO DIÁRIO • Permite adicionar Bluetooth em rádios que não possuem a função • Conexão rápida, estável e sem interferências • Fácil de usar: conectou, pareou e utilizou • Design compacto e discreto no painel do carro • Compatível com celulares Android e iPhone • Ideal para músicas, chamadas e áudio de navegação • Excelente custo-benefício para uso automotivo ⚙️ INFORMAÇÕES DO PRODUTO • Marca: Altomex • Modelo: REC-AL-A230 • Tipo: Receptor Bluetooth USB • Conexão: Bluetooth • Alimentação: Porta USB • Uso indicado: Som automotivo e aparelhos com entrada USB • Alcance aproximado: Até 10 metros (pode variar conforme ambiente) • Função principal: Transmissão de áudio via Bluetooth ❓ DÚVIDAS FREQUENTES • Funciona em qualquer carro? Sim, desde que o rádio possua porta USB para alimentar o dispositivo. • Precisa instalar aplicativo? Não. O produto é Plug & Play, basta conectar e parear via Bluetooth. • O áudio fica limpo? Sim, oferece transmissão estável e adequada para uso diário. • Pode usar em outros aparelhos? Sim, pode ser utilizado em caixas de som ou dispositivos com porta USB compatível. Garanta já o seu com envio rápido e compra segura pela Shopee. Qualquer dúvida, estamos à disposição no chat.', 49.9, 15.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Bluetooth Transmitters', 'https://cf.shopee.com.br/file/br-11134207-820m4-mphzzaf88feob3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410522123%2F47202974148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22491599051', 'Panela Antiaderente Cerâmica 20cm Cooktop Fogão Indução Avulsa 2,25 Litros Marmol MimoStyle', 'A linha Mármol Cook possui 3 camadas, 2 camadas de revestimento cerâmico e 1 camada resistente a alta temperatura. Com estrutura de alumínio as panelas possuem 4mm de espessura que proporciona uma maior durabilidade do produto, como também mais uniformidade térmica, cozinhando os alimentos de maneira uniforme, sem variações de temperatura. Sem contar que elas também mantêm o calor por mais tempo mesmo fora do fogo, possibilitando refeições aquecidas até mesmo à mesa. Com revestimento soft-touch, toque super macio, em seus cabos e alças, confortável ao segurar e previne queimaduras. Disponível em 2 cores, com estética diferente para todos os gostos. Possui fundo triplo que pode ser utilizado nos fogões a gás (em fogo baixo!), elétrico, vitrocerâmico e no cooktop de indução. O sistema de indução funciona através de ondas eletromagnéticas, estimuladas pelas propriedades magnéticas presentes no fundo da panela. Assim, o fogão de indução só aquece quando as duas superfícies entram em contato. Graças a condutibilidade de calor rápida e eficiente do alumínio, cozinhar em temperatura baixa ou média é suficiente, reduz o consumo de gás e energia elétrica. O revestimento cerâmico não deixa o alimento grudar, permitindo o uso de menos óleo, facilitando a limpeza. É livre de metais pesados, e elementos prejudiciais à saúde (PFOA free), por isso possui classificação A (ótima) no inmetro. DESIGN: Foi projetada em alumínio com revestimento cerâmico, possui um fundo triplo para fogão de indução. A frigideira é antiaderente, diminuindo a necessidade de usar azeite e óleo. O cabo possui revestimento com tecnologia soft-touch, toque macio e confortável ao segurar, prevenindo acidentes e queimaduras ADEQUADAS PARA TODOS OS FOGÕES: Nossa frigideira pode ser utilizada em todos os tipos de fogões elétricos, vitrocerâmicos, gás e indução. O material conduz o calor de forma uniforme, reduzindo o consumo de gás e energia, permitindo que você cozinhe os alimentos em fogo baixo ou médio PARA QUALQUER NECESSIDADE: É a aliada perfeita no preparo de suas refeições. Extremamente prática para uso diário, pode ser utilizada no preparo do seu café da manhã ao jantar. Prepare omeletes, ovos mexidos, carnes, vegetais e outros diversos tipos de alimentos com nossa frigideira para completar suas refeições COZINHA SAUDÁVEL: A frigideira possui um revestimento antiaderente, reduzindo o uso e consumo de óleo e azeite no preparo de suas refeições. O seu material permite a condução do calor por igual em toda a frigideira reduzindo também o uso de energia elétrica e gás FÁCIL HIGIENIZAÇÃO: Os produtos indicados para a limpeza do produto são: detergente suave e/ou neutro e água morna. Aplique com um pano macio ou uma esponja de nylon, enxague e seque. Não utilize abrasivos e palha de aço. Não é recomendável o uso em lava-louças, fornos ou micro-ondas.', 239.9, 159.9, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-7rbmj-ll9du5jg5k7xca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F22491599051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207012114', 'Balcão Cozinha MDF Herval Viana, 1 Porta e 3 gavetas, Azul Orion, 120 cm', 'BALCÃO COZINHA MDF HERVAL VIANA, 1 PORTA E 3 GAVETAS, AZUL ORION, 120 CM CARACTERÍSTICAS Marca: Herval Modelo: Viana Tipo: Balcão Cor: Azul Orion ESPECIFICAÇÕES 1 Porta e 3 Gavetas | 100% MDF Estrutura: MDF 15 mm | fixação com minifix, cavilhas e parafusos Abertura das portas: Dobradiças caneco de 35mm com amortecimento Abertura das gavetas: Corrediças telescópicas 300mm Puxadores de metal Pés: Sapatas plásticas Sem divisor de talheres SUPORTE DE PESO 80 kg distribuídos uniformemente ITENS INCLUSOS 01 Balcão MONTAGEM Modelo entregue desmontado DIMENSÕES (AxLxP | Peso) 86,5x120x52 cm | 30 Kg Altura das prateleiras internas: 32,5 cm GARANTIA 06 meses Informamos que, nossas entregas são realizadas somente no térreo, sem serviços de içamento ou subida por escadas, que devem ser negociados diretamente com o transportador ou outro prestador. *NÃO FATURAMOS PARA CNPJ', 928.87, 928.87, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8261e-mlwdg73scooyc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1541406826%2F58207012114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
