INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14071901836', 'Lampada H7 Standard 55w 12v Neolux N499/64210 Farol Principal/auxiliar', 'Lâmpada H7 Standard 55W 12V Neolux N499 / 64210 – Farol Principal / Auxiliar A Lâmpada H7 Standard Neolux N499 (código 64210) oferece iluminação eficiente, confiável e dentro do padrão original, ideal para reposição no farol do seu veículo. Com 55W de potência e 12V, proporciona excelente visibilidade noturna e segurança na condução, sendo indicada para uso em farol principal ou auxiliar. Produto novo, com qualidade reconhecida e instalação simples. Características Técnicas: Marca: Neolux Modelo: H7 Standard Código: N499 / 64210 Potência: 55W Tensão: 12V Aplicação: Farol principal / farol auxiliar Aplicação: Compatível com veículos que utilizam lâmpada H7 55W 12V (Verifique o manual do veículo antes da compra.) Conteúdo da Embalagem: 1 Lâmpada H7 55W 12V Neolux N499 / 64210', 38.29, 38.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/acb53c47186e6e23a9942a0a9cd8e65d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F691145803%2F14071901836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799130617', 'Batedeira Philco Planetária PHP500 Turbo 220V', 'Batedeira Philco Planetária PHP500 Turbo 220VMais do que preparar receitas deliciosas, cozinhar é uma demonstração de amor a todos aqueles que são importantes para você e com a Batedeira Preta você terá muito mais eficiência e praticidade para todos esses momentos! Através de seu movimento de rotação constante combinado com os movimentos de translação, você terá massas muito mais homogêneas em muito menos tempo! Tem controle com 11 velocidades mais função turbo, permitindo você selecionar a velocidade ideal para cada tipo de receita. Sua tigela, em plástico, possui capacidade para 4,5 litros, permitindo o preparo de grandes quantidades de uma só vez! Compartilhar com a família nunca ficou tão fácil! Possui três batedores (massas leves, massas pesadas e claras em neve) para que você possa preparar das receitas mais pesadas às mais leves com muito mais praticidade. Conta com tampa antirrespingos com abertura para adição de ingredientes, que deixará todo o processo mais rápido e higiênico, pois você nem precisará tirar a tampa para adicionar os ingredientes. Claras em neve, chantili, maionese, bolos, pudins, pizzas, pães, você decide o que fazer e a Batedeira Preta prepara! Principais Características - Potência de 700W - 12 velocidades Turbo - 01 tigela de plástico: capacidade 4,5L com alça - Acompanha tampa antirrespingo - 01 Batedor em aço inox para massas leves - 01 Batedor em aço inox para massas pesadas - 01 Batedor para claras em neve - Unidade motora fixa - Botão de articulação - Base antiderrapante e porta fio - Movimento planetário. Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas. Especificações Técnicas Marca: Philco Modelo: PHP500 Cor: Preto Tipo: Planetária Estado: Tigela extra: Não Capacidade da tigela: 4,5 L Potência: 700W Velocidades: 11 Batedores: 3 unidades Função portátil: Não Função turbo: Sim Altura do produto: 33,5 cm Largura do produto: 23 cm Comprimento do produto: 33 cm Peso do produto: 3,452 kg Altura com embalagem: 40,1 cm Largura com embalagem: 38,1 cm Comprimento com embalagem: 22,9 cm Peso com embalagem: 3,86 kg Garantia: 360 Dias', 314.9, 314.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-821ge-mgmmjbjqcqo975', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617519379%2F23799130617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
