INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098670631', 'Escapulário em Ouro 18k piastrine Unissex 65cm', 'ESCAPULÁRIO MEDALHA TAMANHO PEQUENA MASCULINO E FEMININO TRADICIONAL OURO 18K 750 PESO APROXIMADO 1,60 GRAMAS COMPRIMENTO 65 CM MEDALHAS: NOSSA SENHORA DO CARMO E SAGRADO CORAÇÃO DE JESUS TAMANHO 8,00 MM DE ALTURA E 5 MM DE LARGURA ELOS: LARGURA 1,00 MM COMPRIMENTO 2,70 MM Embalagem para presente e com o nosso Certificado de Garantia Eterna de Ouro 18k/750 Você sabia que o ouro puro é muito maleável e frágil não podendo ser usado na confecção de peças? Para isso, uma porcentagem de ouro é misturada a outros metais – na confecção de joias de ouro 18K/ 750, as ligas possuem 3/4 de ouro puro e 1/4 de outros metais, como prata e cobre. (site IBGE) AQUA JOIAS', 2313.24, 1850.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-7rd5v-lwribzy1q7uv65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F21098670631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
