INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17361456271', 'Borracha Ventarola Quebra Vento Gol Parati Voyage Saveiro 1988 1989 1990 1991 1992 1993 1994', 'Os veículos possuem componentes de borracha nas portas, porta malas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Essas borrachas protetoras são conhecidas como guarnição, e, além de serem instaladas no teto e nas portas, também podem ser encontradas nas áreas de contato entre capô, no porta-malas e nos vidros, evitando o contato direto da tampa com a carroceria. Modelos Compativeis: Gol Quadrado – 1988 até 1994 Voyage 2 Portas – 1988 até 1994 Parati Quadrada 2 Portas - 1988 até 1995 Saveiro - 1988 até 1997 Especificações: Modelo: Para Quebra Vento movel com Retrovisor no Quebra Vento O valor é referente a unidade Borrachas na cor preta Produto paralelo de excelente qualidade Itens Inclusos: ESCOLHER LADO DIREITO OU LADO ESQUERDO', 68.06, 68.06, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/342e4823abeb99afc067919ab5844f5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F17361456271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
