INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47756512296', 'Como Fazer Amigos e Influenciar Pessoas - Edição de Luxo Almofadada', 'Como Fazer Amigos e Influenciar Pessoas, de Dale Carnegie, é um dos livros de desenvolvimento pessoal mais vendidos do mundo e leitura essencial para quem deseja melhorar a comunicação, fortalecer relacionamentos interpessoais e alcançar sucesso pessoal e profissional. Com linguagem simples e prática, o autor apresenta técnicas eficazes de comunicação, inteligência emocional, liderança e influência, aplicáveis no trabalho, nos negócios, nos estudos e no dia a dia. O livro mostra como criar conexões verdadeiras, conquistar a confiança das pessoas e gerar oportunidades por meio de atitudes positivas. Um verdadeiro clássico do crescimento pessoal, indicado para quem busca autoconhecimento, habilidades sociais, persuasão e melhores resultados na carreira e na vida. Um best-seller atemporal que já transformou milhões de leitores ao redor do mundo. DESCRIÇÃO DO PRODUTO: ISBN: 9786553100190 Páginas: 208 Largura: 15,1 cm Altura: 23 cm Publicação: 2026 Selo: Camelot Editora Encadernação: Capa Dura Autor: Dale Carnegie', 69.9, 49.9, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/br-11134207-820lo-ml6dgnsozvutfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F47756512296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
