INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397333018', 'Coleção Povos Indígenas do Brasil - Tupiniquins', 'A Coleção Povos Indígenas do Brasil convida crianças a explorar a cultura vibrante dos Tupiniquim, uma das comunidades indígenas mais fascinantes do país. Com ilustrações envolventes e narrativa acessível, este livro infantil oferece uma introdução empolgante à história, tradições e profunda conexão dos Tupiniquim com a natureza, promovendo desde cedo o respeito pela rica diversidade cultural brasileira.', 29.9, 19.95, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rcd9-lrdfamm0cp2h06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F22397333018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199214214', 'Filtro Cabine Ar Condicionado Civic 1996 1997 1998 1999 2000', 'Aplicação: HONDA CIVIC VI 1.6 (D16Y7) - 1996 A 2000 HONDA CIVIC VI 1.6i (D16Y8| LX/ EX/ VTi) - 1996 A 2000 Especificações: Tipo: Filtro de cabine ar condicionado Comprimento: 213 mm Largura: 211 mm Altura: 29 mm Referência: FAAH01 Marca: Japanparts EAN: 7908374408770 Números Originais: OEM - 79831S04003', 40.9, 40.25, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rccs-lstzt1ms70qu45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405317374%2F21199214214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594389502', 'VERMOUTH NOILLY PRAT 750ML', 'Noilly Prat é uma marca de vermute francesa, baseada em Marselha, junto ao mar Mediterrâneo. Sua receita data de 1813, quando um mercador de bebidas chamado Joseph Noilly inspirou-se no processo de maturação do vinho para criá-la. O grande salto no reconhecimento da marca veio junto com a criação do icônico drink Martini, o qual levava o Vermouth Noilly Prat em sua receita. O processo de fabricação do Noilly Prat utlizado hoje em dia é praticamente o mesmo dos anos da fundação da empresa, no Século XIX. É produzido apenas com variedades de uvas brancas, cultivadas na região da Marselha, sendo a Picpoul de Pinet e Clairette as principais. Essas uvas produzem um vinho leve e frutado que então são maturados em grandes barricas de carvalho canadense por 8 meses. Após esse período, o vinho é transferido para barris menores, onde passa mais 1 ano descansando. Durante esse processo, os barris são deixados ao ar livre, sofrendo as influências do clima, expostos ao sol, chuva, vento e frio. O resultado é um vinho seco, encorpado e de coloração âmbar, similar ao Madeira e Jerez. Seguindo o processo, o vinho é mistuado a uma pequena quantidade de suco de uva e destilado de vinho, para suavizar seu sabor extremamente seco. Finalmente, esse líquido é macerado à cerca de 20 ervas e especiarias pelo período de 3 semanas, entre as ervas estão camomila, casca de laranja, noz moscada, coentro e cravo. Nome: Vermouth Prat French Dry Volume: 750ml Origem: França Teor: 18%', 124.99, 99.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meg69nflg64ide', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23594389502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794387180', 'WHISKY BOURBON JIM BEAM WHITE 4 ANOS 1L', 'Whisky Jim Beam White Bourbon é o BOURBON NO.1 DO MUNDO. A Jim Beam foi fundada em 1795 quando Jacob Beam vendeu seu primeiro barril de whiskey. Atualmente é o Bourbon mais vendido no mundo. A destilaria fica localizada no estado americano de Kentucky, e tem sido comandada pela família há sete gerações. Nós sempre produzimos bourbon do nosso jeito, envelhecendo o dobro do tempo que a lei exige. É assim que fazemos história todos os dias.', 125.99, 94.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mehimsrgwvlud3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23794387180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263776613', 'Gelatina Tubes Pinta Lingua 20g - Fini', '"A Gelatina Dr. Oetker Fini Tubes Pinta-Língua leva a experiência da sua sobremesa para outro nível. Com sabor marcante de framboesa azedinho e um efeito especial que pinta a língua, surpreende a cada colherada. É perfeita para quem busca sabor com um toque de criatividade e diversão! Afinal, quem resiste a um doce que deixa lembrança até na língua? Fácil de preparar, basta dissolver em água quente e fria. "', 2.5, 2.5, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-825b7-mqc8432d8yyz3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F992995220%2F58263776613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798130773', 'Filtro óleo Citroen Xsara 1997 a 2005 Wega WUNI-0004', 'Descrição: O Filtro de óleo WEGA WUNI-0004 é uma peça que serve nos veículos ALFA ROMEO 145, 147, 155, 156, 166 / CHEVROLET TRACKER / CITROEN AX, BERLINGO, BX, C3, C5, C6, C8, EVASION, XANTIA, XANTIA BREAK, XM, XSARA, XSARA BREAK, XSARA PICASSO, ZX / FIAT BRAVA, DOBLO, LINEA, MAREA, MAREA WEEKEND, PALIO, PALIO WEEKEND, SIENA, STILO, STRADA, TIPO, UNO / HYUNDAI SONATA / PEUGEOT 106, 205, 206, 208, 306, 307, 405, 406, 407, 607, 806, 807, PARTNER / RENAULT LAGUNA, R21, SAFRANE, TRAFIC / SUBARU FORESTER, IMPREZA, LEGACY, SVX / SUZUKI GRAND VITARA. Confira abaixo as especificações e aplicações detalhadas. Atenção: EMBALAGEM COM 1 UNIDADE Especificações Técnicas: - Altura: 89 mm - Diâmetro externo: 77 mm - Inclui válvula antirretorno: SIM - Inclui válvula de bypass: SIM - Tipo de rosca: M20X1,5-6H Sobre o Peça Aí: Com o Peça Aí, você acha a peça certa para cada carro e compra num só lugar. É o maior estoque digital de peças do país! São mais de 100 mil itens originais e de reposição à sua disposição. Importante: • Dúvidas: Caso tenha qualquer dúvida sobre as aplicações do produto, entre em contato conosco. • Instalação Profissional: Recomendamos que a instalação do produto seja realizada por profissionais especializados. • Responsabilidade: Não nos responsabilizamos por montagens mal realizadas e equívocos de instalação." • Produto novo, original e com nota fiscal.', 52.21, 52.21, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rff5-m96hly15p3td0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343288194%2F21798130773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201799889', 'Verniz De Motor Aerosol Finalizador Vonixx 400ml Silicone Paulista 300ml Spray', '🌟 Bem-vindo! Você está em uma loja especializada em soluções automotivas seguras e confiáveis. Aqui, cada detalhe é pensado para cuidar do que move você: sua família, sua segurança e seus melhores momentos na estrada. 🔥 Verniz De Motor Aerossol Um Novo Escudo De Proteção Imbatível Para o Coração Do Veículo O Verniz de Motor Vonixx protege, dá brilho e renova todas as superfícies do cofre do motor: partes metálicas, plásticas, superfícies pintadas e mangueiras de borracha. Forma um filme levemente lubrificado, resistente a altas temperaturas e com proteção que dura até 6 meses. 🧩 Referências Compatíveis 36059 2011107 📦 Informações do Produto Marca: Vonixx Tipo: Verniz De Motor Aerossol Condição: Novo Estado físico: Líquido Capacidade: 400ml Cor: Transparente Odor: Característico Pronto para uso Não necessita enxágue Secagem rápida Resistente a altas temperaturas Garantia: 90 dias ⚠️ Antes de realizar seu pedido, esclareça suas dúvidas. 🚗 Aplicações Motores automotivos Caixas de roda Peças plásticas e metálicas do cofre Tampa de válvula Componentes que precisam de brilho e proteção térmica ⚠️ Onde Não Aplicar Superfícies quentes Borrachas sensíveis a solventes Partes eletrônicas, conectores e chicotes Pintura externa do veículo ⭐ Benefícios ✨ Realça o brilho original do motor 🔰 Cria película protetora resistente ao calor 🧽 Ajuda a repelir sujeira e poeira 🚫 Evita manchas e oxidação 💎 Acabamento brilhante duradouro 🛡️ Proteção por até 6 meses 🔥 Alta resistência térmica — não amarela, não derrete e mantém o acabamento mesmo sob calor intenso 🛠️ Modo de Usar Certifique-se de que a superfície esteja limpa, seca e fria. Aplique uma névoa leve do produto cobrindo totalmente a peça. Aguarde 15 minutos para secagem. Para acabamento mais fosco, remova o excesso com toalha de microfibra. ⚠️ Aplique em ambiente aberto e com o motor desligado. 🛒 Onde Comprar Garanta seu Verniz De Motor Aerossol em nossas Lojas Oficiais: 🏬 Camillo Parts 🏬 Genuine Automotive 🏬 Edumac Parts Qualidade, suporte e segurança para o seu veículo. 📢 Aviso Legal Proibimos o uso, cópia ou alteração de nossas fotos, imagens e conteúdo presentes nos anúncios. De acordo com a Lei 9.610/98, qualquer violação será tratada legalmente, pois possuímos direitos autorais sobre este material.', 62.6, 41.32, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Brighteners', 'https://cf.shopee.com.br/file/sg-11134201-822wk-mi4j9jtbtmvc31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349667948%2F58201799889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393253162', 'Perfume Acqua Di Gio Masculino Eau de Toilette', 'O Perfume Acqua di Giò Masculino Eau de Toilette é a fragrância de Giorgio Armani assinada pelo famoso perfumista Alberto Morillas, no ano de 1996. Sua combinação de notas cítricas, florais, amadeiradas e oceânicas proporcionam uma sensação de frescor, como estar à sombra de uma árvore no meio do deserto, ou apreciando a natureza de uma ilha distante. Bem versátil, o Perfume Acqua di Giò é indicado para as atividades do cotidiano e é uma ótima pedida em qualquer temperatura. ATRATIVOS - Perfume aromático aquático - Excelente desempenho em dias mais quentes - Giorgio Armani é uma tradicional casa da perfumaria, que já se consolidou como uma das maiores e mais influentes do mundo. Desde quando começou no ramo da alfaiataria, já era sinônimo de elegância, e felizmente os perfumes seguiram o mesmo caminho, com um poder de te transportar para lugares paradisíacos e te fazer apreciar elementos da natureza mesmo numa área urbana.', 599.99, 589.99, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rd3l-lxbdyl6a8ih281', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F23393253162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894517762', 'Kit 4 Rodas Krmai Nivus 2025 Aro 16x6 5x100 Preto com Diamantado Bicos de Brinde S59', 'Kit 4 Rodas S59 Aro 16 5x100 - Kit com 4 Unidades Principais Benefícios: ✅ Qualidade e Durabilidade: Fabricadas com liga leve, essas rodas oferecem alta resistência e desempenho superior, garantindo longa durabilidade e uma direção suave. ✅ Estilo e Design Esportivo: Com acabamento em preto diamantado, essas rodas adicionam um visual moderno e atraente ao seu veículo, destacando-se por seu design esportivo. ✅ Facilidade de Instalação: Com furação 5x100 e offset de 35 mm, essas rodas são ideais para veículos que utilizam essa configuração, proporcionando uma instalação rápida e fácil. Características do Produto: ✅ Marca: KRMAI ✅ Modelo: NIVUS 2025 ✅ Tamanho: Aro 16 ✅ Quantidade: 4 ✅ Largura/Tala: 6” ✅ Furação: 5x100 ✅ Offset: 35 mm ✅ Material: Liga Leve ✅ Acabamento/Cor: Preto Diamantado ✅ Inclui Calota: Sim ✅ Selo INMETRO: Sim ✅ Nota Fiscal: Sim Itens Inclusos no Pacote: ✅ 4 Rodas KRMAI Aro 16 5x100 ✅ 4 Bicos de Ar Outras Informações: ✅ Produto Novo: 0 km ✅ Tipo de Veículo: Compatível com veículos que utilizam furação 5x100 Compatibilidade: Ideal para veículos com furação 5x100 que necessitam de rodas aro 16. Observações: Verifique a compatibilidade com seu veículo antes de realizar a compra. Produto de alta qualidade, com excelente desempenho e design esportivo. Para dúvidas, estamos disponíveis para atendê-lo diretamente.', 3489.26, 3489.26, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Wheels', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfmwnryfwtfr78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F22894517762', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298933863', 'Kit Vonixx Para Limpeza Interna Sintra Fast + Tryon + Aplicador+Pano e Pincel', '🚗 Kit Completo Vonixx – Limpeza, Higienização e Restauração Profissional Inclui: ✅ Sintra Fast Vonixx 500ml – Limpeza Interna com Ação Bactericida e Fungicida ✅ Tryon Vonixx 500ml – Restaurador de Plásticos e Borrachas ✅ Pincel Automotivo Interno ✅ Pano Toalha Microfibra 40x40cm – 230gsm (cor sortida) ✅ Aplicador de Espuma Zacs Roxo 🧴 Sintra Fast Vonixx 500ml 🔹 Multilimpador flotador universal, bactericida e germicida, pH balanceado. 🔹 Indicado para limpeza de painéis, laterais e cantos de portas, couro, carpetes e estofados. 🔹 Remove manchas de gordura e sujeiras diversas. 🔹 Elimina microrganismos causadores de doenças e diminui maus odores, tornando o interior do veículo mais saudável. 🧴 Tryon Vonixx 500ml 🔹 Condicionador de plásticos 3 em 1 (internos, externos e borrachas). 🔹 À base d’água com SiO₂, proporciona alta durabilidade. 🔹 Proteção: plásticos internos até 12 meses, externos até 3 meses e borrachas até 6 meses. 🔹 Proporciona renovação, hidrorrepelência e proteção UV. 🖌️ Pincel Automotivo Interno 🔹 Cerdas macias e flexíveis para superfícies delicadas. 🔹 Cabo plástico resistente e ergonômico. 🔹 Ideal para limpeza detalhada de cantos e áreas de difícil acesso. 🧽 Pano Toalha Microfibra 40x40cm – 230gsm 🔹 Alta absorção, não risca superfícies. 🔹 Ideal para limpeza geral, vidros, eletrônicos, óculos e acabamento automotivo. 🔹 Cores sortidas enviadas conforme disponibilidade de estoque. 🟣 Aplicador de Espuma Zacs Roxo 🔹 Disco com formato ergonômico. 🔹 Aplicação uniforme, evitando desperdício e manchas. 🔹 Perfeito para restauradores, ceras e protetores. 🔧 Informações Técnicas Marca: Vonixx Condição: Novo Embalagem: 500ml cada Estado Físico: Líquido Cor: Verde (Sintra Fast) Odor: 