INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42228926259', 'Carrinho De Ferramentas S/ Fechamento 1 Gaveta VD2018 Vonder', 'Carro de ferramentas compacto e prático indicado para organização de ferramentas em oficinas e garagens. O modelo VD2018 da Vonder possui uma gaveta para armazenamento rápido, design sem fechamento para acesso imediato e facilidade na visualização das ferramentas. Ideal para profissionais e hobbistas que precisam de mobilidade e agilidade no trabalho, facilita o transporte entre bancadas e pontos de serviço, otimizando o fluxo de trabalho e poupando tempo na busca por ferramentas. Características: Marca: Vonder Modelo: 6160002018 Benefícios: Organiza ferramentas de forma prática e acessível Acesso rápido às ferramentas sem mecanismo de fechamento Melhora a eficiência no local de trabalho Fácil movimentação e posicionamento na oficina Conteúdo da embalagem: 1 Carro de ferramentas sem fechamento com 1 gaveta (VD2018)', 949.78, 731.02, NULL, 'Home & Living > Tools & Home Improvement > Trollies', 'https://cf.shopee.com.br/file/sg-11134201-8262u-ml6qbwroxiiof2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F42228926259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
