INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23591954341', 'Antena Corta Pipa Moto Universal Retratil Anti Cerol M5b', 'Antena Corta-Pipa 6 Estágios + Chave Alen p/ Ajuste Características: - 6 Estágios; - 60cm; - Tubos em Aço Inox; - Ponteira que corta a linha; - Produto patenteado MU-8702188-9 Especificações: - Ponteira Desing moderno e seguro. - Lâmina Desenvolvida para total eficiência na hora do corte. - Tubo Em Aço Inox, possui maior resistência. - Suporte Resistente e permite e reclinação da antena com a moto parada. - Braçadeira Produzida com material especial para uma maior resistência e segurança na utilização. - Parafuso Não espana, permitindo todo ajuste necessário sem danos na peça. - Anel Redutor Permite todo ajuste necessário sem danificar a peça. Montagem: 1. Retire o parafuso com a chave que acompanha o produto. 2. Para guidões de 7/8", utilize o redutor que acompanha o produto. * Atenção: Não manusear os estágios bruscamente, evite a quebra por mau uso.', 52.9, 42.32, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Side Mirrors', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mggiq1r4543r72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F23591954341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15264395480', 'Rolamento Roda Flange da Coroa Fazer 250 / Fazer 150 / Factor 125 6004 Nachi', 'Rolamento Nachi 6004 Original Japonês – Alta Precisão e Durabilidade O Rolamento da Nachi é fabricado com materiais de alta qualidade e precisão japonesa, garantindo excelente desempenho, durabilidade e segurança para sua motocicleta. Desenvolvido para proporcionar uma rotação suave e reduzir o atrito, contribui para uma condução mais estável e confortável. Ideal para reposição, oferece alta resistência ao desgaste e confiabilidade mesmo em condições severas de uso. Compatível com HONDA: CG 150 TITAN Roda Traseira 2015 em diante CG 150 FAN - Roda Traseira 2015 em diante NXR 150 BROS - Roda Traseira 2015 em diante CG 160 TITAN - Roda Traseira CG 160 FAN - Roda Traseira CG 160 START - Roda Traseira NXR 160 BROS - Roda Traseira Conteúdo da Embalagem: 01 Rolamento - 6004 G2DSE - Gaiola de Resina Poliamida dos dois lados (vedação de borracha). Códigos Originais (OEM) do Rolamento: 91053-KVS-F011 Medidas do Rolamento: - Diâmetro anel interno : 20 mm - Diâmetro anel externo: 42 mm - Largura: 12 mm Especificações Técnicas: - Marca: Nachi - Modelo: 6004 - Material: Aço de alta resistência - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Confeccionado com a melhor matéria-prima - Material leve e resistente - Ótimo acabamento, proporcionando uma instalação sem adaptações - Excelente qualidade e acabamento - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Elaborado com matéria-prima de alta qualidade - Testado e aprovado dentro das normas de segurança. A Nachi é uma tradicional fabricante japonesa de rolamentos, reconhecida mundialmente pela alta precisão, resistência e confiabilidade. Seus produtos são utilizados em aplicações industriais e automotivas que exigem elevado padrão de qualidade. Importante: - Recomendamos que a instalação seja realizada por um profissional especializado. - Verifique se as medidas e o formato do retentor, se é o mesmo da sua moto. - A etiqueta do produto não contempla todas as aplicações possíveis. - Não nos responsabilizamos pelo mau uso do produto. - Todas as imagens utilizadas são fotos reais do produto. Não autorizamos o uso de nossas fotos por terceiros.', 59.9, 53.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824j6-mptjczjwhkwd30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F15264395480', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
