INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17542363199', 'Moldura 2 DIN 7" Kia Sorento 2010-2012 Preta Fiamon 3169', 'Bem-vindo(a) a AT4U! Moldura 2 DIN Kia Sorento 2010-2012 Preta 3169 Quer instalar um DVD Player ou Central Multimídia no seu carro? Temos a opção certa para você, esta moldura de painel é perfeita para você que quer ter aparelho 2 Din no seu carro, com total praticidade e aproveitar toda a comodidade e entretenimento que estes equipamentos podem oferecer. Possui encaixe perfeito que facilita a instalação e não necessita de adaptações no painel, garantindo sua originalidade, mude o design interior do seu carro sem muito trabalho e com o melhor custo benefício do mercado. Compatível: - Kia Sorento 2010 à 2012 Especificações Técnicas: - Acabamento na cor Preta. - Padrão: Japonês / Chinês - Tamanho: 7" - Modelo: 2 Din-3169 Material de alta qualidade. Excelente Acabamento. Longa Durabilidade. Fácil Instalação. Conteúdo da Embalagem: 01 Moldura 2 DIN Kia Sorento 2010-2012 Preta 3169 IMPORTANTE: * Postagem em até 24h. * Entrega Garantida. * COMPRE COM SEGURANÇA. * Tire suas dúvidas via chat com nossos especialistas.', 330.05, 330.05, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Cup Holder and Organizers', 'https://cf.shopee.com.br/file/sg-11134201-7qvg9-ljencvfvclmb6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349249646%2F17542363199', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253843728', 'Vinho Terrazas Reserva Malbec Argentino Tinto 750ml', 'O Terrazas de Los Andes Malbec é um dos tintos ícones da vitivinicultura argentina, produzido pela tradicional vinícola Terrazas de los Andes na região de Mendoza. Com foco na expressão pura da uva Malbec em vinhedos de alta altitude, este rótulo entrega intensidade aromática, equilíbrio e profundidade de sabores, resultando em um tinto elegante e envolvente — ideal para harmonizações gastronômicas e momentos memoráveis.', 133.28, 112.99, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjspby9nmcjqb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1640913654%2F58253843728', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9699746071', 'Suporte de Xícaras Suspenso Verde Oliva Bel', 'O Suporte de Xícaras Suspenso Verde Oliva Bel foi desenvolvido para armazenar suas xícaras e outros utensílios de maneira prática e segura, proporcionando aumento de espaço nos armários e melhor disposição na dinâmica de uso. Suporta até 8 xícaras ou 4 canecas. Além das xícaras, o Suporte de Xícaras Suspenso Verde Oliva Bel pode ser utilizado para ordenar diferentes itens como vassouras, rodos, gravatas, cintos, chaves, entre outros. O suporte é móvel, durável e de fácil instalação, tornando seu dia a dia muito mais prático e ágil. O Suporte de Xícaras Suspenso Verde Oliva Bel é produzido em aço carbono com pintura eletrostática a pó (epóxi), garantindo assim a qualidade e durabilidade do mesmo.', 16.9, 16.9, NULL, 'Home & Living > Home Organizers > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rasi-maisqx6o24iq1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F9699746071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
