INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51911192973', 'Secador de Cabelo Silencioso 1600W Britânia', '***PRODUTO A PRONTA ENTREGA COM ENVIO IMEDIATO*** PRODUTO ORIGINAL COM NOTA FISCAL O Secador de Cabelos Britânia BSC3400 foi desenvolvido para oferecer secagem rápida, confortável e eficiente no cuidado diário com os cabelos. Com potência de 1600W, proporciona alto desempenho na secagem, ajudando a reduzir o tempo de uso sem abrir mão da praticidade. Seu motor BLDC oferece maior durabilidade, vazão de ar intensificada e funcionamento mais silencioso, tornando a experiência de secagem mais agradável. A tecnologia Silence Turbo garante fluxo de ar potente com menor ruído, ideal para quem busca conforto durante a rotina de beleza. Conta com 3 temperaturas, 3 velocidades e jato de ar frio, permitindo até 9 combinações para diferentes tipos de cabelo e necessidades de finalização. Informações técnicas: Marca: Britânia Tipo: Secador de cabelos Potência: 1600W Consumo: 1,6 kW/h Cor: Cinza Níveis de temperatura: 3 Níveis de velocidade: 3 Combinações de uso: Até 9 combinações Motor: BLDC Tecnologia: Silence Turbo Recurso: Íon Tourmaline Jato de ar frio: Sim Grade traseira removível: Sim Alça para pendurar: Sim Comprimento do cordão elétrico: 2 metros Conteúdo da embalagem: 1 Secador de Cabelos Britânia BSC3400; 1 bocal concentrador; 1 manual de instruções Garantia: 3 meses contra defeitos de fabricação Tenha mais potência, conforto e praticidade para secar e finalizar seus cabelos com resultado rápido e eficiente.', 396.9, 304.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-823po-mopw500xwav6f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F51911192973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
