INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593001534', 'Jogo 4 Pneus Continental Aro 14 ContiPowerContact 175/65R14 82T', 'Marca: CONTINENTAL Modelo: CONTIPOWERCONTACT Medida: 175/65R14 Largura: 175 Perfil: 65 Tamanho de Aro: 14 Índice de peso: 82 - 475 kg, 82 Índice de velocidade: T - 190 km/h, T Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: ASSIMÉTRICO UTGQ: 480AB Adesão à àgua: C Eficiência energética: E Ruído externo: 70 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Desenvolvido para equipar carros compactos e médios, o pneu Continental ContiPowerContact oferece qualidade de sobra para o uso diário, seja urbano ou rodoviário, com muita segurança e conforto. Possui banda de rodagem assimétrica e composto da 4ª geração de sílica, que em conjunto fazem com que o pneu tenha ampla área de contato com a pista, porém com desgaste reduzido, devido à baixa resistência ao rolamento, o que também ajuda no consumo de combustível, resultando em menor emissão de CO2 e aumento da vida útil do pneu. Sobre a marca Continental A marca Continental foi fundada em Hanover, na Alemanha em 1871. Os pneus Continental são referência mundial em desempenho e qualidade, equipando os mais modernos e sofisticados carros. São usados como pneu original de fábrica em marcas como BMW, Mercedes e Porsche, tanto com pneus comuns quanto em pneus RunFlat. Seja em pneus para carros de passeio, carros esportivos, utilitários, a Continental oferece inovações e a garantia de segurança total nos trajetos realizados.', 1727.52, 1589.32, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdy5-lxlb6q2b7z4v52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23593001534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
