INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56805573854', 'Fundamentos da Teologia Reformada - Augustus Nicodemus', 'Descrição Fundamentos da Teologia Reformada é escrito pelo teólogo e pastor Augustus Nicodemus Lopes e publicado pela Editora Vida Nova. A obra apresenta uma exposição clara e pastoral dos 33 capítulos da Confissão de Fé de Westminster (1647), considerada uma das mais importantes sínteses doutrinárias da tradição reformada. O autor conduz o leitor por uma análise detalhada dos fundamentos da fé reformada, abordando temas como: • Autoridade das Escrituras • Doutrina de Deus e da Trindade • Cristologia e obra redentora de Cristo • Justificação, santificação e perseverança dos santos • Igreja, sacramentos e culto • Escatologia e esperança cristã Com linguagem acessível e sólida fundamentação bíblica, o livro é indicado para estudantes de teologia, líderes cristãos e todos que desejam aprofundar-se na tradição reformada. Ficha técnica Título: Fundamentos da Teologia Reformada Autor: Augustus Nicodemus Lopes Editora: Vida Nova EAN/ISBN: 9786559673919 Ano de publicação: 2026 Idioma: Português Formato: Brochura Dimensões: 23 cm x 16 cm Peso: 1,1 kg Número de páginas: 704 Categoria: Teologia Reformada, Doutrina Cristã, História da Igreja Indicação etária: Adultos Palavras-chave fundamentos da teologia reformada, Augustus Nicodemus, Editora Vida Nova, confissão de fé de Westminster, teologia reformada, doutrina cristã', 131.71, 131.71, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2cte4rskxvd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F56805573854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
