INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3869673712', 'Sandalia Infantil Masculina Minipasso Papete Infantil Menino', 'Sandalia Infantil Masculina Papete Minipasso Nada melhor que ter os pezinhos frescos e soltos, não é mesmo? O Chinelo Infantil masculino é uma excelente opção para deixar os pequenos brincarem com os amigos em dias mais quentes. Por serem mais descontraí­das, a papete masculina infantil combina sempre com um short e com looks para passeios e com os dias de brincadeira com os amigos. Por serem frescas e confortáveis, as sandálias são ideais para passeios em família, brincadeiras em grupo de amigos e também para dias mais quentes. O design da sandália infantil masculina ainda traz segurança e conforto para que as mamães e papais deixem os pequenos se divertirem sem medo! Composição do Calçado: Marca: Minipasso Material: Sintético Forro: Sintético Fecho: de Contato Palmilha: Comfort Sola: Micro expandido Tabela de Medidas: Nº 20 – 12,7 CM Nº 21 – 13,3 CM Nº 22 – 14,0 CM Nº 23 – 14,6 CM Nº 24 – 15,3 CM Nº 25 – 16,0 CM Nº 26 – 16,6 CM Nº 27 – 17,3 CM Nº 28 – 17,9 CM Nº 29 – 18,6 CM Nº 30 – 19,3 CM Nº 31 – 19,9 CM Nº 32 – 20,6 CM Nº 33 – 21,3 CM Nº 34 – 21,9 CM Nº 35 – 22,6 CM', 102.9, 59.95, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0vi3c3c9wgwdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F3869673712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
