INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597507824', 'Kit 20 Luminária Painel Plafon Sobrepor Redondo Led 18w Bivolt ELGIN', 'ATENÇÃO!!! ⚠️⚠️O PLAFON DESTE ANÚNCIO JÁ POSSUI DRIVE/REATOR EMBUTIDO (OU SEJA, O DRIVE/REATOR FICA DENTRO DO PLAFON)⚠️⚠️ DESSE MODO É POSSIVEL FAZER A LIGAÇÃO DIRETO NA REDE ELETRICA!!! IMAGEM ILUSTRATIVA, FAVOR CONFERIR O TAMANHO DO PRODUTO ANTES DA COMPRA!!!!!!!!!!!!!!!!!!! *DIMENSÃO: 19 X 19 X 2,7 Este Plafon LED Sobrepor Redondo 18w proporciona uma excelente iluminação com elegância e sofisticação para seu ambiente, é ideal para ser utilizado em ambientes internos, sobrepor a lajes, paredes e vigas, residências, apartamentos, escritórios, condomínios, estabelecimentos comerciais, vitrines, hotéis, entre outros. Pode ser utilizado em forros de gesso, modulares, forros de madeira, sancas, pvc ou similares. Com material antioxidante, o design desta peça foi pensado para encaixe perfeito, evitando qualquer lacuna para entrada de partículas que possam danificar a instalação. Os plafons LED trazem muita elegância e sofisticação ao ambiente, além de proporcionar ótima iluminação. Uma das principais vantagens do uso da tecnologia led é a alta economia de energia, representam uma economia de 80% na conta de energia elétrica, e em até mais em determinados casos. Outro ponto na economia é referente ao tempo de vida útil do plafon led, com o manuseio e conservação corretos, a lâmpada durará milhares de horas. Isso significa menos descarte no meio ambiente. Até 85% de economia de energia! - Características : * Potência : 18 W * Fluxo Luminoso : 1440 lúmens * Eficiência Luminosa : 80 Lúmens / W * Emissão de Cor : Branco Frio - LUZ BRANCA ( 6500K ), Branco Quente/ Morno - LUZ AMARELA ( 2700K-3000K ) ou Branco Neutro ( 4000K ) ( ATENÇÃO BRANCO/MORNO CORRESPONDEM A MESMA COR DE ILUMINAÇÃO, AMBAS SÃO AMARELAS) * Vida útil nominal de até 25 mil horas * Frequência: 50/60 Hz * Tensão nominal : 100V a 240V. (BIVOLT, serve para 110 e 220v) * DIMENSÃO: 19 X 19 X 2,7 * Material : ABS ( PLÁSTICO ) * Tipo de instalação : Sobrepor. * IRC: >70 * Índice de Proteção : IP20 * Ângulo de Abertura : 120º * Fluxo luminoso constante em toda faixa de tensão. * Temperatura ambiente : -5°C a 40°C. * Fator de potência : >0,50. * Baixo consumo de energia. * Alta Economia de Energia * NÃO DIMERIZAVEL *Imagens Meramente Ilustrativas* ATENÇÃO!!! ⚠️⚠️O PLAFON DESTE ANÚNCIO JÁ POSSUI DRIVE/REATOR EMBUTIDO (OU SEJA, O DRIVE/REATOR FICA DENTRO DO PLAFON)⚠️⚠️ DESSE MODO É POSSIVEL FAZER A LIGAÇÃO DIRETO NA REDE ELETRICA!!! IMAGEM ILUSTRATIVA, FAVOR CONFERIR O TAMANHO DO PRODUTO ANTES DA COMPRA!!!!!!!!!!!!!!!!!!! *DIMENSÃO: 19 X 19 X 2,7 **Garantia de 1 ano com a FABRICANTE do produto**', 536.9, 335.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwwv2l9fnwcy77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1257849357%2F23597507824', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098986681', 'Boneca Disney Princesas Cinderela 38cm com Sapatos Removíveis para Crianças a Partir de 3 Anos Multikids - BR2015', 'Junte-se a uma jornada mágica de aventuras e sonhos com a belíssima Boneca Disney Princesa Cinderela! Essa linda boneca incorpora o espírito de uma Princesa da Disney, inspirando as crianças a acreditarem em si mesmas e perseguirem seus sonhos, encher seu tempo de brincadeira com encantamento! Boneca de 38cm de altura com olhos pintados e sapatos removíveis. Você pode recriar as cenas do filme ou inventar suas próprias histórias mágicas com essa boneca perfeita! Leve Cinderela para onde você for e crie memórias mágicas juntas Características: - Marca: Multikids - Modelo: BR2015 *Imagens Meramente Ilustrativas* Especificações Técnicas: - Largura do produto: 11.43cm - Altura do produto: 38.1cm - Comprimento do produto: 16.51cm - Peso do produto: 635g - Cor: Azul - Faixa etária: +3 anos - Composição do Material: Plástico, Poliéster - Desenvolvimento: Motor Conteúdo da Embalagem: - 1x Boneca Disney Princesas Cinderela Multikids', 174.14, 174.14, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rbl8-lm97488uizf4dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F21098986681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47063286962', 'Brinquedo Infantil Jogo Mordida Feroz Rex Disney Toy Story 5 Toyng - 060235', 'O Jogo Mordida Feroz Rex Toy Story 5 Disney Pixar é perfeito para transformar a brincadeira em momentos de suspense, risadas e muita diversão. Inspirado no personagem Rex, do universo Toy Story, o jogo desafia crianças, amigos e familiares em uma dinâmica simples, interativa e cheia de emoção. A brincadeira funciona de forma divertida: os participantes pressionam os dentes do Rex e precisam contar com a sorte para não serem surpreendidos pela mordida. O jogo estimula atenção, reflexos, coordenação motora e interação social, tornando cada rodada mais animada e envolvente. Produzido pela Toyng, o produto possui material plástico de qualidade e design inspirado na licença Disney Pixar Toy Story. É uma excelente opção para presentear crianças, fãs da franquia e famílias que buscam um brinquedo criativo para momentos de lazer. Destaques: Inspirado no personagem Rex de Toy Story 5 Jogo divertido com mecanismo de mordida surpresa Estimula atenção, reflexos e interação social Ideal para brincar com amigos e família Produto oficial Disney Pixar Ótima opção para presentear fãs de Toy Story Características: Marca: Toyng Modelo: 60235 Tipo de Produto: Jogo infantil de ação Material: Plástico de alta qualidade Idade Recomendada: A partir de 4 anos Imagens Meramente Ilustrativas Conteúdo da Embalagem: - 1 Jogo Mordida Feroz Rex Toy Story 5', 107.68, 96.92, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-825am-mq6a4q89syrm02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F47063286962', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
