INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16441596705', 'Kit Cuidados com o Bebê 6 Peças Rosa 5239 - Buba', 'DESCRIÇÃO DO PRODUTO O Kit Cuidados da Buba foi desenvolvido para cuidar com delicadeza e segurança dos pequenos. Possui tesoura com pontas arredondadas, cortador de unhas, pente e escova, ideais para o dia a dia do bebê. CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: 01 Escova de cabelo / 01 Pente / 01 Tesoura de unhas com capa protetora / 01 Cortador de unhas com aparador de precisão. Dimensões Aproximadas da Embalagem: 21,7 x 16 x 16 cm (Altura x Largura x Comprimento/Profundidade) Material/Composição: Composição: Escova: 40% Plástico, 30% Borracha Termoplástica (TPR), 20% Náilon, 10% Folha de Ferro; Tesoura: 25% Plástico, 25% Borracha Termoplástica (TPR), 50% Aço Inoxidável; Cortador: 70% Plástico, 20% Aço de Carbono, 10% Epóxi. Marca: Buba Referência: 5239 Outras informações: Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 49.99, 37.99, NULL, 'Mom & Baby > Bath & Body Care > Baby Grooming Tools', 'https://cf.shopee.com.br/file/6830c7793c57ffa4b0ab033b92a5ac08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F16441596705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19797414016', 'Macacão Bebê Amore Curto Verão Menina Menino Estampado 100% Algodão', 'DESCRIÇÃO Seu bebê merece esse conforto! O Macacão de Verão com protetor de Ziper é uma exclusividade da Amore pensada especialmente para os pequenos. São macias e confortáveis, feitas com tecido em Suedine 100% algodão, para tornar o dia do seu amor mais alegre e cheio de estilo. DETALHES • Confeccionados com tecido macio em Suedine 100% Algodão • Ziper • Protetor de Ziper TAMANHO • RN = Recém Nascido • P = 3 Meses de Idade • M = 6 Meses de Idade • G = 9 Meses de Idade • GG = 12 Meses de Idade ESPECIFICAÇÕES • 1 Macacão com Ziper A mercadoria é composto somente pelos produtos da descrição acima.', 34.9, 31.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-milx5z9r86wz07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435692544%2F19797414016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207284011', 'Chupeta Unicórnio Magico Rosa Comfort Tamanho 1 22383 - Buba', 'DESCRIÇÃO DO PRODUTO: A Chupeta Buba Comfort Tam 1 Magic Unicórnio combina funcionalidade e um design encantador para proporcionar o máximo de bem-estar ao bebê. Desenvolvida com um escudo ergonômico em tom rosa suave, ela apresenta aberturas estratégicas de ventilação que favorecem a circulação do ar, prevenindo irritações na pele sensível da criança. O bico em silicone macio de alta qualidade garante uma adaptação natural e confortável durante o uso, enquanto a estampa central de unicórnio, acompanhada por uma alça translúcida em verde água, confere um toque moderno e lúdico ao acessório. Totalmente livre de BPA, este modelo une segurança e estilo, sendo a escolha ideal para pais que buscam um produto confiável, durável e com acabamento premium para o dia a dia. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Chupeta Comfort Dimensões Aproximadas do Produto: 4cm x 13cm x 17cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 4cm x 13cm x 17cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Base e Alça: 100% Polipropeno (PP); Bico: 100% Silicone. Idade Mínima Recomendada: A partir de 1 Mês. Alimentação: Não se aplica. Marca: Buba Referência: 22383 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 22.72, 22.72, NULL, 'Mom & Baby > Feeding Essentials > Pacifiers', 'https://cf.shopee.com.br/file/sg-11134201-82607-mm1u9yyp78jod4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.