INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798044459', 'Tim Chip Kit 25 Unidades: 5 Sem Recarga E 20 Com Recarga', 'LOJA OFICIAL TIM UM CHIP. MUITOS BENEFÍCIOS. 5 unidades TIM Pré Chip (Chip Pré Pago sem recarga) 20 unidades TIM Pré XIP Chip + Recarga (Chip Pré Pago com recarga inclusa) Triplo Corte: tamanho compatível com redes e aparelhos 2G, 3G e 4G, Nano, Micro e TIM Chip padrão. Para utilizar a rede 5G NSA é necessário que o aparelho seja compatível com 5G. • Abrangência nacional; • Ligações ilimitadas pra todo Brasil com o código 41. Exemplo: 0 + 41 + DDD + número do telefone; • Para ativar seu TIM Chip, insira o mesmo no aparelho e siga as instruções; • Ao ativar o seu TIM Chip, o DDD será automaticamente cadastrado de acordo com o DDD de sua localização; • Este chip é específico para celulares e não funciona em máquinas de cartão de crédito. Como Ativar o seu TIM Chip: 1. Com o aparelho desligado, coloque o TIM Chip no celular e ligue em seguida; 2. Ao iniciar o aparelho, receberá uma mensagem informando sobre a necessidade de reiniciar o aparelho; 3. Ao reiniciar o aparelho, receberá o número do TIM Chip e o link para ativação; 4. Feito isso, realize o cadastro acessando o link de ativação e preenchendo os dados cadastrais; 5. Por último, valide os dados tirando foto da identidade/CNH ou respondendo a algumas perguntas. Para mais informações sobre planos, ofertas e sumários acesse o site da TIM. Baixe também o App Meu TIM para gerenciar todos os detalhes da sua conta e resolver o que precisar com agilidade e segurança.', 475.0, 439.99, NULL, 'Mobile & Gadgets > Sim Cards', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2v5oo5twetv21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662539995%2F22798044459', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397730145', 'Detergente Para Reservatorio de Agua do Parabrisa Wurth 5g', 'LIMPA PARA-BRISA ECO-W WURTH O LIMPA PARA-BRISA ECO-W é um detergente em pastilha efervescente com a fi nalidade de facilitar a limpeza e o desengraxe dos vidros, removendo insetos, gordura e resíduos. Produto altamente biodegradável, de pH neutro, não agride o vidro nem a borracha. Além da ação de limpeza, ainda hidrata e preserva as palhetas. Seu formato em pastilha foi desenvolvido para reduzir os gastos com solventes/água, reduzir o espaço de armazenagem, diminuir o valor de frete e controlar as doses de aplicação. Características • Produto altamente concentrado, 1 pastilha faz até 2,7 L de produto líquido. • Biodegradável. • Não agride plásticos e vidro. • Limpa a gordura. • Remove insetos e fuligem. • Não deixa o vidro esbranquiçado. • Não ataca a pintura. • Melhora o deslizamento da palheta. Aplicação • Indicado para limpeza dos vidros em automóveis de pequeno e grande porte, caminhões e ônibus. Restrições de uso •Não utilizar mais do que 6 pastilhas no reservatório de uma única vez. Modo de usar • Retire a pastilha da embalagem. • Verifi que se o reservatório está completo de água e sem a tela de proteção. • Introduza a pastilha no reservatório. • Deixe o produto diluir por alguns minutos antes de utilizar.', 29.92, 29.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxk4web9u4527d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F20397730145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897447832', 'Shampoo Desengraxante Tira Graxa da Corrente Lava Moto Vonixx', 'MOTO-V 500ML - LAVA MOTOS CONCENTRADO DESCRIÇÃO: Moto-V é um lava-motos, desenvolvido para limpeza de alta eficiência. Sua formulação equilibrada permite uso, sem agredir, em todas as partes da motocicleta, seja motor, pintura, metais ou plásticos. As possíveis diluições do produto proporcionam ao mesmo a remoção dos mais diversos tipos de sujeira, como barro, lama, graxa e óleo. DILUIÇÃO: Remoção de graxa e óleo – Até 1:10 Lavagem diária da pintura – Até 1:200 Remoção de barro e lama – Até 1:50 MODO USO: 1. Diluir o produto de acordo com a sujeira 2. Realizar pré-lavagem a fim de remover parte da sujeira 3. Em seguida, usar pincel, luva de microfibra ou escovas a depender da superfície e esfregar até o total desprendimento da sujeira 4. Por último, realizar o enxágue com um jato d’água', 43.87, 43.87, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltxyfkva185w42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23897447832', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692573276', 'Pano 2 Lados Toalha Microfibra Automotiva Lustro 600gsm 40x40 Vonixx', 'TOALHA DE MICROFIBRA 2 LADOS VONIXX DESCRIÇÃO: A Toalha de microfibra 2 lados 600gsm Vonixx possui alta gramatura e proporciona um excelente acabamento. Seu tecido remove camadas de ceras, selantes, aplicação de ceras spray e finalização do polimento sem riscar a pintura TAMANHO: 40x40cm GRAMATURA: 600GSM - NÃO RISCA - SUPER MACIA - ALTA ABSORÇÃO', 55.92, 55.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ln1rqd3w9cqsc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23692573276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
