INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497507988', 'Protetor de Carter Peito de Aço Gol G3 G4 MI 8V 16V AT 1.0 Parati 1997 a 2008', 'Revise modelo, ano e lado nas fotos e tabela. Caso tenha qualquer dúvida ou note divergência, fale conosco pelo chat para ajustarmos seu pedido antes do envio e evitar devoluções. A Kyodai Acessórios é a número 1 em variedade e agilidade no segmento automotivo. Aqui você encontra produtos selecionados com a melhor qualidade e o MELHOR custo-benefício do mercado. Tudo pensado para quem exige confiança, eficiência e resultado. PRODUTO 1ª LINHA (NÃO É ORIGINAL) ** Compare o produto com a peça original de seu veículo antes de realizar a compra ** VISÃO GERAL: Protetor de Carter Peito de Aço Para Volkswagen Gol e Parati. COMPATÍVEL: Volkswagen - Gol (G3 / G4) 1997 a 2008 *MI 8V / 16V / AT 1.0* Volkswagen - Parati 1997 a 2008 ESPECIFICAÇÕES TÉCNICAS: Cor: Preto Material: Aço Aplicação: Carter de Óleo Fixação por Parafusos Excelente Acabamento Feito Sob Medida A instalação deve ser feita por um profissional, pois a loja não se responsabiliza por uso inadequado ou montagem incorreta. As imagens são ilustrativas, e o uso de fotos ou vídeos da loja por terceiros não é permitido. Em caso de devolução, siga corretamente o processo dentro do prazo da plataforma e não encerre por conta própria, pois após o vencimento, os custos serão de responsabilidade do comprador.', 130.76, 122.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdoygeion7w9d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F23497507988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
