INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897279540', 'Kit 2 Esmaltes de unhas com efeito gel essence - Diversos', '✨ ESMALTE DE UNHAS GEL NAIL COLOUR Unhas com brilho intenso e acabamento de salão em poucos minutos. Os esmaltes Gel Nail Colour da essence possuem fórmula com efeito gel que proporciona cor vibrante, longa duração e um brilho incrível. Seu pincel patenteado Double Touch garante aplicação fácil e uniforme, alcançando toda a unha com precisão. Além disso, a secagem é super rápida, permitindo unhas perfeitas em pouco tempo. A fórmula também segue as diretrizes de beleza limpa, é vegana e livre de microplásticos, trazendo mais consciência ambiental sem abrir mão da performance. 💅 Efeito Gel Profissional Cor intensa, brilho extremo e acabamento sofisticado. ✨ Brilho Intenso e Longa Duração Unhas com aparência de manicure de salão. 🖌 Pincel Patenteado Double Touch Aplicação mais fácil, uniforme e precisa. ⚡ Secagem Rápida Seca em aproximadamente 40 segundos. 🌿 Beleza Limpa e Vegano Fórmula com poucos ingredientes, livre de microplásticos e com impacto ambiental neutro*. 💡 Dica de Aplicação Para unhas dignas de salão, aplique uma base antes do esmalte e finalize com um extra brilho. 🌿 Sobre a Marca A essence é a marca nº 1 na Europa em unidades de cosméticos*, oferecendo qualidade com preço acessível. 100% livre de crueldade animal desde o início, com forte compromisso com produtos veganos. Acreditamos em uma beleza divertida, acessível e responsável. Para a essence, cada pessoa é única — o perfeito é ser você. *Marca de cosméticos em unidades.', 25.8, 24.51, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/br-11134207-820lb-mn4gciqxu684d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816819540%2F22897279540', NULL, NULL, '2026-07-28T02:1