INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9696326592', 'Subwoofer 15 Eros E-15 SDS 2.7K - 1350 Watts RMS - 4 Ohms', 'Se você deseja equipar o sistema de som do seu carro com peças capazes de reproduzir tanto sons graves quanto sons agudos em boa qualidade, o Subwoofer 15" Eros E-15 SDS 2.7K Black - 1350 Watts RMS é o equipamento que você precisa. Ele foi desenvolvido para impedir que o som fique distorcido ou abafado demais. Ele conta com potência máxima de 1350 Watts e potência musical de 2700 Watts. Ajuda a aumentar o som projetado pelas caixas de som, para quem gosta de volume ou simplesmente para quem precisa de um alcance maior. Especificações Técnicas: • Potência: 1350 Watts Rms • Potência Musical: 2700 Watts • Impedância: 4 Ohms • Resposta de Frequência: 30 ~ 1000Hz • Diâmetro: 15" • Resistência(Re): 2,8 ou 5,8 Ohms • Frequência de Ressonância: 43,75Hz • Área do Cone: 0,085 Sq.m • Volume Equivalente: 81,97L • Diâmetro da Bobina: 4" • Material do Fio da Bobina: Cobre • Secção do Fio da Bobina: Redonda • Material da Carcaça: Alumínio Conteúdo da Embalagem: • 01 Subwoofer 15" Eros SDS 2.7K 1350 Watts Rms - 4 Ohms • Manual e Certificado de Garantia Importante: • Garantia de 273 Dias.', 1499.9, 1409.91, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rd6g-lwhieuohg8l223', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F9696326592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253592437', 'Tenda Gazebo 2x2 Desmontável Fácil de Montar Reforçada Eventos Festas Aniversários Casamento Proteção Uv Branca', 'CARACTERÍSTICAS: Dimensão: 2m x 2m Altura: 1,90m Material Cobertura: Polietileno FPS60 Estrutura: Tubos Aço Pintura Epóxi Peso: 4kg Cor: Branca A Tenda Gazebo Tubular Bel é perfeita para quem busca sombra e conforto em atividades ao ar livre. Com cobertura em polietileno que bloqueia até 60% dos raios UV, ela protege contra o sol intenso, ideal para famílias em praias ou piqueniques. Sua estrutura tubular em aço com pintura epóxi garante durabilidade e resistência ao tempo, montando rapidamente sem ferramentas especiais. Leve e portátil, pesa apenas 4kg e vem com sacola para transporte fácil. Use em jardins, piscinas, campings ou eventos, desmontando em minutos para guardar compacto. Invista em qualidade Bel para momentos seguros e agradáveis ao ar livre, com garantia de 3 meses. BENEFÍCIOS: Proteção Solar: Bloqueia 60% raios UV, evitando queimaduras e garantindo conforto prolongado Fácil Montagem: Encaixe rápido sem ferramentas, pronta em menos de 5 minutos para uso imediato Portabilidade: Leve 4kg com sacola inclusa, ideal para transportar em viagens ou eventos DIFERENCIAIS TÉCNICOS: Estrutura Resistente: Aço epóxi anti-corrosão, suporta ventos moderados e uso frequente em ambientes externos O QUE ESTÁ INCLUSO? 1 Tenda Gazebo Tubular Bel 2x2 Polietileno Branca, espeques metálicos, tirantes e sacola transporte O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes', 349.9, 269.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjodd61ps4qq2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F58253592437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
