INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16786623222', 'Wella Invigo Sun Leave In 150ml', 'Wella Professionals Invigo Sun Leave-in para cabelos expostos ao sol. Wella Professionals Invigo Sun proporciona suavidade, maciez e proteção dos fios contra raios UV. Leave-in Wella Professionals Invigo Sun evita e recupera os danos causados pela exposição solar e outros fatores externos. Sua fórmula contém Sun Blend, vitamina E, pró vitamina B5, que auxiliam na hidratação, reparação e recuperam o aspecto saudável dos fios. Além disso, traz uma fragrância luxuosa de flor de laranjeiras que possui uma essência moderna floral e frutada para um verão refrescante.', 189.0, 179.55, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/ec611c506fc3393dc4dce9cc1e268840', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F456811696%2F16786623222', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49306303597', 'Kit Xêrosa Vibes Pop com Shampoo + Condicionador e Body Splash', 'O kit contém 1 Shampoo 300 ml + Condicionador 200 ml Xerosa Vibes Pop e 1 Body Splash Desodorante para Cabelo e Corpo Vibes Pop 200 ml, da linha Xerosa, ideal para limpar, perfumar e refrescar com fragrância floral envolvente, deixando a pele e os fios suaves, cheirosos e com sensação de frescor. <>INDICAÇÕES$& Para quais tipos de cabelo? Para todos os tipos de cabelo. Qual a indicação? Para cabelos sem perfume, desidratados e com frizz. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Kit Shampoo 300ml + Condicionador 200ml e Body Splash Xêrosa Vibes Pop Possui compostos que trazem frescor, fixação, hidratação e perfumação <>MODO DE USO$& Qual a melhor forma de usar? Kit Shampoo 300ml + Condicionador 200ml Xêrosa Vibes Pop Shampoo: aplique no cabelo molhado, massageie a raiz até formar espuma e enxágue. Se necessário, repita a aplicação. Condicionador 3 em 1 Super Condicionador: aplique nos fios úmidos e massageie do comprimento às pontas. Deixe agir por 2 minutos e enxágue. Creme de Tratamento: aplique mecha a mecha, enluvando os fios do comprimento às pontas. Deixe agir por 5 minutos e enxágue bem. Creme de Pentear/Leave-in: aplique uniformemente nos cabelos úmidos, desembarace com pente de dentes largos e finalize como preferir. Não enxágue. Body Splash Cabelo e Corpo Xêrosa Vibes Pop Agite antes de usar. Borrife o body splash sobre a pele e os cabelos a uma distância de 20 a 30 centímetros, como um spray perfumado. Reaplique sempre que quiser.br> Dica: Para potencializar o perfume, experimente a linha completa. <>CARACTERÍSTICAS$& É produto vegano? O Kit Xêrosa Vibes Pop com Shampoo + Condicionador e Body Splash é vegano. É liberado? Apenas o Body Splash Xêrosa Vibes Pop é liberado.', 62.0, 62.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mkwg6n1d4k5d4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F49306303597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393840628', 'Jogo de 6 Pratos Fundo 20cm Oxford Flora Amor-Perfeito', 'Encante-se pela beleza das flores, traduzida em uma nova linha de porcelanas da Oxford. Batizada Flora, a linha apresenta pratos de espessura finíssima e design de aba larga, decorada com vincos em alto-relevo inspirados nas pétalas das flores. Disponível em seis cores, as tonalidades exclusivas fazem referência à riqueza botânica do Brasil e recebem diferentes acabamentos: reagente, metalizado e brilhante. A decoração Amor-Perfeito exibe um azul intenso, com variações sutis na tonalidade em função do acabamento reagente, que torna cada peça única e especial. Os pratos fundos do conjunto têm abas altas com 6.4 cm de altura e capacidade para 1L. Conteúdo da embalagem: 6 Pratos Fundo 20Cm - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Tipo da embalagem: Papelão pardo - Linha: Flora - Formato de Venda: Kit - Cor: Azul - Forma: Redondo - É apto para lava-louças: Sim - Linha/Decoração: Flora - Modelo: Flora Amor-Pefeito - Unidades por kit: 6 - Material: Porcelana - Decoração: Monocromático - Tipo: Prato Fundo - Uso: Resistente à micro-ondas, Resistente à lava-louças - É Apto para micro-ondas: Sim - Quantidade de peças: 6 - É kit: Sim - Condição do item: Novo - Código universal de produto: 7891361448081 - Diâmetro: 20 cm ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 323.89, 323.89, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-m7mirnuqr2od9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548911108%2F23393840628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23691073707', 'Máscara Matizadora #todecacho Vermelho Cereja 300g', 'AMáscara Matizadora #todecacho Vermelho Cereja hidrata e promove um cuidado profundo, protegendo a formatação dos cachos com efeito vermelho cereja intenso. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos ondulados, cacheados e crespos com texturas grossas, médias e finas. Qual a indicação? Cabelos naturais ou tingidos. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Sua fórmula possui extrato de cereja e provitamina B5 que, juntos, promovem ação extracondicionante, efeito vermelho intenso com nuance rosada de longa duração, brilho e maciez profunda. Além disso, conta com a eficaz tecnologia PROFIX que garante hidratação, força e saúde para cachos e crespos. <>MODO DE USO$& Qual a melhor forma de usar? Com os cabelos limpos e úmidos, aplique a máscara mecha a mecha, enluvando os fios da raiz até as pontas. Deixe agir por 5 minutos e enxágue bem. Dicas de uso Indicado a aplicação fora do banho e como o uso de luvas para evitar a pigmentação nas mãos e unhas Salon Line Indica Antes de usar, faça sempre a prova de toque e o teste de mecha. <>CARACTERÍSTICAS$& É produto vegano? A Máscara Matizadora #todecacho Vermelho Cereja é vegana. É liberado? A Máscara Matizadora #todecacho Vermelho Cereja é liberada.', 28.0, 25.6, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/br-11134207-820mg-mqz5wd0l2sxw7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F23691073707', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
