INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593633716', 'TECLADO MUSICAL 500 TIMBRES E RITMOS, PRETO, MOD: M-T5000', 'TECLADO MUSICAL MIDI M-T5000 Especificações: 61 teclas Possui 500 ritmos e timbres Musica demo Função pitch bend Notas de polifonia Tom e escala de piano 3 modos função aprendizagem Gravação Metrônomo Suporte de partitura • Controles de Tempo e de transposição • Controle de volumes: Principal, Acorde, Acompanhamento e central • Acordes um dedo, vários dedos e acorde desligado • Display de LCD • Teclado estilo Piano • Reprodutor USB • Volume de Acordes • Função Memória • Sustain Pedal (externo/saída de linha) • Alimentação externa: 12Vdc(+) / 100-240Vac • Tamanho do Produto: C96×L37×A14 cm • Peso do Produto: 4.84 kg Com objetivo de oferecer um teclado musical avançado e versátil, ideal para músicos que buscam explorar uma vasta gama de sons, ritmos e recursos para composição, performance e aprendizado aprofundado. Seu diferencial se destaca se com seus 500 ritmos e timbres, a função Pitch Bend, polifonia e a saída para Sustain Pedal, este teclado eleva a expressividade musical, combinando a robustez de 61 teclas estilo piano com modos de aprendizagem, gravação e um display LCD para controle total.', 899.9, 899.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Keyboards & Pianos', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m530x121t7k5fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1418840072%2F23593633716', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
