INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794955057', 'Café Torrado e Moído Torra da Rainha Bridgerton Melitta Gourmet 250g', 'O café Gourmet Melitta Torra da Rainha é uma edição limitada, lançada em colaboração com a série Bridgerton (Netflix), caracterizado por ser 100% arábica com notas de caramelo e nozes. Com torra média-clara, oferece sabor equilibrado e aroma refinado, embalado em três versões colecionáveis inspiradas na era regencial. Perfil de Sabor: Notas de caramelo, nozes e uma leve acidez cítrica. Edição Limitada: Criada para os fãs da série, com foco na sofisticação e rituais. Embalagens Colecionáveis: Três variações visuais que misturam a elegância da série com o design da marca. Ação de Engajamento: As embalagens contêm cartas com mensagens e curiosidades. Disponibilidade: Já disponível em pontos de venda e no e-commerce da marca. Esta parceria busca unir a paixão por experiências marcantes ao universo de romance e elegância de Bridgerton, oferecendo um café de alta qualidade, ideal para métodos tradicionais de preparo.', 30.79, 30.79, NULL, 'Food & Beverages > Bakery > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zuv-mmvy9aomkzr6fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554850%2F22794955057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
