INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093826607', 'Desengraxante Karcher - 1 Litro', 'Desengraxante biodegradável de alta performance 1 litro. Aplicação: Uso em conjunto com lavadoras de alta pressão ou manualmente. Além de não possuir componentes à base de petróleo em sua formulação, é um produto biodegradável. Utilizado na limpeza pesada de graxas e óleos presentes em chassis de veículos, rodas, motores, pisos, carrocerias e equipamentos industriais. *Leia o rótulo antes de utilizar o produto.', 35.9, 30.52, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-81zwn-mikgop767bi8a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F848951954%2F23093826607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
