INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17732731047', '30 Dias de Libertação | Eliezer Magalhães', 'Muito mais que um devocional, 30 dias de Libertação é um livro pra ser estudado sob oração, critério e com espírito quebrantado. Uma obra preparada passo-a-passo repleto de temas que estão ligados diretamente ao nosso dia, bem como traz esperança para o leitor. Ideal para se estudar em grupo e também aplicar no ensino. Autor(a): Eliézer Magalhães Acabamento: Brochura Tamanho da Letra: Normal Número de Páginas: 176 Data de Lançamento: 2018 Altura: 1,0 cm Largura: 14,0 cm Comprimento: 14,0 cm Peso: 0,220 kg ISBN: 9788574594774', 35.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/93c27bc343a97578a1c99f8c471b76ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F17732731047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
