INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43254639121', 'CURREN Relógio Feminino Novo Aço Inoxidável Pequeno Mostrador Moda Simples Negócios Cem Quartzo Analógico À Prova Dwater', 'Bem-vindo à nossa loja ✅⌚Entrega: Todos os pedidos serão enviados dentro de 24h. ✅⌚Pós-venda: melhor solução para seus problemas. ✅⌚Cada fã, amigo e cliente é muito bem-vindo. ✅⌚Espero que você aproveite suas compras. —————————————————————— 💎⌚Característica: -★⌚À prova d''água 3ATM / 30M★⌚(Não opere os botões do relógio na água e não use o relógio em contato com água quente). -★⌚Alta qualidade★:⌚ 100% novo vidro mineral de alta dureza (anti-risco), estojo de alta qualidade durável. -★⌚Ideias de presente: relógios são ótimos presentes, aniversários, aniversários de amigo, amados, dia das mães, presentes de formatura, presentes de dia dos namorados, ou como presentes para trabalho e festas。 💎⌚Especificações: Tamanho do Mostrador - Tamanho do Mostrador(Diâmetro):28mm Espessura do Mostrador - Espessura do Mostrador: 9mm - Tamanho da alça (comprimento): 23 cm Tamanho da alça (Largura): 12mm 💎⌚Descrição do Produto: Marca: CURREN Código do modelo: 9106 X -Material da caixa: liga -Material da Correia: Aço Inoxidável Gênero da moda: mulheres Estilo: Esporte, Casual, Negócios, Moda -Exibição: Analógico 💎⌚Os produtos incluem Relógios genuínos de 100% [sem caixa] 💎⌚Tempo de garantia:Não A loja faz o melhor para resolver o problema para você】 ———————————————————— -★⌚Serviço: 1.Somos o fabricante original. 2.Todos os produtos são 100% novos e originais. 3.Estamos comprometidos em oferecer a você produtos com a mais alta qualidade com preço razoável. 4.Loja dedicada a oferecer uma boa experiência ao cliente! 5.A satisfação do cliente é a busca vital para nós como sempre.', 140.0, 69.99, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-mb223c9a92k1fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392967703%2F43254639121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250272609', 'Selected Poems | Poemas Selecionados | Emily Dickinson | INGLÊS', 'Emily Dickinson wrote over 1,800 poems, but published only a small fraction of them while alive. This collection combines some of her most striking compositions, capturing the fragility of life, the strength of love, and the enigma of death with unparalleled intensity. The poems in this selection have been carefully chosen to reveal the richness of her language and the depth of her themes. With her unique sensitivity, Dickinson invites readers to reflect on the beauty and brevity of human existence.*Emily Dickinson escreveu mais de 1.800 poemas, mas publicou apenas uma pequena fração deles enquanto vivia. Nesta coletânea, você encontrará algumas de suas composições mais marcantes, que capturam com intensidade a fragilidade da vida, a força do amor e o enigma da morte. Os poemas desta seleção foram escolhidos cuidadosamente para revelar a riqueza de sua linguagem e a profundidade de seus temas. Com sua sensibilidade única, Dickinson convida o leitor a refletir sobre a beleza e a brevidade da existência humana.96 páginas15,50x22,6 cm', 15.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821e7-mglq31qtfv2gd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58250272609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250272639', 'Os Meninos de Jo | Louisa May Alcott', 'Dez anos depois de publicar Rapazinhos: a vida em Plumfield com os meninos de Jo, a autora retoma a história dos dramas cotidiano se das façanhas dos meninos travessos mas descontraídos de Plumfield. O livro segue principalmente a vida de meninos apresentados no livro anterior, particularmente Tommy, Emil, Demi, Nat, Dane os filhos os filhos do professor Bhaer e Jo, Rob e Teddy, embora os outros também façam aparições frequentes, e Josie e Bess, duas primas de Demi e Daisy. Agora crescidos, eles precisam lidar com os dramas, as tempestades e as alegrias da vida adulta. Considerado o mais autobiográfico dos livros da série, Alcott tece com brilhantismo sua própria história, de maneira emocionante e com ligeiro tom de melancolia. Os títulos que narram toda a história das irmãs March são: Mulherzinhas, Boas Esposas, Rapazinhos e Os meninos de Jo.352 páginas15,5x22,6 cm', 20.9, 15.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821e2-mglq4h4n44r13d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58250272639', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793824585', 'kit Shampoo Seda Liso Perfeito 300ml + Condicionador Seda Liso Perfeito 190ml', 'Kit Shampoo + Condicionador Seda - Liso Perfeito Seda quer ajudar você a deixar seus cabelos lisos exatamente como você gosta: lindos, macios e alinhados. Por isso, criou o Shampoo Seda Liso Perfeito, com uma fórmula exclusiva enriquecida com proteínas de seda. Ele proporciona hidratação profunda sem deixar os fios pesados, trazendo vida e movimento aos cabelos lisos. Esse é o cuidado ideal para seus cabelos. Apenas Seda Liso Perfeito é capaz de deixar os fios mais sedosos, macios e com um brilho intenso. Além disso, o shampoo contém filtro UV, que protege contra os raios solares, e um perfume delicioso, resultante de uma combinação de flores e frutas naturais. É só usar e arrasar! Para complementar, o Condicionador Seda Liso Perfeito é de uso diário e foi desenvolvido especialmente para cabelos lisos ou alisados que precisam de alinhamento. Com filtro UV e fórmula exclusiva com proteína de seda, ele adere aos fios sem deixá-los pesados, dando vida, movimento e um balanço natural aos cabelos. Além disso, promove secagem rápida após a lavagem, reduzindo o tempo de exposição ao calor e ajudando a evitar danos. Benefícios: - O Shampoo e Condicionador Seda Liso Perfeito conta com Infusão Ativa, uma poderosa combinação de vitamina, óleo e proteína, desenvolvida para as necessidades do seu cabelo - Suas fórmulas contêm, Vitamina C, conhecida por deixar o cabelo liso, Óleo de Macadâmia, conhecido por controlar o frizz, e Proteína de Seda, conhecida por suas propriedades hidratantes - O shampoo e o condicionador Liso Perfeito limpa, hidrata e suaviza os fios, ajudando a deixar seu cabelo perfeitamente liso, visivelmente saudável e com movimento natural - A fórmula do Shampoo e Condicionador Seda Liso Perfeito conta com ingredientes poderosos, que nutrem o cabelo deixando-o alinhado e macio, sem pesar - Esse shampoo e condicionador são indicados para cabelos lisos e desalinhados. Podem ser usados diariamente. Quais os principais ativos? Os ativos principais que a Sua fórmula possui Vitamina C, Óleo de Macadâmia e Proteína de Seda, ambos ajudando no controle de frizz, alinhamento dos fios e propriedades hidratantes. Modo de usar ? Pronta? Coloque o shampoo na mão, aplique no cabelo, massageie suavemente e enxágue. Após o shampoo, aplique o condicionador nos cabelos molhados. Espalhe por todo o cabelo, concentrando nas pontas. Deixe agir por 30 segundos e enxágue bem. Para um cabelo ainda mais incrível, encontre na o Creme para Pentear Seda Liso Perfeito? As garrafas do Shampoo e Condicionador Seda Liso Perfeito são feitas com plástico 100% reciclável. Seda também possui a certificação PETA, o que garante que não são testados em animais em nenhum lugar do mundo.', 32.47, 32.47, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-820lz-mlc2ktwvec5j6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23793824585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098956904', 'Fórmula Infantil NAN Supreme Pro 0 a 6 Meses 400g', 'Fórmula Infantil NAN Supreme Pro 0 a 6 Meses 400g - Nutrição Completa para o seu Bebê Nan Supreme Pro Fórmula infantil para lactentes de 0 a 6 meses, com 4 HMOs, DHA, ARA, Nucleotídeos, proteínas parcialmente hidrolisadas e outros nutrientes essenciais para garantir o crescimento saudável do bebê. Benefícios - Com HMOs (2''-FL, 3’-SL, 6’-SL, LNT): Apoia o fortalecimento da imunidade e a microbiota intestinal do bebê. - Proteínas parcialmente hidrolisadas: Facilita a digestão e reduz o risco de desconfortos gastrointestinais. - Com DHA e ARA: Essenciais para o desenvolvimento cerebral e da visão. - Fonte de ferro e vitaminas: Contribui para o crescimento saudável e fortalecimento do organismo. - Inspirado no leite materno: Fórmula desenvolvida com base em pesquisas científicas para oferecer nutrição completa. - Sem óleo de palma: Melhor digestibilidade e absorção de nutrientes. Para que Serve o NAN Supreme Pro 0 a 6 Meses? -Substituto ou complemento ao leite materno: Para bebês que não podem ser amamentados exclusivamente. -Fortalece a imunidade: Graças à presença dos HMOs, que auxiliam na proteção do organismo. -Apoia o desenvolvimento cerebral e visual: Com DHA e ARA, importantes para a formação neurológica. -Nutrição equilibrada: Contém proteínas e minerais essenciais para um crescimento saudável. -Fórmula de fácil digestão: Com proteínas hidrolisadas que minimizam desconfortos gastrointestinais. Como Preparar o NAN Supreme Pro 0 a 6 Meses Corretamente? 1️.Higienize bem as mãos e os utensílios antes do preparo. 2️.Ferva a água e deixe esfriar até aproximadamente 40ºC. 3️.Adicione a quantidade de água recomendada na mamadeira esterilizada. 4️.Acrescente a medida exata de pó, conforme a indicação do pediatra. 5️.Agite bem a mamadeira até dissolver completamente o pó. 6️.Teste a temperatura no pulso antes de oferecer ao bebê. Atenção: Siga sempre as recomendações médicas para garantir a melhor nutrição ao seu bebê. Por que Escolher o NAN Supreme Pro 0 a 6 Meses? O NAN Supreme Pro 0 a 6 Meses é uma das opções mais avançadas de fórmula infantil, pois combina tecnologia inovadora com ingredientes que se assemelham ao leite materno. Sua composição exclusiva com 4 HMOs, DHA, proteínas hidrolisadas e ferro proporciona uma nutrição equilibrada e fortalece a imunidade do bebê.', 122.54, 122.54, NULL, 'Mom & Baby > Milk Formula & Baby Food > Milk Formula', 'https://cf.shopee.com.br/file/sg-11134201-824ie-mfeajzgi4y6jca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23098956904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599665867', 'Sabonete Liquido Sveda Flor de Cerejeira 500ml', 'O Sabonete Liquido Sveda Flor de Cerejeira limpa e renova a pele promovendo bem estar deixando uma sensação agradável de refrescância e suavidade. Além de possuir um delicado aroma não agride e respeita o equilibrio natural da pele.', 32.48, 32.48, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rd5a-m76yve4i23rda0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F19599665867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898155555', 'Comentário Expositivo Evangelho de João | Capa Dura | Grant R. Osborne', 'Os Comentários Expositivos do Novo Testamento, de Grant Osborne, interpretam as Escrituras verso por verso, construindo uma ponte entre os estudos avançados da academia e a Igreja. Este conjunto de comentários foi pensado para pessoas que buscam uma explicação mais objetiva do texto em seu contexto direto, evitando as intermináveis discussões exegéticas, a simplificação excessiva ou a complexidade mais técnica. O respeitado estudioso bíblico, Grant Osborne, traz à tona as riquezas do Novo Testamento, tornando cada livro acessível aos pastores e leigos em geral que se dedicam ao estudo e ensino das Escrituras. 16x23cm 560 Páginas', 129.9, 116.91, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7ra3l-m5av4138tj4n6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22898155555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
