INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20828843573', 'Kit 2 Trena Tramontina Master 7,5 Metros C/ Fita de Aço - 43156375', 'A Trena Tramontina com Fita de Aço e Corpo em ABS com Freio Duplo 7,5 m é perfeita para quem quer mais praticidade em seu trabalho. A ferramenta possui dois botões de freio e trava, além de contar com retorno automático da fita facilitando no manuseio. Com fita em aço garantindo maior durabilidade e medições mais precisas, a trena tem o corpo em ABS garantindo a leveza que o profissional precisa para se movimentar com o produto. Eficiência e conforto é com a Tramontina! Especificações Técnicas: • Fita em Aço Temperado. • Graduação em Milímetros e Polegadas. • Corpo em Plástico ABS. • Trava Para Fixar a Fita Métrica. • Cinta Para Facilitar o Transporte. • Freio Duplo. • Fita com 3 Rebites Para Maior Segurança. • Todas as Ferramentas de Medição são Inspecionadas e Verificadas Para Manter um Alto Nível de Precisão. • As Ferramentas são Submetidas a Testes de Aplicação Prática Para Garantir sua Resistência em Uso Intenso. • As Ferramentas São Produzidas e Testadas Conforme Normas Específicas. Conteúdo da Embalagem: • 02 Trena Tramontina com Fita de Aço e Corpo em ABS Freio Duplo 7,5 m • Manual e Certificado de Garantia Importante: • Garantia de 273 Dias. • Valor do Kit', 92.21, 86.68, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/939eaea7590826571b7d25b91deef533', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F20828843573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50452555127', 'Mangueira Silicone 7/16 Super Flexível com Engate e Esguicho Alta Resistência para Jardim e Casa', 'Mangueira 7/16" Siliconada Reforçada Anti-Dobras Alta Qualidade com Engate e Esguicho para Lavar Jardim, Casa, Carro entre outros. Chega de mangueiras que ressecam, dobram ou racham! Tenha mais praticidade, resistência e fluxo contínuo de água para o seu dia a dia. DESTAQUES Tamanho ideal de 7 a 40 metros Super flexível – não dobra nem torce Resistente ao sol, calor e tempo 100% silicone de alta durabilidade Compatível com vários tipos de torneiras Fluxo de água contínuo sem interrupções Acompanha esguicho e bicos grátis INFORMAÇÕES Comprimento: 7 a 40 Metros Diâmetro: 7/16 polegadas Material: Silicone siliconado premium IDEAL PARA Limpeza de quintal e calçada Lavar veículos Uso doméstico em geral DÚVIDAS • A mangueira já vem com bicos? - Sim, acompanha esguicho e bicos totalmente grátis. • É resistente ao sol e ao calor? - Sim, o material siliconado premium evita rachaduras e desgaste. • Posso usar em qualquer torneira? - Compatível com diversos modelos, é só conectar e usar.', 69.9, 69.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhw1sax13ojmcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410522123%2F50452555127', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
