INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23324289975', 'Ventilador de Mesa 40cm 127V Preto Multilaser - VL401', 'O ventilador de mesa da Multilaser é um aparelho leve e fácil de transportar entre os cômodos. Conta com uma grade em volta das hélices, o que garante maior proteção e segurança. O motor tem um sistema turbo que gera o vento mais forte. Não sofra com o calor, adquira um ventilador Multilaser Mantenha os ambientes da sua casa mais fresquinhos com esse ventilador de mesa da Multilaser. Os ventiladores de mesa são os grandes companheiros nas épocas de intenso calor. Por essa razão a Multilaser desenvolveu esse aparelho que irá garantir um vento forte e refrescante, para que você não sofra tanto assim quando chegar o verão. Confira mais benefícios desse produto: - potência: antes de qualquer coisa é preciso dar destaque a potência do ventilador. Esse aparelho tem 135 Watts de potência mais um motor turbo que resulta em um vento forte a qualquer hora do dia; - eficiência energética: é importante destacar que esse produto tem baixo consumo de energia. Assim, você pode deixar o ventilador ligado por horas, sem se preocupar com a diferença na sua conta de energia elétrica ao final de cada mês; - design: o seu tamanho é o que ganha maior atenção das pessoas. Afinal ele tem apenas 40 centímetros, o que permite levar o aparelho para qualquer espaço da casa. Além disso, ele vem com 6 hélices junto a uma base antiderrapante que lhe garantem charme e segurança em um único produto. Ficha Técnica Marca: Multilaser Modelo: Ventilador Multilaser de Mesa 40cm Preto VL401 Diferenciais do Produto: Ventilador Turbo muito vento eficiente silencioso Hélice de 6 Pás design Moderno fácil de montar Alimentação: 127V Cor Principal: Preto Altura Produto (cm): 62 Comprimento Produto (cm): 32 Largura Produto (cm): 45 Peso Produto (kg): 2.9', 230.89, 166.55, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-23020-04ny9w6rejnv01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F750964153%2F23324289975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992210404', 'Reparo Original Woofer 10 Eros E-510H 500 Watts RMS - 6 Ohms', 'Reparo Alto-falante Eros E510 H - 500w Rms - 6 Ohms O Reparo para Alto-Falante Eros E510 H oferece a solução ideal para manter o desempenho excepcional do seu alto-falante. Com uma potência de 500W RMS e uma impedância de 6 Ohms, este reparo foi projetado para proporcionar um som potente e claro. Preserve a qualidade do áudio com facilidade, substituindo apenas a parte necessária. Compatível com o modelo Eros E510 H, este reparo é a maneira perfeita de garantir um som impressionante no seu sistema de áudio. Especificações Técnicas: • Compatível com: Alto-Falante Eros E510 H • Impedância: 6 Ohms • Potência RMS: 500W RMS • Potência Musical: 1000W RMS • Resposta de frequência: 100 ~4800 Hz Conteúdo da Embalagem: • 01 Reparo Alto-falante Eros E510 H - 500w Rms - 6 Ohms • Manual e Certificado de Garantia Importante: • Garantia de 90 Dias. • Valor Unitário.', 243.0, 228.42, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lpjsdosmwznre0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F22992210404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
