INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194282363', 'Ração Úmida Fórmula Natural Vet Care Gatos Urinária 100g', 'Ração Úmida Fórmula Natural Vet Care Gatos Urinária ? 100g - Indicado para gatos adultos; - Auxilia na prevenção de urólitos; - Alta palatabilidade; - Variabilidade na dieta. A Ração Úmida Fórmula Natural Vet Care Urinária é especialmente desenvolvida para felinos no tratamento e prevenção de urólitos recorrentes de estruvita e oxalato de cálcio. Com ingredientes selecionados, a ração oferece alta palatabilidade, baixa SSR e Ph controlado. Além disso a ração auxilia para que o felino sinta vontade de ingerir água, cooperando para uma vida saudável. Fórmula Natural Vet Care Urinária Gatos é um alimento coadjuvante.Além de oferecer diferenciais importantes para animais que apresentam recidivas, Fórmula Natural Vet Care Urinária Gatos Úmido ainda oferece benefícios que só um alimento coadjuvante úmido pode proporcionar. Consumo Peso atual Gato (kg)/Quantidade - Peso ideal / Acima do Peso 2 ? 3 150-195 200-260 4 ? 5 235-275 315-365 Composição Água, carne mecanicamente separada de frango, fígado suíno, rim suíno, carne de frango com ossos, plasma sanguíneo desidratado de suíno, glúten de trigo, fécula de mandioca, fibra de cana-de-açúcar, goma xantana, parede celular de levedura, frutooligossacarídeos, inulina, óleo de aves, óleo de salmão, cloreto de potássio, carbonato de cálcio, metionina, taurina, vitaminas, minerais e ácido cítrico.', 18.4, 17.48, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-mcuq6pw7e4862a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F645931940%2F23194282363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
