INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598989590', 'Sabonete Líquido Facial Nupill Firminess 60ml', 'O sabonete facial Nupill Firmness Intensive promove limpeza suave e eficaz para pele seca à normal. Limpa com suavidade mantendo a hidratação essencial para a boa saúde e beleza da pele. Limpa sem ressecar a pele. Remove maquiagem. Enriquecido com PróVit. B5, ou ácido pantotênico mais conhecido como PANTENOL, muito famoso pela sua ação regeneradora da pele. Contém aloe vera (derivado da babosa) que ajuda a sua pele reter a hidratação natural sem oleosidade. Pele limpa, macia e suave. Modo de uso: Aplique no rosto e pescoço, massageando suavemente. Enxágue abundantemente com água. Depois de lavar seu rosto com o sabonete facial Nupill, complemente a limpeza com loção de limpeza facial que higieniza os poros de sua pele. Tonifique a pele com o tônico facial Nupill Firmness Intensive e depois proceda com o creme facial ideal para sua pele. Dica No frio, a pele tende a ficar mais seca e sensível por conta das baixas temperaturas. A primeira alteração que deve ter na sua rotina de skincare é na hora da limpeza, por isso, opte pelo sabonete facial Nupill Firmness Intensive para todos os tipos de pele com a formulação mais suave, que limpa sem ressecar mais ainda a pele. #html-body [data-pb-style="646BA65332DF2"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA65332E06"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 18.21, 18.21, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-7r