INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997312649', 'Tônico Capilar Gota Dourada Fortalecimento Alho 30ml', 'O Tônico para fortalecimento de cabelos Gota Dourada, foi desenvolvido com Óleo de Alho, Extrato de Alho, Extrato de Aloe Vera e Calêndula, que fortalecem a raiz enfraquecida, auxiliando no Combate a queda, caspa, e excesso de oleosidade. Possui na sua composição extrato de Alho, extrato de Aloe Vera e extrato de Calêndula. O Alho fortalece o cabelo, ajuda no combate à queda capilar e é indicado no tratamento intensivo para fortalecer as raízes enfraquecidas, acelerando o crescimento natural dos cabelos. O Aloe Vera, além de ser um hidratante para cabelos, auxilia no tratamento antiqueda. A Calêndula ajuda a combater a oleosidade Modo de uso: Fazer a prova de toque. Aplicar 1 dose somente na raiz dos cabelos, deixe agir por no mínimo 2 horas. Fazer o tratamento 3 vezes por semana, durante 3 meses', 21.28, 21.28, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkzd3eehnhcy08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19997312649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22996921493', 'Kit 6 Cuecas Slip Mash Microfibra Sem Costura 713.02', 'kit 6 cuecas slip mash microfibra sem costura 713.02 as icônicas cuecas boxers mash também são confeccionadas sem costura! com a tecnologia seamless, a cueca boxer microfibra sem costura possibilita muito mais conforto para quem a veste, pois diminui os contatos de fricção entre a pele e a roupa! mas pode ficar tranquilo, pois a falta de costura não tirou a modelagem icônica e moderna das cuecas mash microfibra: aqui, juntamos tecnologia, modernidade e beleza em um só produto! ou seja, proporcionamos a melhor experiência para você!escolha a sua cor favorita e compre agora mesmo este avanço em técnica e conforto no mundo das cuecas! atenção : o kit é enviado com todas as peças somente em uma cor, não é possivel a alteração de cor ou tamanho. características marca: mash material: microfibra linha: sem costura gênero: masculino / adulto modelagem: slip estilo da peça: casual elástico: sem elástico cuidados: recomendamos seguir as instruções de lavagem anexadas a etiqueta. garantia do fabricante: até 90 dias com a apresentação do documento fiscal. embalagem: kit composição: 92% poliamida, 5% elastano e 3% polipropileno sobre a mash presente no dia a dia do homem brasileiro há mais de 50 anos, a mash é referência na categoria de moda íntima masculina não apenas pela tradição, mas também pela alta qualidade, design diferenciado e inovação em tecidos e produtos.', 257.67, 257.67, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-7rbka-llwgul6papmhc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F764761342%2F22996921493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097920340', 'Pistola de Pintura Pulverizadora Elétrica Profissional Portátil 400W 800ml 220V Pró Euro', 'Pistola De Pintura Pulverizadora Profissional 400W 800ml 220V Pró Euro Transforme seus projetos de pintura com a Pistola Pulverizadora Profissional Pró Euro! Com um motor de 400W, esta pistola garante eficiência e praticidade para os mais diversos tipos de superfícies. Ideal para pinturas em madeira, metal, paredes e muito mais. Principais Características: Capacidade do reservatório: 800 ml – para maior autonomia durante a aplicação; Potência: 400W – proporciona uma pulverização constante e uniforme; Vazão ajustável: Máximo de 500 ml/min – ajuste conforme sua necessidade para maior controle; Viscosidade: 40 DIN-S – ideal para diferentes tipos de tinta; Fácil de usar e limpar, garantindo praticidade no dia a dia; Peso aproximado: 1,0kg; Dimensões (C x L x A): 26 x 12 x 27cm. Acompanha: 1 Reservatório 200ml; 1 Medidor de viscosidade. Aplicações: Perfeito para projetos de pintura domésticos e profissionais; Ideal para acabamentos finos em móveis, portões, grades, veículos e muito mais. Compre agora e facilite suas pinturas com a pistola pulverizadora Pró Euro! ATENÇÃO: É recomendada a utilização apenas de tintas com base acrílica.', 239.9, 179.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-820la-mqyv8h26ji1186', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421509827%2F20097920340', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
