INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44600837574', 'Chaleira Elétrica Vintage Verde 1,7 L / Base 360°c / Desligamento Automático - Ariete', 'Chaleira Elétrica Ariete Vintage Verde 1,7L – 1500W | 127V | Estilo Retrô e Elegância Italiana A Chaleira Elétrica Ariete Vintage combina o charme do design retrô com a tecnologia moderna para deixar seu café da manhã ou chá da tarde ainda mais agradáveis. Com linhas suaves, acabamento delicado e detalhes em estilo vintage, ela é perfeita para quem busca funcionalidade com um toque de elegância na cozinha. Com capacidade de 1,7 litros e potência de 1500W (127V), aquece a água em poucos minutos — ideal para chás, cafés, infusões e outras bebidas quentes. A base giratória de 360° permite encaixar e retirar a chaleira com facilidade, enquanto o desligamento automático garante segurança total no uso diário. Além disso, o filtro removível e lavável mantém a água limpa e pura, e o indicador de nível de água visível facilita o controle da quantidade desejada. Suas paredes frias e base estável tornam o uso ainda mais prático e seguro. Especificações Técnicas Modelo: 2869 Cor: Verde Potência: 1500W Voltagem: 127V Capacidade: 1,7 litros Base com giro de 360°: Sim Indicador visível do nível de água: Sim Segurança de paredes frias e base de apoio: Sim Filtro removível e lavável: Sim Desligamento automático: Sim Dimensões (C x A x L): 21,00 x 25,00 x 20,00 cm Peso do produto: 1,16 kg Peso com embalagem: 1,67 kg Destaques do Produto Design retrô elegante e sofisticado Ferve até 1,7L de água em minutos Base giratória 360° para praticidade total Filtro removível e lavável Desligamento automático para mais segurança', 559.99, 559.99, NULL, 'Home Appliances > Kitchen Appliances > Kettles', 'https://cf.shopee.com.br/file/br-11134201-820m3-mqy8fv4eb6knab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F775496126%2F44600837574', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398321769', 'PCP 6.35 T-rex Bullpup Carabina Rossi 250BAR', 'Produto de uso exclusivo em práticas esportivas. ESPECIFICAÇÕES TÉCNICAS: - Nossa loja: AR15 SPORT - Marca da Carabina: Rossi - Modelo: T-Rex Bullpup - Calibre: 6.35mm (.25) - Material da coronha: Polímero - Munição utilizada: Chumbinhos - Mecanismo de ação: Pistão pré-carregado (PCP) - Engatilhamento: Ferrolho lateral - Possui válvula reguladora de pressão - Capacidade do cilindro de ar: 150cc - Pressão máxima de trabalho: 250 BAR (3625 PSI) - Velocidade média: 270 metros por segundo = 885,82fps - Energia máxima: 47 joules - Manômetro acoplado para controlar a pressão - Autonomia: aproximadamente 60 disparos - Trilhos superior e inferior de 20mm - Soleira emborrachada para absorver impacto - Magazine rotativo com capacidade de 9 chumbinhos - Adaptador monotiro para disparos únicos - Supressor de ruídos embutido no cano - Trava de Segurança Manual - Gatilho ajustável com ajuste de peso - Comprimento do cano: 53cm - Comprimento total: 84,2cm - Peso total: 2,300 Kg ITENS INCLUSOS: - 01 Carabina pressão PCP T-REX Bullpup 6,35mm - 01 Manual de instruções - 01 Bico de encher - 01 Magazine rotativo - 01 Jogo de anéis - 01 Adaptador monoshot - 01 Capa Ar15 Sport Acolchoada Preta 120cm - 10 Alvos de Papel Ar15 Sport 14cm x 14cm Observações: Garantia de 12 meses dada pelo fabricante. A velocidade pode variar conforme o chumbinho utilizado. Atenção! Os equipamentos aqui listados servem apenas para uso recreativo NÃO letal. O uso do produto exige treinamento e equilíbrio emocional. Deverá ser guardado em lugar seguro e fora do alcance de terceiros.', 3758.31, 3758.31, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rd4h-m7gxazbttlitc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404617501%2F23398321769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598847599', 'Refletor parachoque traseiro – Grand Siena 2012 a 2020 – Esquerdo ou Direito', 'Refletor parachoque traseiro – Grand Siena 2012 a 2020 – Esquerdo ou Direito Informações técnicas: Lado: Esquerdo ou Direito – Escolha no momento da compra - Posição: Traseiro - Cor: Vermelho - Aplicação: * Grand Siena 2012 a 2020 - Produto Novo - As fotos do produto são meramente ilustrativas. - Este produto não é original. Apenas compatível com o modelo do veículo. - Não nos responsabilizamos e fazemos trocas por mal uso, procurar um profissional para fazer a instalação - Dúvidas? Mandem em nosso chat!', 61.49, 61.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdvwhk1nyadc52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1254320229%2F22598847599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
