INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892776356', 'FAROL BLOCO OPTICO - XTZ 150 CROSSER 2014', 'Blocos Óticos Os Blocos Óticos da NATION são peças de alta qualidade, produzidas com tecnologia de ponta e materiais resistentes e duráveis. Com design moderno e elegante, esses blocos oferecem uma instalação fácil e uma excelente adaptação à motocicleta, além de proporcionar uma iluminação eficiente e segura durante o uso noturno. Além disso, os Blocos Óticos da Plasmoto são altamente resistentes a impactos e vibrações, garantindo a segurança e a durabilidade necessárias para os motociclistas em suas aventuras pelas estradas. Com diversos modelos disponíveis, os Blocos Óticos da Plasmoto são a escolha ideal para quem busca qualidade e desempenho para sua motocicleta. BLOCO OPTICO - XTZ 150 CROSSER 2014', 70.4, 70.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lugs3zw4l5qt16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F22892776356', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994171857', 'Cooler para Notebook Acer Aspire E5-571', 'Cooler para Notebook Acer Aspire E5-571 | Interno Este é um Cooler bringIT compatível com o notebook Acer Aspire E5-571. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.5A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL131-AC-0005', 50.47, 40.39, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-7ra1h-mbfo39c0e1r98f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22994171857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
