INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698113666', 'Capacete Para Moto Pro Tork New Preto E Amarelo 60', 'OCapacete Para Moto Pro Tork New Preto E Amarelo 60é essencial para qualquer motociclista, oferecendo proteção crucial em caso de acidentes. Com uma variedade de modelos disponíveis, cada um projetado para atender a diferentes necessidades e estilos de pilotagem, segurança e conforto em suas atividades Sua viseira transparente permite excelente visibilidade, enquanto o design ergonômico garante conforto durante o uso prolongado. Detalhes do produto: Viseira em Policarbonato: Com espessura de 0,8 mm, a viseira oferece resistência a impactos. Fecho Micrométrico: O fecho micrométrico garante um ajuste seguro e confortável, permitindo que o capacete se adapte perfeitamente à cabeça do usuário. Design Ergonômico: O formato do capacete é projetado para maximizar o conforto durante longos períodos de uso, reduzindo o cansaço. Leveza e Durabilidade: Fabricado com materiais de alta qualidade, o capacete é leve, mas resistente, proporcionando proteção sem comprometer a mobilidade.', 179.9, 110.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-7rfgq-m497sj6kwwez6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F22698113666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
