INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7969841798', 'Anel Bamoer De Prata 925 Sereia Lágrima SCR618', 'Descrição: A Lenda disse que a sereia azul tem a aparência mais bonita e o coração mais gentil, sempre traz boa sorte para as pessoas.】---De Designer Peso: 1,4 gramas Parede: 0,2 cm Material: Platina S925 + Zircão Nome do produto: Rasgo Sereia Nome da marca:Bamoer Número do modelo:SCR618-A Ocasião: Aniversário, Noivado, Presente, Festa, Casamento etc. Fino ou Moda: Moda O pacote inclui: Produto * 1 + saco de veludo de joias/caixa de joias * 1 ⚠⚠ Manutenção de joias de prata: 1. Evite usar ao tomar banho: As joias têm medo de acidez, não pode tocar detergente, evite usá-lo ao tomar banho; 2. Evite o contato com produtos químicos: Lembre-se de não deixar as joias tocarem produtos químicos como cosméticos, pois é fácil reagir quimicamente com as joias para tornar sua superfície manchada; 3. Evite usar ao suar: o suor contém ácidos graxos, ureia e outros ingredientes, que têm efeito corrosivo nas joias; 4. Lenços finos de veludo: Por favor, use um pano de veludo fino para manter as joias brilhantes. Se você não usá-los, coloque-os na caixa de joias. Devido à diferença na exibição do terminal, pode haver uma ligeira diferença de cor entre a imagem do produto e o produto real. Espero que você possa entender. Se você estiver satisfeito com nossos produtos após o recebimento da mercadoria, espero que você possa nos dar uma avaliação de 5 estrelas; Se você tiver algum problema com as mercadorias, sinta-se à vontade para entrar em contato conosco e teremos o maior prazer em ajudá-lo a resolvê-lo.', 53.58, 53.58, NULL, 'Fashion Accessories > Rings', 'https://cf.shopee.com.br/file/4cbb095b40f5a4132d27d5c924104b82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325735487%2F7969841798', NULL, N