INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493252722', 'Esguicho de Alumínio de 1/2" Tipo Jet 76 Cm - Vonder', 'Conteúdo Embalagem: 1 Esguicho Destaques e diferenciais: Produz 2 tipos de jatos e possui alavanca abre e fecha. Devido ao formato do esguicho, com cabo longo em alumínio e um estreitamento na ponta, proporciona maior velocidade na saída da água, fazendo com que o tempo de trabalho seja até 70% menor em comparação a outros esguichos. Possui cabo anatômico e rosca 3/4" fêmea com conector de engate rápido para conexão na mangueira. Aplicações e dicas de uso: Ideal para uso doméstico. Indicado para lavar pisos, paredes, muros, carros, motos, entre outros, e também alcançar locais de difícil acesso. Características Técnicas: Material: Alumínio e borracha Comprimento aproximado: 76 cm Tipo da ponteira: Dupla - 2 jatos Tipo do conector: Rosca 3/4" fêmea com conector para engate rápido de 1/2" Garantia: Garantia legal: 90 dias', 79.9, 79.9, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-lzi5gx84385jf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F22493252722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
