INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9859938269', 'Cortador e Flangeador para Tubos Jogo 6 peças Vonder', 'Conteúdo da Embalagem: 1 Jogo de cortador e flangeador de tubos com 6 peças, sendo: 1 maleta plástica, 1 flangeador, 2 bases de fixação dos tubos, 1 cortador de tubos e 1 rebarbador Descrição: Cortador e flangeador de tubos, jogo com 6 peças, VONDER Aplicações e dicas de uso: Indicado para cortar e flangear tubos de cobre e alumínio Destaques e diferenciais: Possui escareador para a remoção de possíveis rebarbas ou irregularidades Características Técnicas: Capacidade do cortador para tubos de cobre: 1/8" a 1.1/8" - (3 mm a 28 mm) Capacidade do flangeador (base de fixação) para tubos de cobre: 1 Flangeador (base) com as medidas em polegadas: 3/16", 1/4", 5/16", 3/8", 1/2", 5/8", 3/4" + 1 flangeador (base) com as medidas em milímetros: 5 mm, 6 mm, 8 mm, 10 mm, 12 mm, 16 mm, 19 mm Material do corpo do cortador de tubos de cobre: Alumínio Material do flangeador para tubos: Ferro fundido nodular Garantia legal: 90 dias', 470.9, 470.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxv-lzf0bfb0o9bg67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F9859938269', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201291769', 'VOCÊ NÃO DEVERIA ESTAR AQUI', 'VOCÊ NÃO DEVERIA ESTAR AQUI Um romance sombrio e ardente que vai morar em você no novo thriller da autora de Casamento Perfeito Grace Evans mora em Nova York, prestes a vivenciar as dores de um burnout com o trabalho em um banco e a correria da cidade grande. Nas férias, em busca de um descanso em sua vida, ela reserva no Airbnb um quarto em um rancho em Dubois, no Wyoming, Meio-Oeste dos Estados Unidos. Quando chega ao refúgio idílico isolado e cercado pelas Montanhas Rochosas, ela é recebida pelo educado e atraente anfitrião Calvin Wells, que cuida do local após o falecimento dos pais. Calvin está ansioso para apresentá-la aos segredos do seu estilo de vida tranquila nas montanhas, onde se dedica &agrave; criação de vacas, galinhas e ovelhas, além de uma vasta horta nas grandes terras herdadas de seus pais. Ao mesmo tempo em que se sente atraído pelo caubói, Grace percebe que os celulares não possuem sinal e o wi-fi da residência está danificado. A sensação de que há algo de errado naquele rancho só aumenta quando, na gaveta do quarto, ela encontra roupas íntimas que parecem ter sido deixadas pela hóspede anterior. Além disso, as amigas e amigos de Calvin não demonstraram simpatia por ela. Em seguida, conhece Joe, o irmão bronco de seu anfitrião que a trata de maneira estranha. Você Não Deveria Estar Aqui é o explosivo thriller psicológico de Jeneva Rose, a autora do best-seller Casamento Perfeito (DarkSide&reg; Books, 2024) e &ldquo;uma das grandes rainhas das reviravoltas&rdquo;, nas palavras de Colleen Hoover, autora de Verity e é Assim que Acaba. O suspense faz parte do projeto especial E.L.A.S. — Especialistas Literárias na Anatomia do Suspense, que integra a marca Crime Scene&reg; Fiction, da DarkSide&reg; Books e chega &agrave; terceira temporada de lançamentos com mais uma seleção criteriosa das mais criativas e inovadoras autoras contemporâneas do suspense mundial, como Alice Feeney, Tana French, A.R. Torre, Sharon Bolton e Sam Holland, entre outras. Um thriller surpreendente capaz de arrancar suspiros e palpitar corações. Entre trilhas selvagens no rancho isolado e mergulhos revigorantes no rio da propriedade, uma química surge entre Grace e Calvin.', 76.56, 57.8, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/sg-11134201-82284-mhq8sm13o0lfc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F58201291769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
