INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697721359', 'A elite', 'A elite A vida no palácio não era tão ruim quanto america imaginava. Ou melhor com todos os mimos e privilégios que estava tendo, ela já mal se lembrava de como era pertencer à casta cinco. Ser um, em compensação, era fácil suas criadas eram costureiras talentosíssimas e faziam vestidos maravilhosos os banquetes e as festas que frequentava eram incrivelmente divertidos e o conforto em que vivia agora seria impensável alguns meses atrás. Além de tudo, quando sentia saudade de casa, tinha aspen por perto. Ele era compreensivo, companheiro e tinha decidido colocar sua vida em perigo por ela afinal, o que aconteceria se alguém descobrisse que, além de guarda do palácio, era ex namorado de uma das candidatas? Era com aspen que america contava nashoras mais difíceis. Por outro lado, o príncipe maxon era atraente, bondoso, carinhoso e o mais importante desejava america mais do que qualquer outra garota da elite. Mas, além de estar com o coração secretamente dividido, também era difícil lidar com o fato de que aceitar maxon significava ter que aceitar uma coroa. America não tinha certeza se gostaria de ser uma princesa. Apesar da vida glamorosa, havia tantas coisas com as quais ela não concordava e que permaneciam sem explicação por que o palácio sofria tantos ataques rebeldes? O que era reivindicado? Por que os castigos aos infratores tinham de ser tão violentos? O que estava por trás daquele regime de castas tão cruel? O tempo está acabando e as dúvidas de america só aumentam. Informações Adicionais Autor: CASS, KIERA Data Publicação: 01/01/2013 Tipo de capa: Brochura Condição do Item: Novo Subtitulo: A ELITE Idioma: Portugues Páginas: 360 Edição: 2013 ISBN-13: 9788565765121 ISBN-10: 8565765121', 69.9, 55.92, NULL, 'Stationery > Art Supplies > Sketch Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbmk-lplq7zzcwg3n54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22697721359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898370780', 'CENTOPEIA SEM PÉS', 'CENTOPEIA SEM PÉS Lili é uma centopeia especial. Nasceu sem nenhum pé, justamente numa família de muitos pés e, por tradição, responsável pela entrega das correspondências da cidade. Só que o pai da Lili, o senhor Centopeia, teve uma ideia genial fez cem rodinhas e colocou as na filha para que ela pudesse andar. E algo aconteceu, já no primeiro dia de escola, que mostrou para a Lili que ser diferente pode ser algo belo e cheio de possibilidades. Quer descobrir o que foi?. Informações Adicionais Autor: ERALDO, MIRANDA Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: CENTOPEIA SEM PÉS Idioma: INDEFINIDO Páginas: 24 Edição: 1 ISBN-13: 9786555551099 ISBN-10: 6555551097', 56.0, 44.24, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rep5-m8alc8njrwde5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23898370780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299819352', 'AMPLIFICADOR POTÊNCIA ONEAL OP-2800 500W RMS', 'AMPLIFICADOR POTÊNCIA ONEAL OP-2800 500W RMS O OP2800 da Oneal é um amplificador de potência profissional com 500W em 4 ohms, ideal para sonorização de ambientes como bares, igrejas e teatros. Oferece áudio de alta fidelidade com baixa distorção e ampla resposta de frequência (10 Hz a 70 kHz). Possui sistema de ventilação inteligente (ICS), proteção térmica eletrônica (ETP) e contra curto-circuito. Conta com entradas P10 e XLR, saídas P10 para cada canal, controle individual de volume, LEDs indicadores e chave seletora bivolt. Robusto e eficiente, é indicado para aplicações profissionais exigentes. Características: - Marca: Oneal - Modelo: OP2800 - Tipo: Amplificador de Potência Profissional - Classe AB - Cor: Preto - Potência RMS por canal 4 Ohms: 250W - Potência RMS por canal 8 Ohms: 165W - Potência Musical por canal 4 Ohms: 500W - Potência Musical por canal 8 Ohms: 330W - Sensibilidade de Entrada: 775mV - Relação Sinal/Ruído: 100 dB - Distorção Harmônica: 0,03% - Resposta de Frequência: 10 Hz – 70 KHz - Consumo Máximo: 720W - Painel frontal: 02 Alças de Tração, Controle de Volume canal A e B, 3 Indicadores de LED canal A e B, Saída de Ar do turbo dissipador, Botão de acionamento - Conectores canal A traseiro: 01 entrada de áudio P10, 01 entrada de áudio XLR e 02 saídas de áudio P10 4 Ohms - Conectores canal B traseiro: 01 entrada de áudio P10, 01 entrada de áudio XLR e 02 saídas de áudio P10 4 Ohms - Painel traseiro: Ventilador do turbo dissipador, Chave seletora de tensão bivolt, Fusível de proteção, Cabo de energia, Chave lift gnd, Borne de terra - Padrão Rack: 19” de largura - Proteção Contra Curto-Circuito - Proteção Térmica Eletrônica - Sistema de Ventilação Inteligente - Voltagem: 120-240V - Dimensões: 14 cm x 50 cm x 30 cm - Peso: 12,235 kg *Imagens Ilustrativas* *Garantia: 12 Meses*​', 1952.87, 1757.59, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/sg-11134201-7rav5-ma8w4wplnma27e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F18299819352', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
