INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27088778916', 'Sandália Vizzano Papete Feminina Confortável Original 6499', '✨👡 Sandália Vizzano Papete – Conforto, Estilo e Versatilidade 👡✨ A Sandália Vizzano Papete é perfeita para quem busca modernidade e bem-estar em um único calçado. Com design despojado, tiras cruzadas e detalhe em metal dourado na ponta, ela une tendência e conforto para compor produções casuais e cheias de personalidade 🌸💖. Ideal para acompanhar o dia a dia, essa papete é leve, estilosa e combina com looks urbanos, praianos ou descontraídos. 💎 Destaques do Produto: Papete Vizzano super confortável 👡 Design moderno com tiras cruzadas ✨ Detalhe dourado elegante 💍 Solado robusto e estável 👣 Versátil para várias ocasiões 🌟 📏 Ficha Técnica: Tipo: Sandália Papete Marca: Vizzano Material: Sintético de alta qualidade Palmilha: Confortável e macia Solado: Tratorado, resistente e antiderrapante (Altura 5cm aprox.) Fechamento: Fivela ajustável Numeração: 34 ao 39 📐 Tabela de Medidas (em cm): 34 – 23,0 35 – 23,5 36 – 24,0 37 – 24,5 38 – 25,0 39 – 25,5 🧼 Dicas de Limpeza - Limpar com pano úmido e sabão neutro - Não usar máquina de lavar ou secar - Secar à sombra - Evitar produtos químicos agressivos 💖 Por que você vai amar: Uma sandália leve, fashion e aconchegante, perfeita para quem não abre mão do conforto sem perder o estilo 🌸✨.', 179.9, 126.9, NULL, 'Women Shoes > Wedges', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md3blj1ylulu75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F27088778916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999545589', 'Geleia Radiante Aurora Shine By Jade Picon 200g', 'Encante-se com o efeito "uau" da Geleia Radiante Iluminadora Aurora Shine. Sua fórmula em gel, enriquecida com Betaína e Glicerina, desodoriza e proporciona uma hidratação eficaz e refrescante, além de um efeito glow intenso. Pode ser usada durante o dia ou à noite, para iluminar sua pele em qualquer momento e despertar sua essência divina a cada aplicação._x000D_ _x000D_ A glicerina:é um clássico hidratante usado em cosméticos que atrai e retém água na pele._x000D_ _x000D_ A betaína: é um agente de hidratação extraído da beterraba. Fornece aumento rápido e intenso da hidratação e proteção da pele. _x000D_', 169.9, 169.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7repx-m22ncysph6e85e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F20999545589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
