INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251985628', 'Lava Roupas Sanitizante Em Pó Brilhante 1.6Kg', 'Brilhante Limpeza Total apresenta a solução completa para suas roupas! Este lava roupas sanitiza as roupas, combatendo germes e bactérias, e proporciona uma limpeza profunda desde a primeira lavagem. A nova fórmula de Brilhante Limpeza Total combina os melhores resultados de limpeza com a proteção das cores dos tecidos. Possui o poder das enzimas, evitando que a sujeira volte a se depositar nas roupas, e a tecnologia Brilho Ativo que evita o amarelamento das roupas brancas e mantém os coloridos mais vivos.', 22.79, 22.79, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-8259m-mqnekxkqt6haab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554761%2F58251985628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594946969', 'Difusor Taiff Curves - Preto / -', 'Assim como aquele acessório em um look básico, o difusor Curves faz toda a diferença! Ele se adapta aos secadores Taiff de até 2600W e garante cachos definidos e volumosos. Pode ser usado em cabelos crespos, cacheados e ondulados. Possui controle de fluxo de ar que ajuda a definir os cachos e seca o cabelo sem vento e de forma homogenia através do calor. Evita frizz e mantém a forma original dos cachos e ajuda a dar mais volume', 79.9, 79.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-81ztf-mmw3ca8khssjfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1787996512%2F22594946969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210139895', 'Leite Condensado Semidesnatado Italac', 'O Leite Condensado Semidesnatado Italac é um produto cremoso e versátil, ideal para suas receitas doces, sobremesas, confeitarias e cafés especiais. Produzido com leite semidesnatado, ele contém 6% de gordura, oferecendo um equilíbrio perfeito entre sabor e leveza. Perfeito para seus pudins, doces e tortas.', 8.49, 8.49, NULL, 'Food & Beverages > Dairy & Eggs > Milk', 'https://cf.shopee.com.br/file/sg-11134201-825az-mqnellflq5n22a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58210139895', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
