INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9896860698', 'Vela Iridium Cpr8eaix9 Honda Nx 400 Falcon 2013/16', 'Vela iridium: São as velas do tipo IX e possuem ponta de Iridium no eletrodo central, sendo a ultima geração de tecnologia em velas de ignição voltadas a motores de alta performance. O Iridium é um metal nobre que possui alta resistência ao desgaste, possibilitando a redução do diâmetro do eletrodo e melhorando sua ignibilidade e durabilidade. Possui diâmetro de eletrodo central de 0,4mm a 0,6mm. Maior economia de combustível; Maior estabilidade de marcha lenta; Redução na emissão de poluentes; Partidas mais fáceis; Menor possibilidade de falhas de ignição; É uma vela do tipo resistiva evitando interferência em sistemas eletrônicos. As velas de ignição NGK são submetidas às mais severas condições de trabalho nas mais diversas pistas, pelos melhores pilotos e equipes de competição. Essa escolha pela vela de ignição NGK se deve ao alto desempenho de seus produtos, por sua tecnologia de ponta e garantia de qualidade.', 99.9, 99.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/25efec6e68881070a79717c63e6dd821', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545730812%2F9896860698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
