INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198198945', 'Cadiveu Professional Nutri Glow Booster - Fluído de Tratamento 200ml', 'Cadiveu Professional Nutri Glow Booster - Fluído de Tratamento 200ml Pré Shampoo Booster Milagroso formula altamente concentrada rico em óleos e manteigas nutre intensamente os cabelos ressecados, devolvendo a maciez e flexibilidade natural da fibra, o resultado são pontas seladas, frizz controlado e cabelos 8x mais brilhantes*. Conselho de Aplicação Pré Shampoo: aplicar nos cabelos secos, mecha por mecha, no comprimento e pontas (não aplicar rente à raiz). Massagear e deixar agir por pelo menos 30 minutos. Seguir para a lavagem dos fios. Pode ser usado como umectação noturna, para proteção as pontas do suor durante atividades físicas ou sempre que seu cabelo precisar de um tratamento nutritivo poderoso.', 155.65, 155.65, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ratd-ma37cm940hf0c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21198198945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997669064', 'Kit Snorkel de Mergulho Infantil c/ Respiro + Óculos Visão 180º Proteção UV Natação', 'Kit de Mergulho Infantil Máscara e Snorkel Vollo O Kit de Mergulho Infantil Vollo oferece uma experiência incrível de mergulho livre para as crianças. Desenvolvido especialmente para o conforto e segurança dos pequenos, é uma excelente opção para praia ou piscina. A Máscara possui lente única de vidro temperado antiembaçante com proteção UV que possibilita uma visibilidade panorâmica inigualável de 180º, e vedação em silicone super macio que garante o máximo conforto e resistência. O Snorkel possui espaço de armazenamento de água que garante fácil escoamento, e bocal de silicone confortável de alta qualidade, macio e facilmente adaptável à boca. Além disso, possui fivela fácil de ajustar, para ajuste de ângulo quando fixada na máscara. Diferenciais Kit de Mergulho Infantil Máscara e Snorkel Vollo: ⦁ Proteção contra raios UVA e UVB ⦁ Lentes com tratamento antiembaçante ⦁ Máscara em Vidro Temperado Transparente ⦁ Máscara com Vedação em Silicone ⦁ Estrutura Ergonômica ⦁ Suporte de snorkel integrado ⦁ Mais liberdade para o desempenho aquático ⦁ Material flexível que não machuca ⦁ Bocal do Snorkel em silicone Especificações: ⦁ Infantil ⦁ Composição da tira e ventosas: 100% silicone ⦁ Composição das lentes: Vidro Temperado ⦁ Cor: Azul e Laranja - KIT VENDIDO POR UNIDADE -', 259.9, 210.42, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/sg-11134201-7rd3y-luggw4h59g932f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1001649409%2F18997669064', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
