INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20798008115', 'Brinco Rommanel Solitário Com Cristal Preto 4mm - 525029 Original', '**Brinco Rommanel - Solitário com Cristal Negro** Este sofisticado brinco solitário é composto por um cristal negro de 4 mm, perfeito para adicionar um toque elegante e moderno ao seu visual. - Medida: 4 mm de diâmetro - Material: Semi joia Rommanel, antialérgica e resistente ao escurecimento - Garantia de 12 meses contra defeitos de fabricação Informações adicionais: Acompanha nota fiscal, certificado de garantia Rommanel e uma embalagem presenteável, conforme disponibilidade. **Cuidados:** Para preservar a beleza e durabilidade da sua joia, evite contato com produtos químicos e atividades que possam gerar atrito. Seu pedido será processado com agilidade, garantindo que você receba o produto o mais breve possível.', 109.0, 96.96, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/sg-11134201-7rbmi-m5d19qxjjq7fdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F536715397%2F20798008115', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
