INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13789111326', 'Kit 6 Cuecas Zorba Infantil Boxer Algodão Sem Costura 678', 'DESCRIÇÃO: Kit com 06 Cuecas Zorba Boxer Seamless Algodão Boys. Malha confortavel, não possui costura nas laterais. Possui a tecnologia Go Tagless, sem etiquetas costuradas, não arranha e não irrita a pele. Veste do P ao G. Tecnologia Maxfresh: Regula a Sensação Térmica. Protege contra odores e bactérias. Tecnologia Go Tagless: Sem etiquetas costuradas. Não irrita e não arranha a pele. Tecnologia Seamless: Sem costura nas laterais. Ajuste perfeito ao corpo. COMPOSIÇÃO: 76% Algodão, 21% Poliamida e 3% Elastano. Mescla: 42% Algodão, 40% Poliester, 17% Poliamida e 1% Elastano. PAÍS DE ORIGEM: Brasil. INSTRUÇÕES DE LAVAGEM: Temperatura máxima de lavagem 30ºC; processo suave; não alvejar; não secar em tambor; secagem em varal por gotejamento a sombra; temperatura máxima da base do ferro a 110ºC sem vapor; não limpar a seco. INDICAÇÃO: Dia a dia. CONTÉM: 01 kit com 06 unidades. TABELA DE MEDIDAS: P - 3-5 anos até 55 cm de cintura M - 6-8 anos até 60 cm de cintura G - 9-11 anos até 65 cm de cintura Caso sua medida esteja no intervalo das medidas entre um tamanho e outro, considerar o tamanho maior.', 123.9, 90.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Underwear & Innerwear', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgf3tdt1ujnoec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F733918049%2F13789111326', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
