INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292218889', 'Kit 5 Aplicador de Espuma Automotivo Cera Plástico Pneus', 'O APLICADOR DE ESPUMA ZACS foi desenvolvido com células fechadas de alta qualidade, criado especialmente para aplicação de ceras, hidratantes para couro, limpadores, renovadores de plásticos, polidores, produtos para pneus e etc. Seu formato anatômico permite fácil manuseio. Devido sua tecnologia inovadora a base de poliéster pré-soft, esse produto traz algumas características importantes, como: resistência ao rasgo, resistência a solventes e maciez extrema. - Cor: Roxo - Alta maciez - Espuma com céluas fechadas - Tamanho: 11 x1,5cm - Poliéster de alta qualidade', 20.4, 19.49, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkv0esdccheg54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557320114%2F22292218889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
