INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53305864103', 'Capa Anti Impacto Gocase Infinite Para iPhone 17', 'Capa Anti Impacto Gocase Infinite Para iPhone 17 • A Gocase Infinite possui um design elegante, tecnologia e alta qualidade para proteger o seu smartphone. • Desenvolvida em TPU emborrachado, excelente para encaixar no aparelho com facilidade. • Com material qualificado, protege o seu smartphone contra impactos, arranhões e sujeira. • Material flexível e de alta qualidade. As Cases da Gocase estão entre as melhores do Mundo. ATENÇÃO! Não utilize produtos químicos abrasivos para higienizar a Capa, inclusive álcool. O álcool é abrasivo e pode remover o verniz e a tinta da Capa.', 109.9, 69.9, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-8260t-mkcpcyrnmmtje8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F53305864103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
