INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19069602537', 'Branqueador Banheiro Veja Antibac Frasco 500Ml Borrifador', 'Limpador Antibac Veja Banheiro Oxi Action 500ml limpa e desinfecta sem a agressão do cloro. Benefícios: Limpa e desinfecta a superfície sem a agressão do cloro. Superfícies: aços inoxidáveis, azulejos, ladrilhos vitrificados, pias, armários, box de banheiro, vasos sanitários e banheiras. Sujeiras: gordura corporal, pasta de dente, marcas de sapato, poeira e resíduos de sabão. Informações de uso: Gire o bico do pulverizador até a posição “on”. Para limpeza e desinfecção: aplique o produto até que a superfície esteja totalmente molhada e deixe agir por 10 minutos antes de enxaguar. Enxugue a área com um pano e remova completamente o produto da superfície. Após o uso, gire o bico do gatilho para a posição “off”. Marca: Veja Quantidade: 500ML Contém: 1 pulverizador de 500ML', 52.52, 52.52, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7r9bg-llf2mi0wtuvxc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F912497596%2F19069602537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
