INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193722316', 'Mochila Hidratação Ciclismo Térmica Bolsa Agua C/refil 2lts Preto - WCT Fitness', 'Mantenha-se Hidratado com Conforto e Estilo Apresentamos a mochila de hidratação, projetada para aventuras em ciclismo, esportes, corrida e caminhadas. Equipada com tecido impermeável, tanque de água integrado e saco de armazenamento prático, esta mochila combina funcionalidade, leveza e conforto para experiências inesquecíveis. Principais Características: Capacidade Ideal para Hidratação e Armazenamento: Com 45 cm de altura, 25 cm de largura e 15 cm de profundidade, oferece espaço suficiente para o tanque de água e itens essenciais. Volume do tanque‎2 Litros. Tecido Impermeável: Nylon com fibra de poliéster e EVA protege contra chuva e umidade, garantindo durabilidade. Tanque de Água Integrado: Sistema de hidratação com fácil acesso à água durante atividades, mantendo-o sempre hidratado. Saco de Armazenamento Prático: Ideal para organizar pequenos itens como chaves, celular e lanches, proporcionando conveniência. Benefícios Adicionais: Leveza e Conforto: Peso de apenas 480g e design ergonômico que proporciona conforto durante longos períodos de uso. Versatilidade em Atividades ao Ar Livre: Perfeita para ciclismo, esportes, corridas e caminhadas, oferecendo praticidade em todas as suas aventuras. Durabilidade e Resistência: Construída com materiais de alta qualidade para resistir ao desgaste do uso frequente, garantindo longa vida útil. Prepare-se para explorar novos horizontes com a nossa mochila de hidratação. Projetada para oferecer conforto, praticidade e desempenho superior, é a companheira perfeita para manter-se hidratado e organizado em todas as suas atividades ao ar livre. Adquira já sua Mochila de Hidratação e aproveite cada aventura com total conforto e segurança!', 323.9, 323.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Dry Bags', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6gt69ovbcqv23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F504750919%2F23193722316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999307124', 'Conjunto C/2 Banqueta Allegra Alta Master Preta Cozinha Americana Balcão Polipropileno', 'Conjunto C/2 Banqueta Allegra Alta Master Preta Cozinha Americana Balcão Polipropileno Modelo: Banqueta Allegra Master Com design moderno a banqueta allegra é ideal para decorar qualquer ambiente. A banqueta possui encosto vazado e descanso para os pés, prática e confortável. Ideal para deixar a sua bancada de alimentação ou bar mais moderna. Garantia de 3 meses por defeito de fabricação. Altura Total: 109 cm Altura do Chão Até o Assento: 76 cm Profundidade Interna do Assento: 40 cm Largura Interna do Assento: 36 cm Peso Máx. Recomendado: 120 kgs Peso unitário: 4,6 kgs Não Giratória Não Dobrável Não Empilhavel Indicações de Uso: - Não utilizar produtos químicos e abrasivos para limpeza - Limpar com pano umedecido e sabão neutro para melhor conservação - Deve ser evitada exposição dos produtos ao sol pois podem apresentar pequenas mudanças em sua coloração. Observações importantes: - Produto NÃO necessita de montagem - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento.', 678.0, 678.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-ly5leqxuxjfu05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F19999307124', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
