INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51705096960', 'Armário Aéreo 3 Portas 90cm MDP – Kit com 2 Unidades', 'Pronta Entrega - Envio Imediato - Mais Vendido - Enviamos para Todo o Brasil Descubra o Conjunto de armário aéreo 3 portas perfeito para um ambiente moderno e organizado. Versátil e multifuncional, ele se adapta a qualquer espaço da sua casa, seja na lavanderia, cozinha ou escritório. Fabricado com ótimo material, oferece durabilidade e estabilidade, proporcionando estilo e praticidade na organização do seu dia a dia. Renove seu espaço com funcionalidade e elegância! Descrição: -Altura: 62 cm -Largura: 90 cm -Profundidade: 28,2 cm Características: -Material: MDP 12 mm -3 Portas com dobradiças metálicas e puxadores PVC cromados -Não possui prateleiras internas -Suporta 25kg distribuídos -Pintura UV Conjunto com 2 Unidades', 564.98, 297.7, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8262p-mjsfne9smio12a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242718651%2F51705096960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
