INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693130845', 'Sensor de Rotação Velocidade do Câmbio Automatico Superior Pajero Full 3.2 Diesel 2005 A 2015', '*SENSOR SUPERIOR DA CAIXA AUTOMATICA, CONFERIR O MODELO DA SAIDA, POIS EXISTE TAMBEM O SENSOR INFERIOR, QUE A SAIDA É DIFERENTE DESSE MODELO* Aplicação: Pajero Full 3.2 Diesel 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015 - Câmbio Automático Nº Original: MR518300 Garantia: 90 dias Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Peças Rápidas - O seu shopping de auto peças online!', 209.99, 209.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lxjpvw9obtle95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F23693130845', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207435421', 'Alicate Rebitador Manual Luatek LWJ-128A', 'ALICATE REBITADOR MANUAL LUATEK LWJ-128A Características Marca: LUATEK Código do fabricante: LWJ-128A EAN: 7908881424416 Especificações: Material: Aço carbonoTamanho: 24 x 8,3 cm (9,5 polegadas)Indicado para rebites pop Características:• Formato anatômico.• Clipe de travamento do cabo.• Chave para troca dos bicos.• Prático e resistente. Instruções de uso: Com uma furadeira, fure o seu trabalho nos locais que deseja rebitar.(Use uma broca de tamanho compatível com o rebite que irá utilizar). Encaixe o rebite no furo. Com a alavanca frouxa, encaixe a ponta no rebite.Atenção: A ponta do rebitador e o rebite devem ser do mesmo tamanho.Para trocar a ponta, use a chave, desrosqueie a ponta do rebitador e rosqueie a ponta do tamanho desejado. Aperte o cabo do rebitador até o pino do rebite estourar. Afrouxe o cabo; a haste do rebite sairá do rebitador. Cuidados: • Para reduzir o risco de lesões, sempre use adequadamente equipamentos de proteção individual (óculos de proteção, máscara, botas, luvas, etc.) necessários ao trabalho. • Use a ferramenta correta para cada tipo de trabalho. Não force a ferramenta. A ferramenta correta fará o trabalho melhor e mais seguro se utilizada para aquilo que foi projetada. • Armazene em local seco e fresco.• Guarde em local seguro.• Guarde estas instruções para futuras consultas.• Manter fora do alcance das crianças. Embalagem contém:• 01 Rebitador', 68.0, 23.98, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820mb-mmq4wlztmj9i6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1655406395%2F58207435421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
