INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5979880557', 'Piscina Retangular Pequena Mor 1000 Litros - Portátil', 'Piscina Retangular Pequena 1000 Litros Portátil - Mor As piscinas infantis da Linha Mor foram cuidadosamente projetadas para proporcionar momentos de diversão com segurança para as crianças. A Piscina de 1.000 litros, possui estrutura metálica e peças plásticas em polipropileno, é fácil de montar graças ao seu sistema de encaixe simplificado. Sua lona em PVC, decorada com estampas aquáticas encantadoras, convida os pequenos a desfrutarem de horas de brincadeiras refrescantes. A piscina possui capacidade para até 1000 litros de água, formato retangular e é prática de montar, desmontar e transportar para qualquer lugar. Sua estrutura fabricada em aço com acabamento em pintura epóxi proporciona resistência e estabilidade, enquanto a lona robusta garante durabilidade e segurança durante o uso. É essencial lembrar de proteger a pele dos pequenos com filtro solar durante o uso da piscina. Guarda-sóis são ótimos aliados para garantir sombra e tranquilidade durante esses momentos de lazer. Recomenda-se sempre a supervisão de um adulto quando as crianças estiverem próximas à água. Principais Características: - A Partir de 03 Anos (Com supervisão de um adulto) - Capacidade para até 1000 Litros de água - Formato: Retangular - Prática de ser montada, desmontada e transportada para qualquer lugar. - Estrutura fabricada em aço com acabamento em pintura epóxi - Lona resistente e estrutura firme Especificações Tecnícas: - Material: Lona Pvc e extrutura em aço com pintura epóx, peças em plásticas em polipropileno com sistema de encaixe que facilitam sua montagem - Composição da Embalagem, 01 Piscina 1000 litros + Manual de Instruções - Dimensões: (AxLxP): 42,0 x 1,26 x 1,89 cm - Garantia: 3 Meses (Contra Defeito de Fabricação Pelo Fabricante) - Certificação: ABNT NBR ISO 9001:2008 - Código do Fabricante: 1002 - EAN: 7896020610021 - Marca: Mor Imagens meramente ilustrativas, cores e estampas podem variar de acordo com o lote do fabricante.', 269.0, 197.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz90jjpz5phdaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F5979880557', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
