INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697873505', 'Interruptor Inteligente Touch WiFi Preto Avant Neo', '𝙄𝙣𝙩𝙚𝙧𝙧𝙪𝙥𝙩𝙤𝙧 𝙄𝙣𝙩𝙚𝙡𝙞𝙜𝙚𝙣𝙩𝙚 𝙒𝙞-𝙁𝙞 - 𝘼𝙫𝙖𝙣𝙩 𝙉𝙚𝙤 O Interruptor Inteligente Avant Neo permite controlar a iluminação com praticidade, via aplicativo ou comando de voz, trazendo mais conforto e automação para o ambiente. 𝙋𝙧𝙤𝙥𝙧𝙞𝙚𝙙𝙖𝙙𝙚𝙨: ✔ Controle remoto via aplicativo Avant Neo; ✔ Programação de horários; ✔ Compatível com Alexa e Google Assistente; ✔ Acionamento touch. 𝘾𝙖𝙧𝙖𝙘𝙩𝙚𝙧𝙞́𝙨𝙩𝙞𝙘𝙖𝙨 𝙙𝙚 𝙁𝙪𝙣𝙘𝙞𝙤𝙣𝙖𝙢𝙚𝙣𝙩𝙤: ✔ Controle de qualquer lugar; ✔ Automação de rotinas; ✔ Comando por voz. 𝙀𝙨𝙥𝙚𝙘𝙞𝙛𝙞𝙘𝙖𝙘̧𝙤̃𝙚𝙨 𝙏𝙚́𝙘𝙣𝙞𝙘𝙖𝙨 𝙚 𝘾𝙤𝙢𝙚𝙧𝙘𝙞𝙖𝙞𝙨: ✔ Modelo: INTERRUPTOR-NEO-PB; ✔ Código: 291005050; ✔ Potência: 300W; ✔ Cor: Preto; ✔ Material: Polipropileno (corpo) e vidro (visor touch); ✔ Dimensões: 119mm x 73,3mm x 120mm; ✔ Peso: 10g; ✔ Necessário neutro para instalação. 𝙂𝙖𝙧𝙖𝙣𝙩𝙞𝙖: Garantia de 12 meses contra defeitos de fabricação. 𝙎𝙤𝙗𝙧𝙚 𝙖 𝘼𝙫𝙖𝙣𝙩 𝙉𝙚𝙤: A Avant Neo é uma marca que busca oferecer soluções inovadoras e inteligentes em iluminação e automação residencial. Com produtos de alta qualidade e tecnologia de ponta, a Avant Neo traz praticidade, design e economia para o seu dia a dia.', 126.9, 78.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Switches', 'https://cf.shopee.com.br/file/br-11134207-820me-mo9s2ov2kxdx8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275385296%2F21697873505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
