INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593509014', 'Livro - Batman: A Piada Mortal (DC De Bolso) - Novo/Lacrado', 'Batman: A Piada Mortal (DC De Bolso)Encontre neste único volume com 136 páginas duas das histórias que melhor souberam descrever a figura do Coringa e sua relação com o Batman. Em Batman: A Piada Mortal, Alan Moore e Brian Bolland nos levam à mente do Príncipe Palhaço do Crime, mostrando-nos o que poderia ser um vislumbre de seu passado. Em Batman: O Homem Que Ri, Ed Brubaker e Doug Mahnke revisitam as primeiras aparições do Coringa, voltando no tempo aos dias de seu primeiro confronto com o Batman, oferecendo novas perspectivas a histórias clássicas. Uma viagem alucinante ao mundo daquele que é o vilão dos quadrinhos por excelência!Segmentos: Comics Marcas: DC Autor(es): Alan Moore, Brian Bolland ISBN: 9786525930091 Check-List: Novembro/2024 Classificação Etária: 16 anos Editora: Editora Panini Número de páginas: 136 Tipo de capa: Capa Cartão Data de Lançamento: 21/11/2024 Idioma: Português Condição: Novo/Lacrado', 43.9, 43.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7req1-m22uw04mrjtu1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F23593509014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
