INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793945541', 'Par Pneus Para Bicicleta Paco Fire Flame Aro 26 X 2.125 Balão Slick Largo Mtb Bike', 'Apresentamos o PNEU ARO 26 X 2.125 PACO FIRE na cor PRETO, um produto de alta qualidade da renomada marca GTA/PACO. Este modelo é ideal para bicicletas MTB, proporcionando uma excelente performance em qualquer tipo de terreno. Os pneus possuem um diâmetro de 559" e uma pressão máxima de 40 psi, garantindo uma condução suave e segura. Além disso, cada pneu pesa 900g, o que contribui para a estabilidade da bicicleta. Esse pneu na cor PRETO, que além de proporcionar um visual elegante, também oferecem uma grande resistência e durabilidade. O design slick dos pneus permite uma melhor aderência ao solo, tornando a sua experiência de ciclismo ainda mais agradável. Os pneus são feitos com arame, o que aumenta a sua resistência e durabilidade. A medida dos pneus é de 26 x 2.125 (ETRTO 54-559) e a pressão recomendada é de 40 PSI. Dados Técnicos: Marca: GTA/PACO TIRES Pneu 26x2.125 (54-559mm) Fire PRETO Certificado pelo INMETRO Modelo: Fire Medida: 26x2.125 (54-559mm) Para Bike aro 26" Estrutura de arame com 24 tpi Cor: PRETO Pressão recomendada: máximo de 40 libras (psi) Composição: elastômero, tecido sintético, arame de aço', 164.9, 164.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rfg9-m9dspmhg3gpl3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23793945541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
