INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998027592', 'Nac (N Acetil L Cisteína) Pote 60 cápsulas - FTW', 'NAC FTW é um suplemento alimentar em cápsulas composto por N-Acetil L-Cisteína, uma forma estável do aminoácido cisteína. Esse composto é frequentemente utilizado como precursor da glutationa, um tripéptido naturalmente produzido pelo organismo, e amplamente associado a estratégias nutricionais voltadas ao equilíbrio oxidativo e suporte metabólico. Indicado para adultos com dietas específicas ou rotinas que demandam atenção à ingestão de aminoácidos, o NAC pode ser utilizado conforme a recomendação de nutricionista ou profissional de saúde. Ingredientes N-Acetil L-Cisteína, estabilizantes (celulose microcristalina e amido), antiumectante dióxido de silício. Ingredientes da cápsula: Celulose, opacificante dióxido de titânio e água potável filtrada. NÃO CONTÉM GLÚTEN. Apresentação Pote com 60 cápsulas Porção: 1 cápsula ao dia Rendimento: Cerca de 60 porções. Como Consumir Ingerir 1 cápsula ao dia, preferencialmente com líquido. Uso conforme recomendação de nutricionista ou profissional habilitado. Informações Adicionais Produto indicado para adultos maiores de 19 anos; Este produto não deve ser consumido por gestantes, lactantes ou crianças; Mantenha fora do alcance de crianças; Não exceder a recomendação diária de consumo indicada na embalagem; Conservar em local seco e fresco, ao abrigo da luz e umidade; Após aberto consumir em até 60 dias; Este produto não é um medicamento. Certificação Suplemento alimentar dispensado de registro conforme Resolução RDC nº 240/2018. Alegações baseadas no Anexo V da IN 28 Anvisa.', 63.9, 49.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjit2z1vpjwhef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397772996%2F23998027592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
