INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208363797', 'Ar Condicionado Split Agratto Hi Wall Zen Top Inverter 9.000 Btu/h Frio Monofásico Branco ZICST9F-02 220V', 'Ar Condicionado Split Agratto Hi Wall Zen Top Inverter 9.000 Btu/h Frio Monofásico Branco ZICST9F-02 Circuito inteligente para climatização, mantém a temperatura mais constante e evita picos de energia. Moderno, bonito e econômico, consegue ir ainda mais além na economia. Seu ciclo de climatização inverter pode gerar até 60% mais economia. Tecnologia Inverter com inversor de frequência que ajusta a velocidade do compressor ao diagnosticar se o ambiente precisa de menos refrigeração. O aparelho fica mais silencioso devido à pouca variação na rotação do compressor e gera um ambiente confortável, ao alcançar a temperatura desejada rapidamente. Econômico: Classificação energética A Serpentina: Tubos 100% em cobre Painel de Led: Iluminação suave Gás Ecológico: Gás R32 Especificações Técnicas: Marca: Agratto Cor: Branco Modelo: ZICST9F-02 Capacidade (BTU/h): 9.000 Voltagem: 220V Classificação Energética: A Frequência: 60Hz Consumo (kWh/ano): 311 Ciclo: Frio Ideal até (m²): 15 Tecnologia Inverter: Sim Controle Remoto: Sim Gás Refrigerante: R32 Fase: Monofásico Serpentina: Cobre Nível de Ruído Evaporadora dB(A): 32-39 dB (A) Nível de Ruído Condensadora dB(A): 48-53 dB (A) Potência (W): 735 Fluxo de ar (m³/h): 600 Inmetro: 008 946/2022 Dimensões e Peso do Produto: Evaporadora Altura: 20,1 cm Largura: 77 cm Profundidade: 25 cm Peso: 6,200 kg Condensadora Altura: 55 cm Largura: 47,8 cm Profundidade: 39 cm Peso: 15,370 kg Garantia: 90 dias (Sendo 3 meses de garantia legal). Instalado por um técnico credenciado: 01 ano (Sendo 3 meses de garantia legal e 9 meses pelo fornecedor).', 9999.0, 1646.88, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https