INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799665571', 'Mala de Bordo ABS 4 Rodas Adventure Fortt Vermelha - MAB01-VR', 'Mala de Bordo ABS 4 Rodas Adventure Fortt Vermelha - MAB01-VR A Mala de Bordo Adventure Fortt, foi desenvolvida com o que há de mais moderno. Ela é produzida em ABS, que é um material resistente e de fácil limpeza. Possui 4 rodas com giro de 360°, é equipada com cadeado fixo, com senha configurável para a proteção de seus itens e internamente, possui cintas elásticas para lhe ajudar na organização de seus pertences. Características Parte Externa: Pode ser utilizada como bagagem de mão em aviões; Cor: Vermelha; Estrutura rígida em ABS; Cadeado fixo com senha configurável; Alça de alumínio retrátil com regulagem de altura; Alça superior e lateral; 4 Rodas com giro 360º Parte Interna: Forro em nylon; Cinta elástica com trava; Bolso interno na tampa; Amplo espaço interno; 2 Compartimentos internos. Dimensões externas: Altura com a alça totalmente esticada: 95cm Altura com a alça abaixada: 55cm Largura: 35cm Profundidade: 22cm Dimensões internas: Altura: 48cm Largura: 36cm Profundidade: 20cm Peso suportado: 10 kg Peso: 3Kg Garantia legal de 90 dias para defeito de fabricação - Material resistente com um rigoroso controle de qualidade, unindo versatilidade, praticidade e durabilidade. - O tom da cor do produto pode variar de acordo com lote e/ou características do seu monitor ou tela. - Fotos Meramente ilustrativas.', 239.0, 114.74, NULL, 'Travel & Luggage > Luggage', 'https://cf.shopee.com.br/file/sg-11134201-7rd3u-m7b7qhjjzkx54f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1388709282%2F20799665571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
