INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198890326', 'Ventilador de Teto Ventisol Wind 3 Pás Bivolt Branco', 'Ventilador de Teto Ventisol Wind 3 Pás Bivolt Branco O Ventilador de Teto Ventisol Wind 3 Pás Bivolt Branco é a escolha ideal para quem busca eficiência, economia e um design discreto para ambientes internos. Com três pás de plástico de alta durabilidade, ele garante excelente circulação de ar, proporcionando conforto térmico mesmo nos dias mais quentes. Equipado com motor inverter, o modelo oferece alto desempenho com baixo consumo de energia, podendo ser até 75% mais econômico. Além disso, seu funcionamento é silencioso, ideal para quartos, salas e escritórios. Conta com sistema Easy-Plug, que facilita a instalação elétrica, além de ser bivolt automático (127V-220V), trazendo mais praticidade e versatilidade. Possui controle remoto com diversas funções, incluindo ajuste de velocidade, timer e modos de ventilação. Seu acabamento em branco permite fácil integração com qualquer estilo de decoração, tornando o ambiente mais confortável e moderno. ESPECIFICAÇÕES Marca: Ventisol Modelo: Wind Tipo: Ventilador de teto Pás: 3 pás em plástico Voltagem: Bivolt automático (127V-220V) Motor: Inverter (baixo consumo e alto rendimento) Consumo: Até 75% mais econômico Funcionamento: Silencioso com alta vazão de ar Eixo: 14 mm (maior estabilidade) Controle remoto: Sim 6 níveis de velocidade Função ventilação e exaustão Controle de iluminação Timer de até 4 horas Função Wave (variação de velocidade) Incluso 2 pilhas AAA Instalação: Sistema Easy-Plug (fácil conexão elétrica) Iluminação: Soquete E27 Compatível com lâmpadas de até 20W (não inclusa) Outros: Compacto e leve Fácil montagem Limpeza prática DIMENSÕES E PESO Largura: 15 cm Altura: 20 cm Comprimento: 42,5 cm Peso: 2,8 kg ITENS INCLUSOS Ventilador de teto Controle remoto 2 pilhas AAA Imagens de caráter ilustrativo. Informações divulgadas de acordo com o manual do fabricante. Produto novo, lacrado, com nota fiscal e garantia de 12 meses do fabricante. Em caso de dúvidas sobre informações técnicas, utilização ou instalação, consulte o manual do fabricante. EAN: 7898461974632 NAC: NAC014634', 399.9, 215.91, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-824h3-meiyr8f55nnr91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497436635%2F23198890326', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49800435386', 'Pijama Plus Size Americano Miami Serve Amamentação', 'Descubra o conforto e a praticidade do Pijamas Plus Size Americano Miami, especialmente desenhado para mulheres que estão em fase de amamentação. Composto por três pijamas, este conjunto é ideal para proporcionar uma experiência relaxante durante as noites de primavera e verão. Cada pijama é confeccionado em suede, com uma composição de 96% poliéster e 4% elastano, garantindo suavidade e elasticidade. As mangas curtas e o fechamento em botões oferecem facilidade e estilo, permitindo que você se sinta à vontade e elegante ao mesmo tempo. Além de ser apto para gestantes, o design pensado para a amamentação facilita o acesso, tornando-o uma escolha prática para novas mães. Aproveite a combinação perfeita de conforto e funcionalidade, ideal para momentos de descanso e cuidado.', 69.0, 58.65, NULL, 'Women Clothes > Sleepwear & Pajamas > Pajamas', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgfgeyhv9u6d1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F336042646%2F49800435386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
