INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9750854481', 'Cranberry Desidratado - P&P', 'A Prova Entrega. Envio em 24Horas! SUPER PROMOÇÃO! 🍒💖 Delicie-se com os benefícios naturais das Cranberries! Reconhecidas por suas propriedades antioxidantes Quem está em busca de cuidar da saúde e manter a dieta em dia já deve ter ouvido falar dessa fruta, que está cada vez mais comum nos supermercados. A cranberry (a “oxicoco”, no Brasil) é uma fruta vermelha, oriunda principalmente das regiões mais frias do mundo – como o Canadá, Estados Unidos e Europa , ela é muito rica em nutrientes e antioxidantes, que podem servir para tratar diversas doenças. BENEFÍCIOS DO PRODUTO O cranberry desidratado é extremamente rico em nutrientes, apresentando alta concentração de antioxidantes (flavonóis, antocianinas, catequinas e proantocianidinas), manganês, vitamina A, E, C e fibras, sendo uma ótima opção para complementar a dieta. Escolha entre as opções de Peso: 500g ou 1kg', 70.0, 34.97, NULL, 'Food & Beverages > Snacks > Dried Snacks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltx0u1kegmsl04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F9750854481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52354199918', 'Kit 6 Cueca Boxer Reebok Microfibra Kit Cueca Box Poliamida Cueca Masculina Sem Costura Original', 'Kit 6 Cueca Boxer Classic Poliamida Reebok A cueca boxer masculina em poliamida da Reebok é a escolha ideal para quem busca conforto, respirabilidade e alta performance no dia a dia e nos treinos. Desenvolvida com modelagem anatômica sem costura, ajusta-se perfeitamente ao corpo, reduzindo atritos e proporcionando liberdade total de movimento ao longo do uso. O tecido leve e macio oferece excelente absorção do suor e secagem rápida, mantendo a sensação de frescor mesmo em longos períodos de uso. O cós elástico reforçado com logo Reebok garante ajuste firme e seguro, sem dobrar, apertar ou enrolar, unindo funcionalidade e estilo esportivo. Versátil e durável, essa cueca boxer é indicada tanto para atividades físicas quanto para a rotina diária, entregando conforto contínuo, suporte estável e acabamento premium. Vantagens do produto: - Tecnologia sem costura, que reduz atritos e aumenta o conforto - Modelagem anatômica que se ajusta perfeitamente ao corpo - Tecido leve, macio e resistente, com alta durabilidade - Cós confortável com logo Reebok, firme sem apertar - Excelente absorção do suor e secagem rápida - Ideal para treinos, trabalho e uso prolongado - Design moderno, discreto e acabamento de qualidade Conteúdo da embalagem: Você receberá: Kit com 6 Cuecas Boxer Reebok Classic em Poliamida Composição: 94,16% Poliamida | 5% Elastano | 0,84% Poliéster Descrição dos kits Kit sortido: 1 branca | 1 cinza | 2 marinho | 2 preto Kit monocromático: 6 unidades na cor preta (Envio conforme variação escolhida no anúncio) Tabela de medidas: P: Manequim 38?40 | Quadril 34?36 cm M: Manequim 42?44 | Quadril 36?38 cm G: Manequim 46?48 | Quadril 38?40 cm GG: Manequim 50?52 | Quadril 41?43 cm Dica: se estiver entre dois tamanhos, opte pelo maior para melhor conforto. Cuidados na lavagem: - Lavar à mão ou na máquina até 30°C - Não usar alvejante - Secar à sombra, em varal - Não passar a ferro - Não lavar a seco Seguindo essas orientações, você preserva o caimento, a elasticidade e a durabilidade do produto.', 159.99, 69.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-8260p-mj5m5hih0niff1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F52354199918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
