INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255527976', 'CAMARA AR GP TECH COM SELANTE A-18 3.00-18 / 90-90-18 / 2.75-18 ( TITAN / FAN / YBR / FACTOR )', 'CAMARA AR GP TECH COM SELANTE 1. Retire o objeto perfurante em um local seguro. 2. Ande com a motocicleta por aproximadamente 1,5 km para permitir que o selante atue na vedação. 3. Se a vedação não ocorrer e o esvaziamento for gradual, o furo pode ser maior do que o recomendado ou estar localizado fora da banda de rodagem. Segurança Após a vedação, continue sua viagem com total segurança. Precauções Não reutilize o líquido selante. Em caso de contato com os olhos ou pele, lave com água em abundância. Em caso de ingestão, procure um médico imediatamente. Composição Borracha natural, pó de pneu, H2O, agentes adesivos naturais, espessante, cobre, níquel, aditivos naturais e anticorrosivo. Atenção A vedação ocorre instantaneamente de dentro para fora. Com a rotação das rodas, o selante cria uma fina camada protetora no interior da câmara de ar, sem afetar o balanceamento ou a dirigibilidade da motocicleta. Funciona com pressão mínima de 20 psi nos pneus. Nunca realize reparos pelo método a frio. O reparo deve ser feito exclusivamente por vulcanização. Em casos de perda excessiva do líquido selante, futuras perfurações podem não ser vedadas corretamente. O diâmetro máximo do objeto perfurante suportado pelo selante é de 2,5 mm. A GP Tech e a Block não se responsabilizam por danos decorrentes de erros na montagem e/ou uso indevido da câmara de ar. Importante: Câmaras de ar estão sujeitas a esvaziamento repentino devido a mau uso, erro de instalação ou perfurações fora dos limites garantidos. * Imagens meramente ilustrativas * Garantia de 90 dias contra defeito de fabricação. Maximize a Performance da Sua Moto: Conheça a Câmara de Ar GP Tech com Selante da Paulinho Motos CAMARA AR GP TECH COM SELANTE A-18 3.00-18 / 90-90-18 / 2.75-18 ( TITAN / FAN / YBR / FACTOR ) Adquira a Câmara de Ar para Pneu Moto GP Tech com Selante na Paulinho Motos. Garantia de qualidade e segurança para sua pilotagem. Confira já!', 49.99, 49.99, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Inner Tubes for Tires', 'https://cf.shopee.com.br/file/sg-11134201-8262f-mky5rjyatj4302', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1025296952%2F58255527976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892566682', 'Jogo de Taças e Copos de Cristal Imperial Fio de Ouro 8 peças - Lyor', 'Conjunto De 4 Taças e Copos Imperial Transparente Fio de Ouro - Lyor Na hora de servir as bebidas num almoço ou jantar, é ideal que elas estejam com uma boa temperatura, mas para isso é importante usar a taça e os copos certa para cada tipo de bebida. Além disso, este conjunto deixa a sua mesa ainda mais bonita na hora de receber os convidados. O kit de taças e copos é desenvolvido na cor transparente com borda fio de ouro do modelo Imperial, unindo beleza e utilidade para sua mesa posta. Desenvolvida com cristal de excelente qualidade e espessura, o que garante toda durabilidade. As taças da Lyor possuem 330mL de capacidade e os copos possuem 370mL cada, são ideais para água, suco e refrigerante. O conjunto possui design moderno e sofisticado para você servir deliciosas bebidas com requinte e bom gosto. Composição e Dimensão: 4 Taças de 330mL - 16,5cm (A) x Ø 8,7cm 4 Copos de 370mL - 12cm (A) x Ø 8cm Características: Marca: Lyor Referência: 5742 e 5740 Modelo: Imperial Material: Cristal Cor: Transparente com Borda Dourada Imagens Ilustrativas.', 196.0, 151.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7rcfa-lslmh2idcjhx43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F504745949%2F23892566682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
