INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293252498', 'Limpador de Parabrisa Jeep Cherokee Sport ano 02 a 13 Universal', 'Descubra a excelência em limpeza de para-brisa com nossa linha de produtos premium. Projetados para oferecer durabilidade superior e desempenho sem ruído, nossos limpadores em silicone garantem uma visibilidade impecável, independentemente das condições climáticas. Encontre a solução ideal para manter sua visão nítida e sua jornada segura em todas as viagens. Compatível com: Limpador de Parabrisa Jeep Cherokee Sport ano 02 a 13 Universal. Acompanha: 1 - Palheta Limpador de Para-brisa dianteiro Motorista 19" 1 - Palheta Limpador de Para-brisa dianteiro Passageiro 19" 1 - LIMPA PARA-BRISAS FORCE ONE 100ML Universal Investindo em qualidade e confiança, nossos produtos também incluem a garantia do fabricante de 90 dias. Adquira já e desfrute de uma visibilidade máxima com nossos limpadores de para-brisa premium', 29.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzan7rk0axede7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F22293252498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
