INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46110210786', 'Tênis Fila Racer Fastpace Verde Azul e Laranja - Feminino', 'Mais leveza, conforto e performance para evoluir na corrida! Tênis Fila Racer Fastpace Verde Azul e Laranja - Feminino Ficha Técnica: Marca: Fila Gênero: Feminino Cor: Verde Azul e Laranja com detalhes em prata Cabedal: Tecido com aplicação em TPU para maior resistência e ajuste Indicado: Corridas diárias, treinos de rodagem, regenerativos e competições Nível de Corrida: Intermediário – treinos e corridas até 10 km Palmilha: Macia Sola: Borracha com tecnologia EVER-GRIP Fechamento: Cadarço Amortecimento: Macio Estabilidade: Neutro Tecnologias: ULTRA FOAM para amortecimento e retorno de energia. EVER-GRIP para tração e durabilidade Entressola: ULTRA FOAM com alta absorção de impacto Detalhes: Design leve, respirável e com ajuste preciso aos pés Evolua na corrida com o Tênis Fila Racer Fastpace, desenvolvido para quem busca desempenho com conforto em cada passada. Porque investir: A tecnologia ULTRA FOAM proporciona excelente absorção de impacto e retorno de energia, ajudando você a correr com mais eficiência. Já o solado EVER-GRIP garante tração e segurança em diferentes superfícies. Com cabedal leve e resistente, é o parceiro ideal para seus treinos e provas. Conteúdo da embalagem: 1 par de Tênis Fila Racer Fastpace Verde Azul e Laranja - Feminino', 499.99, 388.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-820lz-mo07t6qjyu4h1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F46110210786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
