INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492984965', 'Shampoo Tamanho Grande Palmolive Naturals Anticaspa Lavanda 650ml', 'A superprodução de óleo no couro cabeludo pode causar caspa. Esse shampoo Palmolive Naturals Anticaspa Lavanda, da linha Palmolive Naturals Cuidado Anticaspa, cuida do couro cabeludo de forma eficaz e com o uso contínuo, além de eliminar os vestígios visíveis da caspa, ajuda a prevenir a sua formação, deixando os cabelos macios e maleáveis. Benefícios para você: Esse shampoo Palmolive Naturals Anticaspa Lavanda é suave com o couro cabeludo e não resseca o cabelo. Um shampoo Palmolive com fórmula com óleo de lavanda de origem natural. Com o uso contínuo, além de eliminar os vestígios visíveis da caspa, ajuda a prevenir a sua formação. Tenha frescor e conforto para seus cabelos.', 42.66, 42.66, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd5d-lutdsq5hlrbnfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F23492984965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
