INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12449952031', 'Kit com 4 Limpador Diluível Pinho Sol Limpeza Pesada Eucalipto 1L Cada', 'Kit Contém: 4 Limpador Diluível Pinho Sol Limpeza Pesada Eucalipto 1L Cada O novo limpador Pinho Sol Limpeza Pesada Eucalipto 1 L é um multi-limpador feito para limpar profundamente todo o tipo de sujeira na sua casa. Isso porque a sua nova fórmula avançada facilita a limpeza, remove as manchas mais difíceis e desengordura, além de deixar um cheirinho delicioso por 8 horas. É a sua casa muito mais limpa, brilhante e protegida com um produto tão poderoso quanto você! Benefícios para você: Esse limpador Pinho Sol Limpeza Pesada Eucalipto limpa profundamente todo o tipo de sujeira na sua casa. Além disso, é um limpador que remove manchas. E você também conta pode contar: o Pinho Sol Limpeza Pesada Eucalipto desengordura. E perfuma os ambientes. Também protege a sua casa. – Para limpeza pesada utilize puro com um pano úmido na remoção de manchas e sujeiras mais difíceis. Disponível nos tamanhos: 1L e 500ml.', 109.99, 109.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7qvdf-lguv4ajmfyv38e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F12449952031', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22624216663', 'Bagageiro Suporte Bauleto CB 500 X Braz Acessórios', 'Bagageiro Suporte de Bauleto Baú Para Cb500 X Bráz Acessórios Aplicação: Cb500 X Até 2023. Descrição Técnica do Bagageiro: Cor: Preto Fosco; Peso aproximado: 2,5 Kg; Suporte carga máximo recomendado: 12 Kg. O Bagageiro Suporte Bauleto da Bráz Acessórios foi projetado milimetricamente para perfeita instalação na sua moto Cb500 X. A base é produzida em chapa de aço 1/8 e hastes de chapas reforçadas de 4,75mm, resistente ao uso diário e com alta capacidade de carga. Seu designer inovador, elaborado com corte a laser e pintura eletroestática, integra com a elegância de sua motocicleta. Sua instalação é simples e rápida, o bagageiro é fixado em pontos já existentes da sua CB 500 X. Um dos únicos modelos em chapa do mercado que não tem a necessidade de ser retirado o pega mão'' traseiro da moto.', 695.97, 695.97, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-23020-v82uadfy8invff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951482108%2F22624216663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997674536', 'Maiô Juvenil Acqua Basic Speedo - PRETO', '⚠️ Atenção ao tamanho! Nossa modelagem é menor que o padrão. Para garantir conforto, escolha um número acima do habitual. 😉 O Maiô Acquaplus Infantil é produzido em Helanca de alta qualidade. A modelagem das costas apresenta decote nadador, trazendo liberdade nos movimentos e tornando o treino e momentos de lazer mais prazerosos. Detalhes do produto: • Resistente ao cloro • Logo bordado • Costas nadador • Tecido Externo: 100% Poliamida • Tecido Interno: 100% Poliamida Dicas de Uso: • Não guarde a peça úmida • Não use amaciantes ou produtos com alvejantes à base de cloro • Não passar • Evite o contato com superfícies ásperas • Sua peça possui instruções específicas para lavagem e secagem, veja na etiqueta • Cloro e bronzeadores podem manchar o produto. Após o uso, enxague bem a peça em água fria • A contínua exposição à luz forte do sol e água clorada podem deteriorar alguns tipos de tecidos e cores', 179.9, 179.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Swimwear', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjh8221xuwar12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242944993%2F20997674536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
