INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897983439', 'Faixa Elástica Yoga Pilates Fitness Fisioterapia Exercícios - Rosa', 'O elástico é composto de um material plastico resistenten que possibilita um trabalho multifuncional para pilates, yoga e exercícios físicos em geral. Ajuda a desenvolver a musculatura em diversas regiões do corpo. Pode ser combinado com outros equipamentos de condicionamento físico. Contribui com aumento da força, resistência, agilidade, tonificar e fortalecer a musculatura, correção da postura e alongamento. Utilizado para treino nas regiões do corpo como: Ombros Peito Braços Abdómen Pernas Glúteos ATENÇÃO: Utilizar o produto de acordo com a orientação de um profissional especializado. Utilização: Treinamentos funcionais, yoga, pilates, reabilitação e condicionamento físico, fisioterapia entre outros.', 25.0, 25.0, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Training Equipments', 'https://cf.shopee.com.br/file/sg-11134201-82627-mlcl851ogsg182', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F18897983439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46910546758', 'Meloxiworld Anti-Inflamatório Meloxicam Cão e Gatos 0,5 mg Cx 10 Comp.', 'MeloxiWorld é um anti-inflamatório, analgésico e antipirético em cães e gatos. Utilizado no tratamento da dor, inflamação aguda e febre. MODO DE USAR Os comprimidos de MeloxiWorld devem ser administrados de acordo com o peso vivo, por via oral, diretamente na boca do animal, cuidadosamente, para evitar sua regurgitação durante o procedimento. Dosagem, frequência da administração e duração do tratamento: consultar bula.', 42.99, 22.99, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-820m5-mo8taiwf3g90e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464043565%2F46910546758', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
