INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999442351', 'ANTHELIOS ULTRA COVER PROTETOR SOLAR FPS60 COR 3.0 COM 30G', 'Anthelios Ultra Cover FPS 60 Cor 3.0 30g: Cobertura Extrema e Proteção Máxima O Anthelios Ultra Cover Protetor Solar FPS 60 com Cor 3.0 de 30g é um dermocosmético inovador, oferecendo altíssima proteção solar (FPS 60) de amplo espectro com cobertura de maquiagem extrema. É ideal para quem precisa disfarçar marcas severas, melasma ou cicatrizes. A tecnologia Ultra Cover cobre a pele por 12 horas, substituindo a base de alta cobertura. A textura é leve, não oleosa e seca rapidamente. A Cor 3.0 (Morena Média) se adapta perfeitamente a tons de pele morena. Não comedogênico e resistente à água. Bisnaga de 30g prática. Cobertura Extrema com FPS 60: FPS 60 Alta Cobertura: Proteção máxima UVA/UVB com efeito maquiagem.Ultra Cover: Cobre marcas severas por 12 horas. Cor 3.0: Ideal para tons de pele morena média. 30g: Tamanho prático para uso facial diário. Aplique uma camada uniforme no rosto antes da exposição solar. Reaplicar após o contato com a água ou a cada 2 horas. A proteção máxima com a cobertura que você precisa, de forma suave e duradoura.', 137.48, 137.48, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-82605-ml5jt1iobdand7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F20999442351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399265842', 'Fixodent Original Com 40G', '• Fixação Forte para uma Confiança que Dura o Dia Todo: O Creme Fixador Fixodent Original oferece uma fixação incrível que dura o dia inteiro. Coma, fale e sorria com a confiança de que sua prótese permanecerá firme e segura no lugar. • Selo Contra Partículas de Alimentos: Cria uma vedação superior que ajuda a bloquear a entrada de partículas de alimentos irritantes entre a prótese e a gengiva. • Bico de Alta Precisão: O bico 75% mais fino permite uma aplicação em linhas contínuas e precisas, garantindo uma fixação mais eficaz e sem excessos. • Sabor Neutro: Não interfere no sabor dos alimentos. A marca nº1 em recomendação pelos dentistas. • Palavras-chave: Fixodent, Fixador de Dentadura, Creme Adesivo, Prótese Dentária, Fixação Forte, Original.', 108.95, 108.95, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-8261x-ml5ju3ul2nepc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F18399265842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
