INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299140169', 'Nível Laser GLL 12-22 Bosch 12 Metros Esquadro 2 Linhas Vermelho IP55', '- PRODUTO ORIGINAL; - ENVIO IMEDIATO; - ENVIAMOS COM NOTA FISCAL; Destaques do produto O GLL 12-22 é o nivel a laser robusto para alinhamento rápido e preciso em canteiros de obras. Essa ferramenta compacta foi fabricada para suportar condições adversas. Possui carcaça reforçada com borracha e proteção IP55 contra poeira e respingos de água. Um suporte rotativo integrado com ímãs fortes garante uma fixação estável e também protege o vidro do laser durante o armazenamento ou transporte. Com a operação simples do interruptor de ligar/desligar, o laser permite um raio de ação de até 12 metros e um alcance de autonivelamento de +/- 3,5°. Esse nivel a laser tem uma tecnologia Dual Power Source (fonte de alimentação dupla) e funciona com 2 pilhas alcalinas AA ou com o acumulador de lítio BA 3.7V 1.0Ah A Professional, disponível separadamente. Isso significa nivelamento ininterrupto e maior sustentabilidade. Equipamento e aplicação Esse prático nivel a laser facilita o nivelamento preciso. É ideal para aplicações gerais de nivelamento, como o alinhamento preciso de interruptores elétricos e o alinhamento de vigas de metal e madeira. Características: - Código de referência: 0601065220; - Tipo de embalagem: Papelão; - Acabamento da ferramenta: Plástico, borracha e vidro; - Fonte de Energia: 2 pilhas AA (inclusas); - Não possui conexão Bluetooth; - Fonte de luz: Laser; - Público Alvo: Instaladores em geral, profissionais de construção, marceneiros, pintores, instaladores de Drywall e construção a seco. Dados Técnicos: - Ambiente de uso: Interno; - Proteção contra pó e projeções de água: IP 55; - Raio de ação: até 12 m; - Precisão: ±0,8 mm/m; - Projeção: 2 linhas; - Não possui Linha 360º; - Temperatura de serviço: -10 40 °C; - Temperatura de armazenamento: -20 70°C; - Gama de autonivelamento: ± 3.5°; - Tempo de nivelamento: 6s; - Rosca do tripé: 1/4"; - Cor da linha laser: vermelho; - Dimensões do produto (AxLxP): 10,4 x 6,4 x 10 cm; - Peso: 0,67 Kg. Componentes incluídos na embalagem: - 1 Nivelador de linhas 12 m compatível com bateria íons de lítio Bosch GLL 12-22 Bosch; - 1 Manual de instruções; - 2 pilhas AA; - 1 Bolsa de proteção.', 469.99, 469.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgxztzp8g740f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1530270722%2F23299140169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997711124', 'Livro Credobatismo | Thomas R. Schreiner e Shawn D. Whigth', 'Thomas R. Schreiner e Shawn D. Whigth Esta obra reexamina o debate sobre o batismo, frequentemente controverso entre cristãos ao longo da história. Enfatizar demais o ato externo do batismo pode levar a distorções, como evidenciado pelo protesto batista contra o sacramentalismo. Por outro lado, certas práticas contemporâneas do batismo “batista” também enfrentam críticas. A recuperação de uma visão robusta do credobatismo pode contrabalançar o minimalismo teológico e o individualismo presentes em muitas igrejas batistas hoje. O batismo é mais do que uma declaração de fé; é um ato sagrado de incorporação à comunidade de fé visível, exigindo uma reforma em nossa prática batismal. Autores: Thomas R. Schreiner, professor de Novo Testamento e pastor na Clifton Baptist Church, é autor de vários livros e artigos. Shawn Wright, professor assistente de História da Igreja e pastor na Clifton Baptist Church, é coautor da obra. Especificações do livro: Título: Credobatismo Subtítulo: Sinal da Nova Aliança em Cristo Autor(es): Thomas R. Schreiner e Shawn D. Whigth Ano de Edição: 2019 Capa: Brochura Acabamento: Laminação Fosca Miolo: Papel Pólen Páginas: 320 Dimensões: Altura: 23 cm Largura: 16 cm Profundidade: 2 cm Peso: 0,460 kg ISBN: 9788552900214 Editora: Schaeffer Editorial', 44.54, 44.54, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lyy1dk1s8sv94e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23997711124', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23417433603', 'Minhas Primeiras Palavras - Profissões | Trilíngue', 'O processo da alfabetização precisa ser construído passo a passo e nada melhor do que percorrer esse caminho de maneira prazerosa e divertida, não é mesmo? Minhas Primeiras Palavras: Profissões é totalmente ilustrado com figuras que estimulam o aprendizado, além de ser trilíngue para enriquecer o vocabulário dos pequenos.', 19.9, 13.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-23010-e653phjuy4lv52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F23417433603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
