INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20959159729', 'Bíblia C. S. Lewis | NVI | Leitura Perfeita | Capa Dura Azul e Dourado', 'Bíblia C. S. Lewis ''A Bíblia C. S. Lewis fornece leituras dos célebres clássicos espirituais de Lewis, incluindo “Cristianismo puro e simples”, “Cartas de um diabo a seu aprendiz”, “O grande divórcio”, “O problema da dor”, “Milagres”, “A anatomia de um luto”, “O peso da glória” e “A abolição do homem", bem como suas cartas e poesias. A leitura de trechos relevantes da obra e das histórias de C. S. Lewis ao lado da Bíblia enriquecerá a meditação diária do leitor nas Escrituras. O que você tem em suas mãos é o trabalho assíduo de muitos estudiosos que, com grande habilidade, reuniram centenas de coisas que Jack [C.S. Lewis] escreveu em “As Crônicas de Nárnia”, ensaios acadêmicos, obras de apologética cristã e até mesmo em cartas para amigos e estranhos, para nos mostrar como até mesmo os cami­nhos tortuosos da vida e da literatura nos levam de volta à Fonte Única e Verdadeira, a Bíblia. - Douglas Gresham Título: Bíblia C. S. Lewis Linguagem: Nova Versão Internacional Capa: Azul e dourado Acabamento: Capa Dura Borda: Artística Índice: Não Harpa: Não Palavras de Jesus em destaque: Não Letra: Leitura perfeita Fitilho: Sim Páginas: 1.728 Dimensões: Altura: 24 cm Largura: 16 cm Profundidade: 5 cm Peso: 1,150 kg ISBN: 9786556893563 Editora: Thomas Nelson', 151.82, 151.82, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22110-8bm7biqz8bjv26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20959159729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297995929', 'Canguru Bublim Baby Liso Detalhe Estampado', 'Canguru Bublim Baby Liso Detalhe Estampado O canguru Bublim é confeccionado com tecido macio e pode ser usado de 03 formas diferentes. Possui acento acolchado, alças ajustáveis e trava de segurança. Modelo liso com detalhes estampados. Confortáveis e práticos, os carregadores canguru são feitos para facilitar o dia a dia na rotina com o bebê. Possui benefícios comprovados como o de permitir que o bebê fique na posição vertical após as mamadas, além de estreitar os vínculos através do calor do corpo. Informações Adicionais: Tamanho: Único Cores: Azul Marinho Referência: 96000009 Marca: Bublim', 96.7, 96.7, NULL, 'Mom & Baby > Baby Travel Essentials > Baby Carrier', 'https://cf.shopee.com.br/file/sg-11134201-7rdvh-m1h3yb917m7z62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22297995929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48013587843', 'Hair Splash Aura Radiante – Perfume Capilar Luminoso', 'Perfume Capilar para Sensação Radiante e Frescor Luminoso O Hair Splash Aura Radiante é um perfume capilar que envolve os fios com uma sensação radiante e luminosa. Sua fórmula oferece um frescor que brilha ao longo do dia, deixando os cabelos com energia e vitalidade. Mantém os fios macios, leves e com aspecto saudável, proporcionando uma aura de luminosidade que complementa perfeitamente a rotina de cuidados capilares. Ideal para quem busca uma perfumação luminosa e energizante, que deixa os cabelos com aroma fresco e radiante, com fórmula livre de parabenos, petrolatos e Cruelty Free. Benefícios Proporciona sensação radiante e luminosa Oferece frescor que brilha ao longo do dia Mantém os cabelos macios e leves sem pesar Contribui para aspecto saudável e vitalizado dos fios Renova a fragrância entre as lavagens Complementa a rotina de cuidados capilares Deixa aroma fresco e energizante nos cabelos Ativos e Benefícios O Hair Splash Aura Radiante combina pantenol e vitamina E com uma fragrância luminosa e energizante. Sua fórmula trabalha no condicionamento dos fios, na manutenção da maciez e na proteção cosmética, oferecendo perfumação radiante que envolve os cabelos. Pantenol Auxilia na hidratação e no condicionamento dos fios, contribuindo para uma sensação de maciez e suavidade ao toque. Ajuda a manter a aparência saudável dos cabelos e melhora a maleabilidade durante o uso. Vitamina E Conhecida por sua ação antioxidante, auxilia na proteção cosmética dos fios contra agressões externas do dia a dia. Contribui para a manutenção do brilho e da aparência saudável dos cabelos. Indicações Indicado para todos os tipos de cabelos. Ideal para quem busca uma perfumação radiante e energizante que renova a fragrância entre as lavagens, mantendo os fios macios, leves e com aspecto saudável e luminoso. Modo de Uso 1. Borrife o produto sobre os cabelos secos ou úmidos, mantendo uma distância de aproximadamente 15 a 20 cm dos fios. 2. Distribua de maneira uniforme por todo o comprimento e pontas. 3. Reaplique sempre que desejar intensificar a perfumação e a sensação de frescor nos cabelos. 4. Não enxágue. 5. Evite aplicar diretamente na raiz. Precauções Uso externo. Manter fora do alcance de crianças. Armazenar em local fresco ao abrigo de luz e calor. Em caso de irritação, suspenda o uso e procure orientação médica. Evite contato com os olhos; caso isto ocorra, enxágue abundantemente com água.', 32.9, 32.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820la-mqngv0s9ezgi7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703142099%2F48013587843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
