INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13175381975', 'Kit com 5 Limpador Diluível Ajax Fresh 1L Cada', 'Furação de Limpeza Profunda e Sem Agressão - Brilho intenso sem resíduos Ajax Fresh Limpeza Pesada é indicado para limpeza geral de pisos, azulejos, vidros, cerâmicas e superfícies laváveis. Proporciona uma limpeza profunda sem agredir as superfícies e deixa sua casa com um agradável cheirinho de limpeza. Tem um rendimento incrível pois é diluível em água. Quer saber como usar? É fácil: Dilua 2 tampas e meia do produto em 5 litros de água. Umedeça o pano e passe sobre as superfícies a serem limpas. Se a limpeza é pesada, pode-se utilizar puro com um pano úmido na remoção de manchas e sujeiras mais difíceis. 1L – Rende até 60 litros.', 126.89, 126.89, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rdvv-m0knxyuqz7f2f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F13175381975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18035138031', 'Kit com 2 Limpador Diluível Pinho Sol Limpeza Pesada Eucalipto 1L Cada', 'Kit Contém: 2 Limpador Diluível Pinho Sol Limpeza Pesada Eucalipto 1L Cada O novo limpador Pinho Sol Limpeza Pesada Eucalipto 1 L é um multi-limpador feito para limpar profundamente todo o tipo de sujeira na sua casa. Isso porque a sua nova fórmula avançada facilita a limpeza, remove as manchas mais difíceis e desengordura, além de deixar um cheirinho delicioso por 8 horas. É a sua casa muito mais limpa, brilhante e protegida com um produto tão poderoso quanto você! Benefícios para você: Esse limpador Pinho Sol Limpeza Pesada Eucalipto limpa profundamente todo o tipo de sujeira na sua casa. Além disso, é um limpador que remove manchas. E você também conta pode contar: o Pinho Sol Limpeza Pesada Eucalipto desengordura. E perfuma os ambientes. Também protege a sua casa. – Para limpeza pesada utilize puro com um pano úmido na remoção de manchas e sujeiras mais difíceis. Disponível nos tamanhos: 1L e 500ml.', 50.19, 50.19, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7qvg2-lguszsp0dbt307', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F18035138031', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
