INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259663303', 'Gelatina em Pó sabor Tutti-Frutti Dr.Oetker', 'A Gelatina em Pó Dr. Oetker sabor Tutti-Frutti é uma sobremesa deliciosa e refrescante, perfeita para qualquer ocasião. Com vitamina C em sua composição, é uma opção saudável e saborosa para toda a família. Para preparar, basta dissolver o conteúdo do pacote em água fervente, adicionar água fria ou gelada e levar à geladeira até adquirir consistência.', 2.79, 2.79, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261u-mj72o9fvfymb11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554945%2F58259663303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
