INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18175995080', 'Kit Lixeira Bold 6L Preto + Escova Sanitária - Ou', 'Lixeira Bold 6L Preto - Ou Com capacidade de 6 litros e fabricada em material resistente (PP). A lixeira Bold é a escolha perfeita para quem busca um design minimalista e moderno. Com bordas arredondadas e acabamento fosco, ela se integra perfeitamente a qualquer ambiente. Além de ser esteticamente atraente, a lixeira Bold é prática e fácil de limpar, tornando-se uma escolha inteligente para sua casa ou escritório. Especificações Marca: Ou Altura: 22cm Largura: 20cm Profundidade: 20cm Escova Sanitária Bold Preto - Ou A escova sanitária Bold combina estilo e funcionalidade. Ela foi pensada e desenvolvida para uma limpeza eficiente e também para manter o seu banheiro sempre higiênico e agradável. Fabricada em material resistente PP + NYLON, com bordas arredondadas e design minimalista, ela ainda deixa o seu banheiro mais bonito. Especificações Marca: Ou Altura: 35cm Largura: 10cm Profundidade: 10cm', 107.9, 89.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-23030-g882whzb6oovd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F18175995080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493564216', 'Regata Básica Masculina Cava Ajustada Em Algodão', 'Regata masculina em algodão 100% para o dia a dia que apresenta a modelagem Tradicional, com caimento confortável e de corte reto e amplo ao corpo, é uma peça para todas as ocasiões. Também contando com decote redondo e cavas ajustadas. Além disso, ela foi feita em tecido 100% algodão, de toque suave garantindo aspecto natural, conforto e muita versatilidade de uso. É Um clássico da moda e presente no guarda-roupa de todos os brasileiros! Ideal para usar com bermuda em jeans Malwee e tênis slip on. • Regata Masculina • Modelagem Tradicional • Alças Largas • Decote Redondo • Cavas Ajustadas • Feita em 100% Algodão • Situação de Uso: Casual e Dia a Dia', 55.9, 50.31, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rfht-m358newsa96eb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F22493564216', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
